quests[25133] = { id = 25133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bericht erstatten in Sen'jin", description = "Eure Prüfungen gegen die Brennende Klinge sind beendet... jedenfalls hier im Tal. Ich möchte aber, dass Ihr von Euren Funden berichtet.\n\nBegebt Euch in das Trolldorf Sen'jin und sucht nach Meister Gadrin. Sen'jin liegt östlich hinter dem Tal und dann geht es an der Weggabelung nach rechts.\n\nBerichtet Gadrin von der Brennenden Klinge und dass sie das Tal der Prüfungen erreicht haben. Bringt von ihm in Erfahrung, ob sie Sen'jin schon erreicht haben.\n\nGeht, {name}, und beeilt Euch. Ich fürchte, dass das Böse, das wir im Koven der Brennenden Klinge entdeckt haben, nur der Vorbote eines viel größeren Übels ist...", sourceObjective = "Sprecht mit Meister Gadrin in Sen'jin.", completion = "Hm, Euer Bericht kommt zu einem denkbar schlechten Zeitpunkt. Die Brennende Klinge lässt sich hier in Sen'jin nicht mehr blicken, aber wir werden gut aufpassen, dass sie nicht noch einmal in diesem Gebiet Fuß fassen.\n\nDie Orcs sind Freunde der Dunkelspeertrolle. Ehrenhafte Freunde. Wir würden den Orcs gern helfen, aber... wir brauchen selbst Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[25134] = { id = 25134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lazy Peons", description = "Verfluchte Peons! Sie arbeiten ja hart daran, Holz aus den Bäumen im Tal zu gewinnen, aber sie machen ständig Nickerchen! Ich brauche jemanden, der dabei hilft, die Peons auf Zack zu halten.\n\nIhr seht wie geschaffen für meinen Auftrag aus, {race}. Hier, Ihr nehmt jetzt diesen Totschläger und lasst ihn auf allen faulen Peons tanzen, die Ihr bei der Arbeit schlafend vorfindet. Ein ordentlicher Schlag wird sie schnell wieder an die Arbeit bringen! Bringt mir den Totschläger wieder, wenn Ihr fertig seid.\n\nHaltet unter den Bäumen im Tal nach ihnen Ausschau. Verdammte faule Peons...", sourceObjective = "Benutzt den Totschläger des Großknechts an 4 faulen Peons, wenn sie schlafen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25135] = { id = 25135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thazz'rils Hacke", description = "{name}, Ihr seid <ein/eine:r> {race}, auf <den/die:r> man sich verlassen kann. Würdet Ihr wohl eine weitere Aufgabe für mich erledigen?\n\nVor einiger Zeit suchte ich in einer Höhle im Norden nach Mineralien und vergaß dort meine Lieblingshacke. Als ich später dorthin zurückkehrte, hausten tückische Bestien in dieser Höhle! Würdet Ihr diese Höhle aufsuchen, es ist der Koven der Brennenden Klinge, und meine Hacke holen?\n\nIch habe sie in einer Kammer mit Wasserfällen gelassen. Meine Hacke ist verzaubert, daher könnt Ihr sie im Dunkeln sehen und müsst Euch keine Sorgen machen, wie Ihr sie findet... nur diejenigen, die sie bewachen, müsst Ihr fürchten!", sourceObjective = "Bringt Thazz'rils Hacke zu Großknecht Thazz'ril.", progress = "Habt Ihr den Koven der Brennenden Klinge betreten, {name}? Und habt Ihr meine Hacke gefunden?", completion = "Prima, Ihr habt sie! Vielen Dank, {name}. Das ist meine Lieblingshacke! Wenn meine Peons irgendwann einmal fertig sind, diese Bäume zu fällen, finden wir vielleicht eine hübsche Höhle für den Bergbau!", sourceObjectiveStatus = "unverified-source-field" }
quests[25136] = { id = 25136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Galgars Kaktusapfel Surprise", description = "Hier im Tal der Prüfungen wird es ganz schön heiß.\n\n<Galgar wischt sich den Schweiß von der Stirn.>\n\nWenn ich doch nur ein paar Kaktusäpfel hätte, dann könnte ich meinen berühmten Kaktusapfel Surprise machen! Nichts kühlt einen schneller ab als ein Stück dieser leckeren Spezialität.\n\nIch sag Euch was, {name}. Wenn Ihr mir sechs Kaktusäpfel bringt, dann mache ich Euch ein paar Portionen Kaktusapfel Surprise, die Ihr mit auf Eure Abenteuer nehmen könnt. Falls Ihr daran interessiert seid, findet Ihr Kaktusäpfel bei den Kaktuspflanzen, die hier in der Gegend wachsen.", sourceObjective = "Sammelt 6 Kaktusäpfel.", progress = "Habt Ihr schon genug Kaktusäpfel eingesammelt?", completion = "Wunderbar, {name}! Wie versprochen, habt Ihr hier Euren Kaktusapfel Surprise - und noch ein bisschen was dazu.", sourceObjectiveStatus = "unverified-source-field" }
quests[25137] = { id = 25137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tal der Prüfungen: PRK - H - Warlock Pet Imp", description = "Die Hexenmeister, die vor uns hier waren, haben sich das Misstrauen der Horde verdient. Wir werden zwar geduldet, aber nicht gemocht.\n\nDas hat die Hexenmeister aber dennoch nicht näher zusammenrücken lassen, denn viele leben lieber zurückgezogen und versuchen sich alleine an ihrer Magie. Ich bin nicht darauf aus, Euch auf den ein oder anderen Pfad zu schicken, ich möchte Euch nur helfen, reifer zu werden.\n\nBevor ich Euch die Kunst des Herbeirufens lehre, bringt mir sechs Köpfe von schändlichen Familiaren aus der Höhle im Nordosten.Ihr erlernt:", sourceObjective = "Bringt 6 Köpfe eines schändlichen Familiars zu Ruzan.", sourceObjectiveStatus = "unverified-source-field" }
quests[25138] = { id = 25138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glyphenpergament", description = "Ah, während Ihr weg wart, ist ein Pergament für Euch gekommen, {name}.\n\nLest es, wenn Ihr die Zeit habt. Wenn ich mich nicht irre, kommt es von Magierlehrerin Acrypha. Sie möchte mit Euch reden, wenn Ihr bereit seid.", sourceObjective = "Lest das Glyphenpergament und sprecht mit Acrypha im Tal der Prüfungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25139] = { id = 25139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuverlässiger Schuss", description = "Ihr wisst bereits, wie man einen arkanen Schuss abfeuert. Gut. Aber wenn Ihr das tut, sinkt Euer Fokus. Um Fokus zurückzugewinnen, müsst Ihr zu einem anderen Fernangriff übergehen.\n\nGeht, sammelt mehr Erfahrung. Wenn Ihr das tut, erlernt Ihr einige neue Fähigkeiten. Die erste wird Euch helfen, Fokus zurückzuerlangen.", sourceObjective = "Erreicht Stufe 3, um 'Zuverlässiger Schuss' zu erlernen. Findet eine Trainingsattrappe und übt daran fünfmal den zuverlässigen Schuss.", sourceObjectiveStatus = "unverified-source-field" }
quests[25140] = { id = 25140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schweinejagd", description = "Ein Stück südlich von diesem Dorf findet Ihr ein junges Schwein namens Lo'shall. Er versteckt sich zwischen den Kakteen und Bäumen. Er ist zwar klein, doch seine Größe täuscht über eine Intelligenz hinweg, die den meisten Schweinen fehlt.\n\nFindet ihn, reißt ihm eines seiner Haare aus und bringt es mir.\n\nErinnert Euch daran, was ich Euch beigebracht habe, {name}. Das Aufspüren von Tieren wird sich hier als nützlich erweisen.", sourceObjective = "Reißt Lo'shall ein Haar aus. Ihr solltet vielleicht \"Wildtiere aufspüren\" verwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25141] = { id = 25141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausweiden", description = "Fangen wir mit den Grundlagen an, ja? Ich bin der einzige Schurkenlehrer hier, also werdet Ihr von mir lernen müssen.\n\nGeht, sammelt mehr Erfahrung, findet heraus, wie Ihr Eure Gegner ausweiden könnt und zeigt es mir dann an den Trainingsattrappen hier. Ich werde Eure Leistung dann bewerten.", sourceObjective = "Erreicht Stufe 3, um 'Ausweiden' zu erlernen. Findet eine Trainingsattrappe und übt daran dreimal die Anwendung von 'Ausweiden'.", sourceObjectiveStatus = "unverified-source-field" }
quests[25142] = { id = 25142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Schatten", description = "Ich will sehen, wie Ihr versucht, an mir vorbeizuschleichen. Ich werde immer noch in der Lage sein, Euch zu entdecken, da Ihr immer noch ein Neuling seid. Also versucht keine komischen Sachen. Ich möchte nur sehen, was Ihr gelernt habt.", sourceObjective = "Benutzt Eure Fähigkeit 'Verstohlenheit' in Rwags Nähe im Tal der Prüfungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25143] = { id = 25143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urtümlicher Schlag", description = "Während Ihr Kraft durch das Erklimmen neuer Stufen erlangt, werdet Ihr Macht erkennen, mit der Ihr neue Fähigkeiten nutzen könnt. Die erste dieser Fähigkeiten, die Ihr auf Eurer Reise entdeckt, ist der 'Urtümliche Schlag'.\n\nSetzt ihn ein, um mit Eurer Waffe einen Schlag zu führen, der mit der Macht der Elemente erfüllt ist.\n\nEs ist Zeit, Eure neue Fähigkeit zu erlernen und sie zu meistern. Übt an einer der Trainingsattrappen vor der Höhle.", sourceObjective = "Erreicht Stufe 3, um 'Urtümlicher Schlag' zu erlernen. Findet eine Trainingsattrappe in Shikriks Nähe und übt daran dreimal die Anwendung von 'Urtümlicher Schlag'.", sourceObjectiveStatus = "unverified-source-field" }
quests[25144] = { id = 25144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stein trifft Fleisch", description = "Die Anführer des Dorfes haben menschliche Invasoren gefasst, die versuchten, das Tal zu betreten. Diese Invasoren werden in Käfigen gefangengehalten, in der Höhle im Westen.\n\nIch möchte, dass Ihr diese Fähigkeit auf einen der Invasoren anwendet, {name}. Verzaubert Eure Waffe mit der Macht der Erde, dann greift diese Feinde an!", sourceObjective = "Besiegt einen gefangenen Späher der Nordwacht, während Eure Waffe mit \"Felsbeißer\" verzaubert ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25145] = { id = 25145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbnis", description = "Es ist meine Pflicht, Euch auszubilden und ich gedenke, genau das zu tun.\n\nWenn Ihr mehr Macht erlangt, werdet Ihr die Teufelsstimmen hören, die Euch neue Zauber offenbaren.\n\nGeht, sammelt mehr Erfahrung, erlernt einen neuen Zauber und übt ihn dann an einer der Trainingsattrappen hier.", sourceObjective = "Erreicht Stufe 3, um 'Verderbnis' zu erlernen. Findet eine Trainingsattrappe und wirkt fünfmal 'Verderbnis' auf sie.", sourceObjectiveStatus = "unverified-source-field" }
quests[25146] = { id = 25146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein dämonisches Feuer", description = "Die Anführer des Dorfes haben menschliche Invasoren gefasst, die versuchten, das Tal zu betreten. Diese Invasoren werden in Käfigen gefangengehalten, in der Höhle im Westen.\n\nIch möchte, dass Ihr einen dieser Invasoren verbrennt, {name}. Wendet Euren frischgelernten Zauber auf diese menschlichen Hunde an, dann seht sie leiden.", sourceObjective = "Wirkt \"Feuerbrand\" auf einen gefangenen Späher der Nordwacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25147] = { id = 25147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmangriff", description = "Man hat mich angewiesen, Euch auf den Kampf vorzubereiten. Ihr seht allerdings aus, als hättet Ihr schon ein wenig Zeit auf dem Schlachtfeld verbracht. Gut.\n\nWährend Ihr Eure Reise fortsetzt, werdet Ihr erkennen, dass Ihr beginnen könnt, neue Techniken anzuwenden.\n\nGeht, sammelt Erfahrung und bringt Euch selbst den 'Sturmangriff' bei. Zeigt mir dann, was Ihr gelernt habt.", sourceObjective = "Erreicht Stufe 3, um 'Sturmangriff' zu erlernen. Sucht eine Trainingsattrappe und übt die Benutzung von 'Sturmangriff'.", sourceObjectiveStatus = "unverified-source-field" }
quests[25148] = { id = 25148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu Eurem Wort stehen", description = "Unsere Dorfältesten haben menschliche Eindringlinge aufgegriffen, die versucht haben, ins Tal zu gelangen. Diese Eindringlinge sitzen in der Höhle im Westen in Käfigen.\n\nIch möchte, dass Ihr Euren Schlachtruf bei einem dieser Eindringlinge anwendet, {name}. Findet einen gefangenen Späher der Nordwacht, während Ihr unter dem Einfluss Eures Schlachtrufs steht. Kehrt zu mir zurück, wenn Ihr erfolgreich wart.", sourceObjective = "Besiegt einen gefangenen Späher der Nordwacht, während Ihr unter dem Einfluss Eures Schlachtrufs steht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25149] = { id = 25149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostnova", description = "Gut, kommen wir zum einfachen Teil.\n\nAlles, was Ihr tun müsst, um Eure Verbindung zum Arkanen zu vertiefen, ist, erfahrener zu werden und mehr Macht zu erlangen. Dann werdet Ihr feststellen, dass Ihr neue Zauber wirken könnt.\n\nIhr werdet sehen. Geht und probiert es aus und zeigt mir dann, was Ihr erlernt habt.", sourceObjective = "Erreicht Stufe 3, um 'Frostnova' zu erlernen. Findet eine Trainingsattrappe und übt den Zauber 2-mal daran.", sourceObjectiveStatus = "unverified-source-field" }
quests[25150] = { id = 25150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Machterfüllter Geist", description = "Arkane Intelligenz ist ein Zauber, den Ihr auf Euch selbst, Eure Freunde oder sogar auf zufällige Passanten wirken könnt. Solange der Zauber aktiv ist, sollte Euer Geist ein wenig... scharfsinniger sein. Lasst es uns einmal versuchen.\n\nIch möchte, dass Ihr Arkane Intelligenz auf jemanden wirkt. Oder nein, vergesst das. Ich möchte, dass Ihr den Zauber auf MICH wirkt.", sourceObjective = "Wirkt Arkane Intelligenz auf Acrypha.", sourceObjectiveStatus = "unverified-source-field" }
quests[25151] = { id = 25151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Er braucht Bier!", description = "<Marley umklammert mit zitternder, blutiger Hand eine Seite Eures Kopfes.>\n\nBier... Muss... Bier... trinken...\n\nHager-Bschorr von drinnen. <Er hustet.> Das sollte... helfen.", sourceObjective = "Durchsucht Burg Bael'dun nach einem Krug mit Hager-Bschorr und bringt ihn zu Marley Doppelzopf am Eingang.", progress = "<Marley atmet stoßweise und zittert keuchend.>\n\n<Sein Blick ist flehend auf Euch gerichtet.>", completion = "<Ihr rennt mit dem Bier auf Marley zu und seine Augen glitzern. Er ergreift den Krug mit beiden Händen und kippt trinkt gierig. Weißer Schaum quillt über seinen blutverschmierten Bart.>\n\nAh... das ist genau das Richtige. Hager-Bschorr... Ich danke Euch, mein Freund.\n\nDas wird all dies... ein wenig einfacher machen.\n\n<Er hustet ein letztes Mal und bricht über der zertrümmerten Steuerkonsole zusammen. Der halb leere Krug fällt zu Boden und sein Inhalt ergießt sich im Sand. Seine Augen brechen.>\n\n<Marley Doppelzopf ist tot.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25152] = { id = 25152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer Platz in der Welt", description = "Endlich seid Ihr alt genug, {name}... alt genug, um im Namen der Horde zu kämpfen. Um für den Ruhm des Kriegshäuptlings Siege zu erringen.\n\nJa...\n\n<Kaltunk mustert Euch.>\n\nDoch, doch, Ihr eignet Euch.\n\nZweifellos wollt Ihr Euch einen mächtigen Drachen oder einen Dämon suchen und ihn mit bloßen Händen erwürgen, aber vielleicht ist es vernünftiger, wenn Ihr mit etwas weniger... Gefährlichem anfinget.\n\n<Kaltunk lacht.>\n\nMeldet Euch bei Gornek; der sollte Euch eine Aufgabe zuweisen können, die zu einem wie Euch passt, {class}. Er sitzt am Feuer direkt hinter mir.", sourceObjective = "Sprecht mit Gornek.", completion = "Wieder einer von Kaltunks Rekruten, was?\n\nEs ist wirklich schlecht um die Horde bestellt, wenn das das Beste ist, was wir auf die Beine stellen können. Einerlei. Wenn es so weit ist und wir erkennen, dass Ihr bereit seid, das Tal zu verlassen, werdet Ihr ein stolzer Krieger der Horde sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25153] = { id = 25153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bael'duns Rettung", description = "Hilfe! Ihr müsst etwas tun!\n\nEinige Zwerge sind noch drinnen... so viele... gefangen unter den Trümmern. Lebendig begraben. Die Flammen! Es ist ein Alptraum da drinnen. Wir wissen nicht, wie lange es noch dauert, bis das Dach einstürzt.\n\nBitte, {class}, Ihr müsst sie retten!\n\nRennt hinein. Benutzt die Notfallfeuerventile, um Euch vor den Flammen zu schützen. Ihr seid ihre einzige Hoffnung!", sourceObjective = "Begebt Euch in die Burg Bael'dun und rettet 10 Überlebende von Bael'dun aus den Trümmern.\n\nBenutzt die Notfallfeuerventile, um Euch vor den Flammen zu schützen.", completion = "Ihr seid eine Legende, {name}.\n\nDie anderen Überlebenden und ich werden noch Jahre von Euren Taten erzählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25154] = { id = 25154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für Lila", description = "Ich versuche diese Handelsschiffskapitänin, Lila, zu beeindrucken. Ich habe an einer Halskette gearbeitet, die zu ihren wunderschönen violetten Haaren passt, aber die Edelsteine sind verschwunden! Sie waren hier, als ich sie gestern Abend meinem guten Freund Curver gezeigt habe. Wir haben Fusel getrunken und ich bin bewusstlos geworden - als ich wach wurde, waren die Edelsteine weg! Das müssen verdammt raffinierte Diebe gewesen sein, Curver hat nämlich nichts gesehen.\n\nIhr Schiff kommt heute Abend an und ich brauche dringend drei Nachtsteine, um ihr Geschenk zu vollenden. So helft mir doch!", sourceObjective = "Schleift drei zeitlose Nachtsteine und gebt sie Isabel Jones in Sturmwind.", progress = "Habt Ihr mir die Nachtsteine gebracht?", completion = "Danke! Ich bin sicher, dass ich diese Marith Lazuria aus Orgrimmar damit schlagen kann! Ich kann gar nicht abwarten, den Blick in ihrem schönen Auge zu sehen, wenn ich es ihr gebe.", sourceObjectiveStatus = "unverified-source-field" }
quests[25155] = { id = 25155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogermazonen in Stimmung", description = "Ich sollte heute eine Ladung Jaspis von Azeroth Express erhalten, aber ich habe gerade gehört, dass ihr Schiff auf einer winzigen Insel namens Ogerzonien aufgelaufen ist. Ich mache mir Sorgen um die Besatzung, da die gigantischen weiblichen Oger auf der Insel, wenn man den Gerüchten Glauben schenkt, entsetzliche Rituale an Männern durchführen, die auf ihre Insel stoßen. Meine Arbeit muss aber fortgeführt werden und wir brauchen diese Edelsteine. Ich habe viel über Eure Fertigkeiten als Juwelenschleifer gehört - könntet Ihr mir vor Ende des Tages drei gezackte Jaspise bringen?", sourceObjective = "Schleift drei gezackte Jaspise und gebt sie Isabel Jones in Sturmwind.", progress = "Habt Ihr mir die Edelsteine gebracht, die ich brauche?", completion = "Eure Arbeit ist so gut, wie man es sich erzählt!", sourceObjectiveStatus = "unverified-source-field" }
quests[25156] = { id = 25156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementarglibber", description = "Statt der gewöhnlichen alten Methode, Edelsteine in Ringe und dergleichen einzusetzen, benutze ich eine innovative neue Methode. Ich klebe die Steine einfach mit Barnsworths Elementarkleber an! Der Professor braucht jedoch mehr Elementarglibber für eine weitere Ladung, und ich muss heute noch viele Edelsteine einsetzen. Könnt Ihr mir welchen besorgen?", sourceObjective = "Besorgt 10 Elementarglibber von beliebigen Cataclysm-Elementaren und bringt sie zu Isabel Jones in Sturmwind.", progress = "Habt Ihr mir den Elementarglibber mitgebracht?", completion = "Danke. Ähm. Legt sie da hinten hin. Ich muss mir etwas einfallen lassen, wie ich meine Hand von diesem Glas löse.", sourceObjectiveStatus = "unverified-source-field" }
quests[25157] = { id = 25157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Schrei!", description = "Professor Barnsworth arbeitet gerade an diesem neuen Sternenstaub. Da diese Saison in Sturmwind alles angesagt ist, was glitzert, bin ich mir sicher, dass man ihn uns auf dem Markt praktisch aus der Hand reißen würde. Aber der Juwelenschleiferverband erlaubt uns nicht, das Zeug unter die Leute zu bringen, bis wir ein paar Tests an humanoiden Lebewesen vorgenommen haben. Sie brabbeln irgendwas von Gefahren bei der Handhabung von magischem Staub und allerlei anderen Unsinn. Nun, ich schätze, wir müssen sie irgendwie bei Laune halten. Nehmt diese Tasche und testet den Sternenstaub No. 2 an humanoiden Testobjekten.", sourceObjective = "Testet den Sternenstaub No. 2 an 10 \"humanoiden Testobjekten\".", completion = "Was ist passiert? Wir sind ruiniert! Hmm. Nun, wenn man es genau nimmt... Vielleicht kann der Professor eine andere Verwendung dafür finden?", sourceObjectiveStatus = "unverified-source-field" }
quests[25158] = { id = 25158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nibbler! Nein!", description = "Lilas Haustier Nibbler ist schon wieder in meine Werkstatt gelangt!\n\nIch war dabei, einen Armreif herzustellen und er sollte heute geliefert werden. Die Arbeit war fast beendet, bis auf ein paar Edelsteine. Ich habe die ganze Nacht damit zugebracht, sie zu schleifen, doch als ich kurz vor die Tür gegangen bin, um zu frühstücken, ist das kleine Biest in die Werkstatt gekommen und hat jeden Edelstein in Reichweite geschluckt! Das Ding kann ALLES verdauen und glaubt mir, Ihr würdet Euch den Rücken brechen bei dem Versuch, seine Hinterlassenschaften aufzusammeln.\n\nIch brauche schnell Ersatzedelsteine; der Kurier kommt heute Abend. Hilfe!", sourceObjective = "Schleift drei gediegene Zephyrite und gebt sie Marith Lazuria in Orgrimmar.", progress = "Habt Ihr mir die gediegene Zephyrite gebracht, die ich brauche?", completion = "Ihr habt mir wirklich die Haut gerettet, {name}. Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[25159] = { id = 25159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Schrei!", description = "Dr. Vernstrom arbeitet gerade an diesem neuen Sternenstaub. Da diese Saison in Orgrimmar alles angesagt ist, was glitzert, bin ich mir sicher, dass man ihn uns auf dem Markt praktisch aus der Hand reißen würde. Aber der Juwelenschleiferverband erlaubt uns nicht, das Zeug unter die Leute zu bringen, bis wir ein paar Tests an \"lebenden Organismen\" vorgenommen haben. Sie brabbeln irgendwas von Gefahren bei der Handhabung von magischem Staub und allerlei anderen Unsinn. Nun, ich schätze, wir müssen sie irgendwie bei Laune halten. Nehmt diese Tasche und testet den Sternenstaub No. 2 an humanoiden Testobjekten.", sourceObjective = "Testet den Sternenstaub No. 2 an 10 \"humanoiden Testobjekten\".", completion = "Was ist passiert? Wir sind ruiniert! Hmm. Nun, wenn man es genau nimmt... Vielleicht kann der Doktor eine andere Verwendung dafür finden?", sourceObjectiveStatus = "unverified-source-field" }
quests[25160] = { id = 25160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für Lila", description = "Ich versuche diese Handelsschiffskapitänin, Lila, zu beeindrucken. Ich habe an einer Halskette gearbeitet, die zu ihren wunderschönen violetten Haaren passt, aber die Edelsteine sind verschwunden! Sie waren hier, als ich sie gestern Abend meinem guten Freund Curver gezeigt habe. Wir haben Fusel getrunken und ich bin bewusstlos geworden - als ich wach wurde, waren die Edelsteine weg! Das müssen verdammt raffinierte Diebe gewesen sein, Curver hat nämlich nichts gesehen.\n\nIhr Schiff kommt heute Abend an und ich brauche dringend drei Nachtsteine, um ihr Geschenk zu vollenden. So helft mir doch!", sourceObjective = "Schleift drei zeitlose Nachtsteine und gebt sie Marith Lazuria in Orgrimmar.", progress = "Habt Ihr mir die Nachtsteine gebracht?", completion = "Danke! Ich bin sicher, dass ich diese Isabel Jones aus Sturmwind damit schlagen kann! Ich kann gar nicht abwarten, den Blick in ihrem schönen Auge zu sehen, wenn ich es ihr gebe.", sourceObjectiveStatus = "unverified-source-field" }
quests[25161] = { id = 25161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogermazonen in Stimmung", description = "Ich sollte heute eine Ladung Jaspis von Azeroth Express erhalten, aber ich habe gerade gehört, dass ihr Schiff auf einer winzigen Insel namens Ogerzonien aufgelaufen ist. Ich mache mir Sorgen um die Besatzung, da die gigantischen weiblichen Oger auf der Insel, wenn man den Gerüchten Glauben schenkt, entsetzliche Rituale an Männern durchführen, die auf ihre Insel stoßen. Meine Arbeit muss aber fortgeführt werden und wir brauchen diese Edelsteine. Ich habe viel über Eure Fertigkeiten als Juwelenschleifer gehört - könntet Ihr mir vor Ende des Tages drei gezackte Jaspise bringen?", sourceObjective = "Schleift drei gezackte Jaspise und gebt sie Marith Lazuria in Orgrimmar.", progress = "Habt Ihr mir die Edelsteine gebracht, die ich brauche?", completion = "Eure Arbeit ist so gut, wie man es sich erzählt!", sourceObjectiveStatus = "unverified-source-field" }
quests[25162] = { id = 25162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementarglibber", description = "Statt der herkömmlichen Methode, Edelsteine in Ringe zu fassen und so weiter, benutze ich eine innovative neue Methode. Ich klebe die Edelsteine einfach mit Vernstroms Elementarkleber an! Der Doktor braucht jedoch mehr Elementarglibber für eine weitere Ladung und ich muss eine Menge Steine einfassen. Könnt Ihr mir welchen besorgen?", sourceObjective = "Besorgt 10 Elementarglibber von beliebigen Cataclysm-Elementaren und bringt sie zu Marith Lazuria in Orgrimmar.", progress = "Habt Ihr mir den Elementarglibber mitgebracht?", completion = "Danke. Ähm. Legt sie da hinten hin. Ich muss mir etwas einfallen lassen, wie ich meine Hand von diesem Glas löse.", sourceObjectiveStatus = "unverified-source-field" }
quests[25163] = { id = 25163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer war das?", description = "Sabotage! Es gibt keine andere Möglichkeit. Das ganze Munitionslager der Burg ist explodiert. Die Horde muss jemanden hineingeschmuggelt haben...\n\n{class}, wenn Ihr den Mumm habt, in den brennenden Alptraum zu laufen... sucht nach Hinweisen, wer uns das angetan hat. Der General wird es wissen wollen! Sucht nach einer Leiche der Horde in den Trümmern und geht dieser Katastrophe auf den Grund...", sourceObjective = "Sucht in Burg Bael'dun nach einer Leiche der Horde.", completion = "<Eine qualmende Leiche ist besonders auffällig in diesem Gemetzel. Der tote Goblin hält einen Bauplan der Burg mit seiner leblosen Hand umklammert...>\n\n<Die Goblins des Bilgewasserkartells. Sie stecken dahinter!>", sourceObjectiveStatus = "unverified-source-field" }
quests[25164] = { id = 25164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Ecke gedrängt", description = "Die Naga sind da, {class}! Helft uns dabei, sie abzuwehr'n!", sourceObjective = "Verteidigt das Lager des Irdenden Rings, bis die Naga sich zurückziehen.", completion = "Ich bin froh, dass Ihr hier wart, Mann.\n\nToshe sieht aus, als will er sie verfolg'n. Ihr solltet ihn'n helf'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[25165] = { id = 25165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Große Haken und Lächeln sollten Misstrauen hervorrufen", description = "Als Nächstes werden wir Gift von den Skorpionen holen, die hier überall herumrennen. Aber keine Sorge, Bom'bay passt auf, dass Euch nichts passiert!\n\nBom'bay hat ein großes Totem, das Ihr in den Boden stecken könnt, wenn der Skorpion angreift. Das Totem entzieht ihm das Gift, und Ihr lauft ganz normal und gesund wieder heim. Klingt das gut?", sourceObjective = "Erhaltet 6 Proben Skorpidtoxin, indem Ihr das Totem der Giftextraktion in der Nähe eines rasselnden Skorpids aufstellt.", progress = "Habt Ihr das Juju?", completion = "Ja! Auf dieses Skorpidjuju hat Bom'bay gewartet! Jetzt machen wir Euch auch wieder heil, {class}.\n\nIhr kommt wieder zu Bom'bay, wenn Ihr Euch besser fühlen wollt. Bom'bay hat Zauber, die Euch gesund machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25166] = { id = 25166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapitän Schreckensbart", description = "Das macht wirklich Spaß, aber wir dürfen nicht vergessen, dass wir für Gnomeregan hier sind!\n\nWir haben den Kapitän der Südmeerfreibeuter auf einem seiner Boote südlich von hier entdeckt, dort, wo die Kämpfe stattfinden. Er ist ganz alleine und ungeschützt auf seinem kleinen Boot!\n\nWenn Ihr Euch um ihn kümmert werden wir den Rest der Piraten in Windeseile los sein.", sourceObjective = "Tötet Kapitän Schreckensbart.", completion = "Er hat einen Meeresriesen unter Kontrolle gehabt? Wenn wir das weiter untersuchen könnten...\n\nÄh, ich meine natürlich, das ist ja total verrückt! Zum Glück ist er jetzt weg, hurra! Herr Noggenfogger wird so erfreut sein.\n\nUnd hier ist eine nette, große Belohnung für Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[25167] = { id = 25167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ketten durchbrechen", description = "Oh Mann, das is' nicht gut! Überhaupt nicht!\n\nThrall ist in See gestochen, Vol'jin kümmert sich um Sachen auf den Echoinseln und der alte Meister Gadrin wird hiergelassen, um sich um Sen'jin zu kümmern. Und dann? Dann kommen diese Menschen von der Feste Nordwacht und schlagen in unserem Gebiet Lager auf!\n\nZum Glück sind sie eben erst angekommen und noch mit dem Aufbau beschäftigt. Ihr könnt dem alten Gadrin helfen, indem Ihr ihre großen Vorratskisten zerstört und die Arbeiter tötet, die die Kisten schleppen. Ihr findet sie südwestlich von hier.", sourceObjective = "Zerstört 3 Vorratskisten der Nordwacht und tötet 10 Träger der Nordwacht.", completion = "Wir haben ihre bisherigen Anstrengungen nichtig gemacht, aber hier sind sie immer noch. Wir müssen härter gegen sie vorgehen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25168] = { id = 25168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Tal reinigen", description = "Nordwacht ist eine sehr gut verteidigte Festung südwestlich von hier, hinter dem Hafen. Es ist eine strategisch gelegene Festung, die für die Horde bisher schwer einzunehmen ist. Wir können wirklich nicht gebrauchen, dass die Menschen eine neue Nordwacht in Durotar aufsetzen.\n\nFegt durch das Tal im Westen und tötet diese Menschen, {name}. Zeigt ihnen die Macht und Wut von Sen'jin.", sourceObjective = "Besiegt 12 Trupps der Nordwacht am Vorposten der Nordwacht.", completion = "Ein gut geführter Kampf, {class}, doch ich habe Zweifel an unserer Effizienz. Diese Menschen sind immer noch hier.\n\nIhr habt allerdings mehr getan, als man von einem loyalen Mitglied der Horde einfach so verlangen kann. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25169] = { id = 25169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kampf gegen die Aggression der Nordwacht", description = "Diese Menschen westlich von hier sind nicht zum Zelten in Durotar. Die haben andere Pläne, und zwar keine netten! Sie wollen unsere Heimat einnehmen und unsere Schädel auf Piken sehen!\n\nAber nicht mit mir! Nein! Nicht mit Lar! Ich habe Familie hier in Sen'jin und werde verflucht sein, wenn jemand auch nur versuchen will, den Schädel von Tai'tasi auf eine Pike zu piken!\n\nDie Menschen haben ihre Pläne alle aufgeschrieben. Große Schriftrollen, schauen wichtig aus. Die werden wir verbrennen, bevor sie überhaupt erst dazu kommen, etwas Ähnliches zu tun.", sourceObjective = "Zerstört 3 Angriffspläne, die beim Vorposten der Nordwacht gelagert werden.", completion = "Gute Arbeit, richtig heldenhaft! Ihr habt Sen'jin heute gute Dienste geleistet. Ganz Durotar habt Ihr heute gute Dienste geleistet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25170] = { id = 25170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Küstensäuberung", description = "Hey, Ihr da! Bom'bay stellt grad mehr Mojo her! Wollt Ihr ein Schlückchen kosten? Oh, davor muss ich aber eh erst noch ein paar Jujus besorgen!\n\nZuerst braucht Bom'bay was von dem Saft von den Krabbenviechern am Wasser. Oh, zeigt mir Eure Hände!\n\n<Bom'bay betrachtet Eure Hände ganz genau.>\n\nMh, bei Euren Händen braucht Bom'bay fünf Handvoll. Geht schon!", sourceObjective = "Erhaltet 5 Handvoll Kriechersekret.", progress = "Ihr bringt mir die Jujus und ich lasse Euch mein Mojo kosten.", completion = "Ja, Mann, das ist das gute Zeug. Jetzt brauchen wir noch andere Jujus.", sourceObjectiveStatus = "unverified-source-field" }
quests[25171] = { id = 25171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiterreiten", description = "Wir müssen unsere Verbündeten in Klingenhügel benachrichtigen. Die Menschen mögen heute besiegt worden sein, doch morgen werden sie wieder da sein und dann werden wir Hilfe von den Orcs brauchen.\n\nSprecht mit Jhash vor den Toren von Sen'jin. Er wird Euch mit seinen Wölfen nach Klingenhügel bringen. Sie kennen den Weg gut.", sourceObjective = "Sprecht mit Räuber Jhash, um nach Klingenhügel zu gelangen. Sprecht mit Gar'Thok, sobald Ihr angekommen seid.", completion = "Der {race} will, dass wir Hilfe schicken? Pff, das kann er vergessen. Ich habe meine eigenen Menschenprobleme, und selbst die sind gerade meine geringsten Sorgen.\n\nSen'jin liegt zwischen den Echoinseln und dem Tal der Prüfungen. Sicherlich wird der Alte Gadrin genügend junge Krieger finden, die ihm mit dem Einfall der Menschen helfen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[25172] = { id = 25172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindringlinge in unserer Heimat", description = "Ihr seid nicht einfach ein weiterer Grünschnabel - Ihr scheint wirklich <ein/eine:c> {class} zu sein. Gut, denn das ist genau das, was ich brauche.\n\nVersucht, es für Euch zu behalten, denn ich möchte keine Panik verursachen... aber es gibt noch weitere Berichte über Menschen in der Nähe. Das ist eine ungeheuerliche Verletzung des Friedens, den wir mit dieser erbärmlichen Jaina Prachtmeer ausgehandelt haben! Wir können keine Menschen hier in Durotar dulden, erst recht nicht hier im Tal.\n\nIhr findet sie im Süden. Tötet sie schnell, bevor es noch mehr werden.", sourceObjective = "Tötet 7 Späher der Nordwacht.", progress = "Schnell, {name}. Entledigt Euch der Menschen in unserem Tal.", completion = "Schnell und präzise ausgeführt. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25173] = { id = 25173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlimmer geht immer", description = "Burg Tiragarde liegt südöstlich von hier, an der Ostküste Durotars. Ihr seid wahrscheinlich auf Eurem Weg von Sen'jin daran vorbeigekommen. Die Burg ist mir schon seit Langem ein Dorn im Auge.\n\nMenschen aus Kul Tiras haben jahrelang in der Burg gelebt und jeden meiner Versuche, sie zu erobern, abgewehrt. Nach dem Kataklysmus war die Küste zerstört, und die Burg mitsamt allen Menschen verschwunden. Allerdings haben diese Ankömmlinge aus Nordwacht jetzt ihren Platz eingenommen!\n\n<Gar'Thok brüllt angesichts dieser erschwerten Umstände.>", sourceObjective = "Tötet 6 Marinesoldaten der Nordwacht, 6 Heckenschützen der Nordwacht und Leutnant Palliter in Burg Tiragarde.", completion = "Von Eurem Mut wird überall erzählt, {name}. Geschichten über Euren Sieg in Burg Tiragarde werden selbst in Orgrimmar erzählt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25174] = { id = 25174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doppelzopf muss es wissen", description = "<General Doppelzopf wird die Einzelheiten dieses feigen Angriffs wissen wollen. Ihr sammelt die Beweise auf.>", sourceObjective = "Meldet Euch bei General Doppelzopf bei Doppelzopfs Patrouille im Südlichen Brachland.", completion = "Wie bitte? WIE BITTE?!!!\n\nBael'dun liegt in Trümmern? Leichen überall - nein. Nein!\n\n<Ihr beschreibt die Beweise, die Ihr am Ort des Geschehens vorgefunden habt.>\n\nDie Bilgewassergoblins also, ja? Die wollen Streit haben? Denen werden wir zeigen, was es heißt, Teil der Horde zu sein, und ob. Ich werde die Kriegsnarbe mit ihren Leichen füllen. Ich werde die Erde mit ihrem Blut tränken.\n\n<Doppelzopf packt Euch am Kragen.>\n\nGoblins. Werden. Sterben!", sourceObjectiveStatus = "unverified-source-field" }
quests[25175] = { id = 25175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlechte Nachrichten", description = "<Sanft schließt Ihr Marleys Augen.>\n\n<Jemand muss General Doppelzopf mitteilen, dass die Horde seinen einzigen Sohn getötet hat.>\n\n<Dieser Jemand seid Ihr.>", sourceObjective = "Überbringt General Doppelzopf bei Doppelzopfs Patrouille im Südlichen Brachland die schlechte Nachricht.", completion = "<General Doppelzopf schleudert seine Axt in den Schmutz. Seine Stimme ist ruhig, aber sein Körper zittert vor Unglaube und Wut.>\n\nDas war mein Junge, {name}. Mein einziger Junge.\n\nJetzt haben sie es persönlich gemacht, {class}. Persönlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[25176] = { id = 25176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Situation ausnützen", description = "<Hey, Hübscher! Ich bewundere Euren großen, fleischigen, starken Bizeps schon, seit Ihr in die Stadt gekommen seid!/Was schaut Ihr denn> hässliche Schachtel! Ich weiß, wie Ihr durch Klingenhügel stolziert und versucht, mir MEINE Männer auszuspannen!;\n\nHört her, ich habe etwas für Euch zu tun. Ich habe gehört, dass Gar'Thok Euch nach Tiragarde geschickt hat. Während Ihr dort seid, könntet Ihr für mich vielleicht ein paar der verlorengegangenen Sachen von Kul Tiras besorgen?\n\n<Danke, Süßer!/Fragt nicht> wieso. Ihr könnt froh sein, dass ich überhaupt mit Euch rede!;", sourceObjective = "Erhaltet 6 Stücke vom Schatz von Kul Tiras.", progress = "<Gail schnurrt entwaffnend wie ein Kätzchen, als sie Euch sieht.>", completion = "Ihr habt mir den Schatz gebracht! Oh, Ihr seid selber so ein Schatz!", sourceObjectiveStatus = "unverified-source-field" }
quests[25177] = { id = 25177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Strände stürmen", description = "Jetzt sind die Menschen erstmal aus dem Weg und wir können uns um richtig wichtige Sachen kümmern.\n\nDer Kataklysmus hat die Ostküste Durotars äußerst stark mitgenommen. Ihr habt selbst gesehen, was aus Tiragarde geworden ist. Und an der Küste östlich von hier ist das Ausmaß noch weitaus schlimmer.\n\nNach der ersten Schockwelle wurde der Strand von wütenden Elementaren eingenommen, die aus dem Meer kamen. Ich habe Grunzer geschickt, um sich um sie zu kümmern, aber es waren zu viele für sie. Ich habe das Gefühl, dass Ihr mehr Erfolg haben werdet.\n\nNehmt Euch aber vor den Gezeiten in Acht!", sourceObjective = "Tötet 11 schäumende Meereselementare.", completion = "Der Geruch des Meeres haftet an Euch, {name}. Eure Anstrengungen gewähren Klingenhügel einen weiteren Tag.\n\nIch werde bei meinen Vorgesetzten von Euren Taten berichten. Ihr könnt Euch unserer Dankbarkeit sicher sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25178] = { id = 25178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schiffswracks durchsuchen", description = "<Hey, Hübscher, willkommen zurück! Es würde Euch nicht stören, noch einmal für mich aufzubrechen, oder? Ich wäre Euch SOO dankbar.../Ihr da! Halt> diebische Elster! Mit Euch bin ich noch nicht fertig!;\n\nIch habe gehört, dass Ihr zur Küste im Osten unterwegs seid. Am Strand sind unzählige gestrandete Schiffe, und in den Schiffen sind Gnomenwerkzeuge... die kann ich gebrauchen.\n\n<Bis bald, Muskelprotz!/An die Arbeit> Frollein!;", sourceObjective = "Erhaltet 4 Kisten Gnomenwerkzeuge.", progress = "Da ist ja mein Ritter in der glänzenden Rüstung!", completion = "Ihr lest einem Mädchen wie mir wirklich jeden Wunsch von den Augen ab, wisst Ihr das? Wenn Ihr jemals etwas von mir braucht...", sourceObjectiveStatus = "unverified-source-field" }
quests[25179] = { id = 25179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abbau der Verluste", description = "Ihr müsst uns helfen. Die Elementare... sie sind stärker, als man ihnen ansieht, und sie kommen in Massen. Sie haben uns total überrascht und übermannt.\n\nViele meiner Grunzer liegen am Strand im Sterben. Wenn Ihr sie retten könntet... wäre ich Euch so dankbar, und Gar'Thok in Klingenhügel auch!", sourceObjective = "Rettet 4 verletzte Grunzer von Klingenhügel.", completion = "Ich habe schon mit ein paar der Orcs gesprochen, die vom Strand zurückgekehrt sind. Alle haben gesagt, dass Ihr sie gerettet habt.\n\nIhr habt heute eine ritterliche Tat vollbracht, {name}. Lok'tar ogar! Für die Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[25180] = { id = 25180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tafeln der Erde", description = "Vor einiger Zeit schickte Brann König Magni eine eilige Nachricht aus Ulduar. Er sagte, er hätte eine uraltes Titanenversteck mit mysteriösen und bedeutenden Relikten gefunden. König Wrynn sandte eines seiner schnellsten Schiffe nach Nordend, um den Kurier zu transportieren. Ich sollte ihn hier treffen und die Tafeln in Augenschein nehmen, aber der Kurier ist unauffindbar.\n\nMagni macht sich Sorgen, {name}. Ich habe nichts von der Ankunft des Kuriers gehört. Wärt Ihr bereit, zum Hafen von Sturmwind zu reisen, um zu sehen, ob er angekommen ist?", sourceObjective = "Bringt die Tafeln der Erde zu Berater Belgrum in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[25181] = { id = 25181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tafeln des Feuers", description = "Ich erwarte die Ankunft eines Kuriers aus Nordend. Er transportiert eine Sammlung uralter Titanenschätze, von denen ich mir erhoffe, dass sie die Gründe für meine verstörenden Visionen offenbaren. Der Schamane sollte auf einem der letzten Zeppelinflüge angekommen sein, und ich beginne, mir Sorgen zu machen.\n\nEr sollte mich beim Zeppelinturm südwestlich der Tore Orgrimmars treffen, aber ich will meine Audienz mit dem Kriegshäuptling nicht verpassen. Wärt Ihr bereit, nach dem Kurier zu suchen, und herauszufinden was ihn aufhält?", sourceObjective = "Bringt die Tafeln des Feuers zu Erdheilerin Norsala in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[25182] = { id = 25182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet sie alle!", description = "Ich will tote Goblins sehen, {name}! Direkt westlich von hier findet Ihr ein ganzes Nest dieser kleinen Maden, die sich in den Berg graben.\n\nSorgt dafür, dass es ihr eigenes Grab ist, das sie sich graben!\n\nVernichtet sie. Vernichtet diese gesamte gierige Operation. Sie haben in Bael'dun ihren eigenen Untergang besiegelt, {class}. Es ist Zeit, dass sie ihrem Schöpfer gegenübertreten.", sourceObjective = "Tötet 10 Minenarbeiter von Frazzelcraz in Frazzelcraz' Hauptader im Südlichen Brachland.", completion = "Tot? Gut!\n\nMöge die Nachricht von dieser Tat sich schnell verbreiten und mit ihr die Angst.\n\nDie Horde wird die Folgen ihres Angriffs auf Bael'dun schon zu spüren bekommen und den Tag bereuen, an dem sich unsere Wege kreuzten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25183] = { id = 25183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "… und vergrabt die Reste", description = "Sie zu töten reicht einfach nicht. Nach der Katastrophe in Bael'dun will ich, dass diese Goblins ihre eigenen fiesen Machenschaften zu spüren bekommen.\n\nGeht in Frazzelcraz' Mine und macht ein paar Sprengsätze scharf.\n\nAm Eingang der Mine sollte sich eine Art Schalter oder Auslöser befinden. Sobald die Sprengsätze scharf sind, verwendet den Auslöser, um den ganzen Ort in die Luft zu jagen. Versetzt sie in Angst und Schrecken, {class}!", sourceObjective = "Macht 6 Sprengsätze von Frazzelcraz in Frazzelcraz' Hauptader scharf.", progress = "<Vom Auslöser führen ein paar sehr provisorisch aussehende Drähte in die Mine.>", completion = "<Die Sprengsätze sind scharf und bereit!>", sourceObjectiveStatus = "unverified-source-field" }
quests[25184] = { id = 25184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wilder Minenwagenritt", description = "Springt einfach auf und sprecht mit Assistentin Greely, wenn Ihr unten angekommen seid.", sourceObjective = "Reist mit dem Minenwagen an das Ende der Strecke und sprecht mit Assistentin Greely.", completion = "Wie wir hier beim Tüftlerverband sagen würden: Vom atmosphärischen tropfenförmigen Niederschlag in den metallischen Weiterleitungsbehälter am Dachlauf.", sourceObjectiveStatus = "unverified-source-field" }
quests[25185] = { id = 25185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es ist vollbracht", description = "<Ihr schützt Eure Augen vor der Explosion und dem umherfliegenden Geröll, als die Mine einstürzt.>\n\n<General Doppelzopf wird sehr erfreut sein, aber Ihr bezweifelt, dass das seinen Rachdurst stillen kann.>", sourceObjective = "Kehrt zu General Doppelzopf an Doppelzopfs Patrouille im Südlichen Brachland zurück.", completion = "<Doppelzopf nickt, als Ihr die Zerstörung der Mine beschreibt, aber in seinen Augen brennt immer noch kalter Hass.>\n\nSehr gute Arbeit, {name}. Ich schätze, dass es auch strategische Vorteile gibt, der Horde diese Mineralien zu rauben, aber am zufriedensten macht mich, dass diese kleinen grünen Monster zerquetscht wurden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25186] = { id = 25186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zweckloser Widerstand", description = "{name}, ich habe nicht die Absicht, Kommandant Singleton meinen Bericht ohne auch nur das geringste bisschen an guten Nachrichten zukommen zu lassen. Wir müssen der starrköpfigen Horde die Kontrolle über diese Straßen entringen.\n\nSoweit ich weiß, ist ihr Anführer Kona Donnerlauf. Er hat ein Lager direkt nördlich von hier. Er ist im Steinkrallengebirge heimisch und kennt diese Straßen so gut wie seine Westentasche. Wenn wir ihn vernichten können, lässt der Widerstand aus dem Westen möglicherweise nach.\n\nFindet und tötet Kona Donnerlauf, dann meldet Euch bei Kommandant Singleton!", sourceObjective = "Tötet Kona Donnerlauf an der Grenze zwischen dem Steinkrallengebirge und dem Südlichen Brachland.", completion = "Also unsere Vorräte kommen nicht durch? Hmmm. Die Ehrenwacht wird immer mehr isoliert.\n\nDoch der Sieg über Donnerlauf sollte unseren Feinden ein Signal senden, dass wir die Absicht haben, zu bleiben. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25187] = { id = 25187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Fluten verloren", description = "Die Ereignisse, die mit dem Kataklysmus in Verbindung stehen, haben nicht nur ein paar Boote an Land geschwemmt, {name}. Der Südstrom ist über die Ufer getreten und das gesamte westliche Becken Durotars ist unter Wasser.\n\nDort sind noch immer Leute, die Hilfe brauchen. Ich habe schon eine Zeit lang gesucht, konnte aber nichts finden. Würde es Euch stören, selbst zu schauen?", sourceObjective = "Benutzt Thonks Handfernrohr, um in der Südstromaue nach Überlebenden zu suchen.", progress = "Was konntet Ihr sehen?", completion = "Aah, ich verstehe... das KLEINE Ende vom Handfernrohr wird ans Auge gesetzt. Das werd ich mir merken.", sourceObjectiveStatus = "unverified-source-field" }
quests[25188] = { id = 25188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Aue patrouillieren", description = "Mein Posten ist hier, im Turm, und ich kann meinen Posten nicht verlassen, {name}. Ich brauche jemanden, der für mich den Leuten hilft, die nach der Überschwemmung des Flusses Hilfe brauchen.\n\nKann ich mich auf Euch verlassen?", sourceObjective = "Sucht die Südstromaue nach den Leuten ab, die Ihr mit dem Handfernrohr gesehen habt und helft ihnen.", completion = "Ich habe den Trick mit dem kleinen Ende vom Handfernrohr benutzt und Euch beim Hin- und Herrennen da unten zugeschaut. Sehr beeindruckend!\n\nOh, wie habt Ihr die alte Frau zum Fliegen gebracht?", sourceObjectiveStatus = "unverified-source-field" }
quests[25189] = { id = 25189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirits Be Praised" }
quests[25190] = { id = 25190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn Raggarans", description = "Die Stacheleber sind ein Schandfleck in der Landschaft, den nicht einmal der übergetretene Strom wegwaschen kann. Mir wurde gesagt, wir sollen evakuieren, aber das konnte ich nicht, weil ich mit meiner Arbeit noch nicht fertig war.\n\nAaarggggh! Ich hasse Stacheleber so unglaublich arg! Helft Ihr mir, sie zu töten?", sourceObjective = "Tötet 4 Stacheleber der Klingenmähnen und 4 Späher der Klingenmähnen.", progress = "Ich hasse Stacheleber!", completion = "<Raggaran scheint sich ein wenig beruhigt zu haben, seit Ihr ihn das letzte Mal getroffen habt.>\n\nGut, gut. Wir sind schon einen Schritt weiter, diese knopfäugigen, korbtragenden, ebernasigen, zweizehigen...\n\n<Raggarans Zorn nimmt offensichtlich wieder zu.>\n\n...gebückt laufenden, schreienden, stachligen, nichtsnutzigen, Gnome mögenden... AAAAAAARGGGH! Stacheleber!", sourceObjectiveStatus = "unverified-source-field" }
quests[25191] = { id = 25191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begutachtet die Zerstörung", description = "Ich habe von unglaublichen seismischen Anomalien hier in Kalimdor gehört, aber ich hatte keinen Schimmer, dass das geologische Chaos so umfassend ist!\n\nIch benötige eine aktuelle Begutachtung der Zerstörung, während ich hier bleibe und die seismographischen Aufzeichnungen auswerte. Könntet Ihr mit meinem vollautomatischen Feldvermessungsfahrzeug ein paar Daten für mich sammeln? Ich kümmere mich um das Fliegen.\n\nWenn die Vermessung erfolgt ist, zeigt die Daten meinem Kollegen Horton Kardanherz in Nordwacht.", sourceObjective = "Sprecht mit Nibb Spindelgang in Ehrenwacht, um die Zerstörung des Kataklysmus zu vermessen.", completion = "Wie bitte? Seht Ihr nicht, dass wir hier angegriffen werden!\n\n<Kardanherz schnappt sich die Aufzeichnungen aus dem Feldvermessungsfahrzeug und stopft sie willkürlich in eine Art Seesack.>\n\nJa natürlich werde ich mir Nibbs Ergebnisse genau ansehen. Und wenn es nach mir geht, aus der Sicherheit der Östlichen Königreiche heraus!", sourceObjectiveStatus = "unverified-source-field" }
quests[25192] = { id = 25192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raggaran regt sich auf", description = "Ich werde nicht ruhen, bis sie besiegt sind! Tötet sie ALLE!\n\n<Raggaran holt tief Luft.>\n\nIhre stinkenden Behausungen sind nördlich oder südwestlich von hier!", sourceObjective = "Tötet 5 Staubläufer der Klingenmähnen und 5 Schlachtwachen der Klingenmähnen.", progress = "Stacheleber! Tötet sie!", completion = "<Raggaran scheint, sich etwas beruhigt zu haben.>\n\nIhr habt gute Arbeit geleistet.\n\nEs tut mir leid, dass Ihr mich so aufgebracht sehen musstet. Danke, dass Ihr die Stacheleber getötet habt. Vielleicht solltet Ihr besser gehen, bevor ich wieder anfange, mich aufzuregen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25193] = { id = 25193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verloren, aber nicht vergessen", description = "Heute ist der Todestag meines Sohnes Kron. Ich habe es ewig nicht zugeben mögen, aber nun weiß ich, dass er nicht von der Krokiliskenjagd heimkehren wird.\n\nIch habe an etwas gearbeitet... etwas, das Krons Leidenschaft für die Jagd darstellt. Eine Halskette mit Krokiliskenzähnen... Reihe um Reihe von Zähnen; ein Schmuckstück, das nur von dem mutigsten jungen Orc getragen werden kann. Ich werde die Kette auf sein Grab legen.\n\nKron war mutig, aber nicht so stark wie Ihr. Könnt Ihr mir die Zähne für seine Kette besorgen?", sourceObjective = "Sammelt 250 Krokiliskenzähne.", progress = "Kron wird nicht vergessen werden.", completion = "{race}, ich danke Euch. Ich werde sofort an der Kette weiterarbeiten.\n\nVor seinem Tod habe ich für Kron das hier angefertigt. Ich kann damit nichts anfangen, aber Euch könnte es nützlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25194] = { id = 25194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungebetene Gäste", description = "Keine Sorge, Zen'Taji ist nicht in Schwierigkeiten. Hat nur gelernt, was passiert, wenn der Fluss über die Ufer tritt.\n\nSeht Ihr die großen Vögel, da am Flussufer? Zen'Taji glaubt, die sind in Schwierigkeiten. Durch das Erdbeben und die Flut wurden die Ebenenschreiter auf diese Seite des Stroms gebracht, aber sie können nicht zurückfliegen, und schwimmen können sie auch nicht. Sie haben Angst davor.\n\nWenn sie hier bleiben müssen, werden sie sterben. Zen'Taji mag Gewalt nicht, aber vielleicht könnt Ihr sie angreifen, damit sie sich so arg erschrecken, dass sie auf die andere Seite flüchten. Ja?", sourceObjective = "Greift 3 launische Ebenenschreiter an, bis sie in Richtung Brachland fliehen.", progress = "Haut sie einfach ein bisschen. Vertraut Zen'Taji, sie werden fliehen. Es ist echt nicht viel dahinter.", completion = "Hey, ich mag alle Tiere. Ich mag auch große Tiere. Ich mag es nur nicht, wenn Ihr ihnen wehtut... aber es ist ja zu ihrem Wohl.", sourceObjectiveStatus = "unverified-source-field" }
quests[25195] = { id = 25195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende dieses Raptors", description = "Viele Kreaturen starben, als das Wasser in das Tal strömte. Die Raptoren allerdings vermehrten sich und fühlten sich in dieser neu entstandenen Umgebung wohl. Sie sind schlaue Raubtiere und konnten sich vom Unglück anderer Tiere ernähren.\n\nEiner der Raptoren ist besonders grausam. Er tötet die kleinen Tiere und lässt sie im Wasser verrotten - er isst sie nicht mal! Er heißt Hiebkreischer; wenn wir nicht aufpassen, wird er das Gleichgewicht der Natur sehr stören.\n\nReist nach Norden, tötet ihn, und gebt seinen Körper der Natur wieder.", sourceObjective = "Tötet den als Hiebkreischer bekannten Raptor.", progress = "Raptoren waren schon immer sehr anpassungsfähig.", completion = "Zen'Taji glaubt, dass der Kataklysmus bei Hiebkreischer etwas komisches hervorgerufen hat. Er war nicht immer so gewalttätig und irrational.\n\nIch danke Euch für Eure Hilfe, {name}. Zen'Taji wird sich nun weiter seinen Naturstudien widmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25196] = { id = 25196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Blockade von Dranosh'ar", description = "Ihr solltet von hier aus nach Norden reisen, {name}. Sprecht mit Gor dem Vollstrecker bei der Blockade von Dranosh'ar. Er ist mit der Aufgabe beauftragt, die Seestraßen, die nach Orgrimmar führen, zu sichern. Sein Dock ist direkt neben der Knochenhöhle. Ich bin mir sicher, dass er daran interessiert wäre, dort weiterzumachen, wo wir aufgehört haben.", sourceObjective = "Meldet Euch bei Gor dem Vollstrecker bei der Blockade von Dranosh'ar in Durotar.", completion = "Ihr seid derjenige, der sich im Süden im Alleingang um die Brennende Klinge gekümmert hat? Meine Ohren sind überall, mein Junge, und Neuigkeiten reisen schnell.", sourceObjectiveStatus = "unverified-source-field" }
quests[25197] = { id = 25197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Admiral gibt nicht klein bei", description = "Wie bitte? Ihr wollt hierbleiben, um zu kämpfen? Typisch {class}, will bleiben und gegen die Horde kämpfen, wenn man doch noch die Chance hätte, wegzulaufen.\n\nHört zu, wenn Ihr wirklich Nordwacht retten wollt, solltet Ihr Euch bei Admiral Aubrey im Turm hinter mir melden. Egal, wie sehr ich ihn darum bitte, er behält seine Schiffe für den Kampf hier, anstatt uns alle in Sicherheit zu bringen.\n\nWenn Ihr mich jetzt entschuldigen wollt - ich muss noch fertig packen!", sourceObjective = "Meldet Euch bei Admiral Aubrey in der Feste Nordwacht im Südlichen Brachland.", completion = "Ihr habt es gewagt, den ganzen Weg von Ehrenwacht aus hierher zu kommen? Ausgezeichnet, wir können Eure Erfahrung hier brauchen.\n\nSie haben zwar die Mauern durchbrochen, aber Nordwacht wird sich nicht kampflos ergeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25198] = { id = 25198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winnoa Kiefernwald", description = "Obwohl wir hier einiges erreicht haben, wäre es eine Tragödie, wenn ein Teil dieser Verderbnis unserer Aufmerksamkeit entgangen wäre. Die Tunnel der Höhlen des Wehklagens erstrecken sich unter dem gesamten Brachland und wenn noch ein weiterer Punkt ungezähmter Energie sich einen Weg an die Oberfläche gebahnt hat...\n\nIhr habt allerdings genug für mich getan. Ich möchte Euch nur noch darum bitten, einen Druidenfreund von mir wissen zu lassen, was hier geschehen ist. Ihr findet Winnoa Kiefernwald an der Vendettakuppe südwestlich von hier.", sourceObjective = "Sprecht mit Winnoa Kiefernwald an der Vendettakuppe im Südlichen Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[25199] = { id = 25199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grundbefehle", description = "Hey! Ihr seht aus, als könntet Ihr uns helfen!\n\nWenn Ihr bereit seid, unsere Ziele zu unterstützten, müsst Ihr erst die Grundausbildung absolvieren. Gnomenausbildungen sind brutal und rigoros, also hoffe ich, dass Ihr vorbereitet seid!\n\nGeht zu Ausbildungsoffizier Dampfkurbel, und er wird Euch beibringen, was Ihr wissen müsst. Folgt unbedingt seinen Befehlen, wenn er sie erteilt, oder Ihr werdet es nie schaffen!\n\nAber ich warne Euch: es ist hart da drüben. Falls Ihr durchkommt, meldet Euch wieder bei mir.", sourceObjective = "Folgt Ausbildungsoffizier Dampfkurbels Befehlen und meldet Euch dann bei Hauptmann Tret Funkdüse zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[25200] = { id = 25200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schredderangriff", description = "Dieser nichtsnutzige Handelsprinz Gallywix hat es irgendwie geschafft, die gesamte Fußbombenmannschaft der Dampfdruckhaie auf der Yacht unterzubringen. Ich habe keinen einzigen von ihnen zu Gesicht bekommen!\n\nJetzt erledigen sie für ihn die Drecksarbeit hier auf der Rodungsfläche. {name}, Ihr seid <der Held, der/die Heldin> die; für uns den Pokal zurück nach Kezan geholt hat. Ihr müsst sie loswerden!", sourceObjective = "Tötet 8 Dampfdruckhaie.", completion = "Ich kann nicht behaupten, dass ich je ein Fußbombenfan war, aber Ihr bringt mir das Spiel wirklich nahe!", sourceObjectiveStatus = "unverified-source-field" }
quests[25201] = { id = 25201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die ultimative Fußbombenuniform", description = "Schaut, <Kleiner/Kleine>, meine Aufgabe ist, dafür zu sorgen, dass Ihr im Endspiel eine faire Chance habt. Thrall braucht Eure Hilfe im Kampf gegen den Handelsprinzen.\n\nGreely, Hobart und ich haben ein ultimatives Fußbombentrikot zusammengestellt, mit der Ihr das Spiel garantiert gewinnt. Zuerst benötige ich jedoch noch ein paar Dinge.\n\nZu unserem Glück quillt diese Rodungsfläche vor Schredderersatzteilen fast über. Also raus auf den Platz und gebt mir 110%!", sourceObjective = "Sammelt 8 Schredderersatzteile.", progress = "Wollen wir mal sehen, was Ihr da habt, {name}.", completion = "Ja, die eignen sich hervorragend. Gut gemacht, Kleiner. Ich sorge dafür, dass Ihr das beste Fußbombentrikot aller Zeiten bekommt.\n\nIn der Zwischenzeit habt Ihr andere Bomben, die Ihr auf die Lakaien des Handelsprinzen niedergehen lassen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25202] = { id = 25202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schnellste Weg zu seinem Herzen", description = "Oh, <Mann/Mädel>, Ihr werdet nie glauben, wer sich auf der Ölplattform im Norden aufhält.\n\n<Izzy schüttelt traurig den Kopf.>\n\nChip ist da draußen und arbeitet für den Handelsprinzen. Diese kaltherzige Schlange hat Euch wie eine heiße Kartoffel fallenlassen und jetzt arbeitet er auch noch für die anderen. Ich habe sogar gehört, dass da etwas läuft zwischen ihm und Vani LeHörnchen!\n\nIch weiß ja nicht, wie es Euch bei der Sache geht, aber wäre er mein ehemals absolut wirklich echter Freund gewesen, würde ich ihm sein noch schlagendes Herz aus der Brust reißen.", sourceObjective = "Reißt Chip Endale das noch schlagende Herz aus der Brust.", progress = "Wie habt Ihr Euch entschieden? Tod oder Vergebung?", completion = "Er hat nur das bekommen, was er verdient hat. Na, na, nicht weinen. Ihr findet schon einen anderen, der Euch gut behandelt.\n\nHier, lasst mich das nehmen… Wir wollen ja nicht, dass die Leute denken, Ihr wärt verrückt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25203] = { id = 25203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer heißt denn schon Chip?", description = "<Kumpel/Mädel>, Ihr werdet nie glauben, wer sich auf der Ölplattform im Norden aufhält.\n\n<Ass schüttelt ungläubig den Kopf.>\n\nChip ist da draußen und arbeitet für den Handelsprinzen. Dieser Verräter arbeitet für die anderen. Aber es kommt noch schlimmer! Ich habe gehört, dass da etwas läuft zwischen ihm und Vani LeHörnchen!\n\nIch weiß ja nicht, wie es Euch bei der Sache geht, aber wenn er sich an meine ehemals absolut wirklich echte Freundin ranschmeißen würde, würde ich etwas dagegen unternehmen.", sourceObjective = "Tötet Chip Endale.", completion = "Anders kann man es nicht sagen… Er hat einfach genau das bekommen, was er verdient hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[25204] = { id = 25204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gelöstes Problem", description = "Wir müssen Handelsprinz Gallywix' Ölversorgung stoppen und seine Maschinen aufhalten.\n\nIhr müsst für uns zur Ölplattform der HGK gehen und die Ventile lösen, um das Kühlsystem zu überlasten. Geht danach zur Plattformsteuerungskonsole und bringt sie zum Explodieren.", sourceObjective = "Löst die Ventile 1 bis 4.", progress = "Ihr habt noch nicht alle vier Ventile gelöst. Das Kühlsystem der Plattform funktioniert immer noch mit ganz normalen Parametern.", completion = "Alle Leuchten und Anzeigen auf der Steuerungskonsole spielen verrückt!", sourceObjectiveStatus = "unverified-source-field" }
quests[25205] = { id = 25205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wolf und der Kodo", description = "Mein \"Kollege\" hier hat Pläne mit Euch, denen ich nicht zustimmen kann. Er ist hastig, unkontrolliert, unverantwortlich und außerdem bezahlt Ihr am Ende vielleicht auch noch mit Eurem Leben.\n\nBevor Ihr mit Gor sprecht, möchte Ich Euch bitten, Euch die Geschichte anzuhören, die ich zu erzählen habe. Es geht bei der Geschichte um ihre Moral - es ist eine Fabel. Ich glaube aber, dass die Moral dieser Geschichte für Euch sehr wertvoll sein könnte. Sprecht mit mir, wenn Ihr sie hören möchtet.", sourceObjective = "Lauscht der Moral der Geschichte von Shin Steinsäule.", completion = "Die Moral der Geschichte: Voreilige Handlungen, die aus Faulheit getätigt wurden, können ein böses Ende nehmen. Wir sollten den Lauf der Dinge nicht überstürzen... wir müssen uns unsere Belohnungen verdienen. Ich habe versucht, dem Vollstrecker diese Geschichte zu erzählen, aber sein Höllschrei-verehrender Schädel hat sie einfach nicht verstanden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25206] = { id = 25206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Warnungen nicht beachten", description = "Ihr könnt die Worte des Schamanen ignorieren, <Soldat/Soldatin>. Es gibt gewisse Leute in der Horde, die auf unsere Zusammenarbeit bestehen. Ich kann Euch aber versichern, dass dieser Thrall-verrückte Scharfseher nicht einmal über seine eigene Hutspitze sehen kann.\n\nDie Elementare führen westlich von hier miteinander Krieg. Normalerweise wäre mir das egal, aber ich brauche dieses Gebiet, um die Schiffstraße von hier ins Brachland zu vergrößern. Die Elementare sind normalerweise recht stark, aber durch ihre Kämpfe miteinander sind sie geschwächt. Mit diesem Wissen sollte es Euch ein Leichtes sein, sie zu zerstören.", sourceObjective = "Zerstört 12 verfeindete Elementare. Ihr könnt wütende Erdwächter oder belebte Wasserwächter töten.", completion = "Seht Ihr? Die Geschichten des Schamanen sind nicht mehr als... eine Bettgeschichte für einen Jüngling. Die neue Horde nimmt sich, was sie will, und verschwendet mit solchem Schwachsinn nicht ihre Zeit.\n\nFalls Ihr dazu kommt, könnt Ihr ja Shin... und auch allen anderen, die sein Verhalten unterstützen... sagen, dass sie Eure Zeit nicht vergeuden sollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25207] = { id = 25207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht die Plattform platt", description = "Auf der Konsole ist ein einzelner großer, roter Knopf. Wenn es Knöpfe gibt, die große Explosionen auslösen, sehen sie ganz sicher so aus!", sourceObjective = "Drückt den großen roten Knopf auf der Ölplattform der HGK.", completion = "Ich habe die Hitze der Explosionen bis hierher spüren können!", sourceObjectiveStatus = "unverified-source-field" }
quests[25208] = { id = 25208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berichtet Silvia", description = "Es scheint, als haben wir eine Plage gefunden, die um einiges schlimmer ist als die, mit dir wir gerechnet hatten. Cho'gall versucht zweifellos, durch die Gordok Zugang zu den Überresten Eldre'Thalas' in Düsterbruch zu erlangen, ein Ort voller verbotener Mächte, die den Fall von Shen'dralar hervorriefen...\n\nIch schweife zu sehr aus. Geht, {name}. Berichtet Silvia von dem, was ich Euch erzählt habe. Was auch immer in Düsterbruch vor sich geht, muss aufgehalten werden.", sourceObjective = "Sprecht mit Silvia am Turm von Estulan.", completion = "Ihr seid zurückgekehrt. Was hat Estulan gesagt?", sourceObjectiveStatus = "unverified-source-field" }
quests[25209] = { id = 25209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohung durch die Gordunni", description = "In der Oberen Wildnis südlich von hier befinden sich viele uralte Ruinen. An diesem Ort haben die Vorfahren der Nachtelfen sich an der arkanen Magie versucht und die Oger der Gordunni streifen dort umher, um Überreste dessen ausfindig zu machen.\n\nIhr werdet bemerken, dass der Wald dort komplett zerstört wurde; die Oger hinterlassen nichts als Schlamm und entziehen der Horde dadurch wertvolle Ressourcen.\n\nGeht und tötet die Gordunni, {name}. Sichert das Gebiet für die Horde, für die Horde allein!", sourceObjective = "Tötet 16 Oger der Gordunni in der Oberen Wildnis.", completion = "Ihr habt Euch als vertrauenswürdig und verlässlich herausgestellt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25210] = { id = 25210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen des Wandels", description = "Eine üble Krankheit hat die Kreaturen unseres Waldes heimgesucht. Zuerst dachte ich, es wäre einfach eine der Tücken der Natur, aber der Krankheit scheint kein Heilungsprozess zu folgen.\n\nDie Hirsche des Waldes, die normalerweise sehr stark und friedlich sind, haben am meisten gelitten. Einige finden in ihrer Schwäche ihr Ende. Andere sind tollwütig und sehr gefährlich. Um die Geister zu befragen und mehr über die Krankheit in Erfahrung zu bringen, benötige ich die Geweihe der Hirsche.", sourceObjective = "Sammelt 8 infizierte Hirschgeweihe.", progress = "Es ist keine schöne Aufgabe, aber es muss getan werden, {name}.", completion = "Ich danke Euch, {name}. Ich werde die Geweihe untersuchen. Seitdem Ihr Euch auf den Weg gemacht habt, hat sich die Lage verschlimmert.", sourceObjectiveStatus = "unverified-source-field" }
quests[25211] = { id = 25211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Behausung säubern", description = "Hört nicht auf Rharen. Er ist so verwirrt, wie man nur sein kann. Es ist sein Fehler, dass das gesamte Bier erbeutet wurde!\n\nAußerdem bin ich davon überzeugt, dass es hier noch ein größeres Problem als nur gestohlenes Bier gibt. Die Tatsache, dass nach all den Jahren hier eine Gruppe Orcs um Dun Algaz herumrennt ist lächerlich!\n\nIch sag' Euch was, {class}. Ihr geht dort hinein und vertreibt so viele Orcs wie Ihr könnt aus diesen Ruinen. Dun Algaz taugt nicht mehr zu viel, aber ich will verflucht sein, wenn wir sie dort einfach sitzen lassen.", sourceObjective = "Tötet 5 Orcs des Drachenmals in Dun Algaz.", completion = "Das wird ihnen eine Lehre sein! Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25212] = { id = 25212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Am Rande der Schächte", description = "Wir dachten, wir könnten warten, bis die Strahlung um Gnomeregan nachlässt, aber es scheint nicht besser zu werden.\n\nWenn wir unsere Stadt zurückerobern wollen, müssen wir sicherstellen, dass unsere Truppen sie unbeschadet betreten können.\n\nNehmt diese Radiageigatrons, schnappt Euch die Donnerschlag hier und werft sie auf die Lüftungsschächte außerhalb von Gnomeregan. Sie werden die Strahlenbelastung direkt an mich übermitteln.", sourceObjective = "Benutzt Pilot Sprossmündungs Flugmaschine, um Radiageigatrons auf die Luftschächte um Gnomeregan herum zu werfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25213] = { id = 25213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sklavengruben", description = "Der Trainer hat uns gesagt, dass Sassy sich drüben bei den Sklavengruben aufhält. Es sind ein paar Orcs bei ihr, die sich auf einen Angriff auf den Handelsprinzen vorbereiten.\n\n{name}, Ihr solltet die Straße entlang nach Südwesten gehen und sie suchen. Sie möchte ganz sicher, dass Ihr den Angriff leitet!", sourceObjective = "Sprecht mit Sassy Hartzang bei den Sklavengruben.", completion = "Ich habe mich schon gefragt, wo Ihr bleibt!\n\nKeine Sorge. Hobart wird dieses Fußbombentrikot in das ultimativste Fußbombentrikot aller Zeiten verwandeln!", sourceObjectiveStatus = "unverified-source-field" }
quests[25214] = { id = 25214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht nach oben", description = "Wir haben wirklich keine Zeit, um all die zu retten, die so dumm sind, sich immer und immer wieder einfangen zu lassen. Ich habe jedoch noch ein paar Raketen übrig, sodass wir dieses Problem ganz leicht aus der Welt schaffen können.\n\nBringt diese einstufigen Trägerraketen zu den Sklavengruben im Norden und befestigt sie an den Käfigen.\n\nDer Käfig wird abheben, und so können wir diese Idioten im Handumdrehen befreien.", sourceObjective = "Benutzt die einstufigen Trägerraketen, um die Käfige von 8 Bürgern von Kezan oder überlebenden Goblins in die Luft zu schießen.", progress = "Es muss noch mehr Käfige geben, die Ihr von ihren azerothischen Fesseln befreien könnt.", completion = "Ups. Nun ja, runter kommen sie alle.", sourceObjectiveStatus = "unverified-source-field" }
quests[25215] = { id = 25215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ablenkender Geruch", description = "Raubtiere riechen diese toten Naga schon fast aus einer Meile Entfernung. Bald werden wir kämpfen müssen, nur um in die Höhle hinein oder hinaus zu kommen. Wollt Ihr mir nicht helfen, aufzuräumen?\n\nDirekt jenseits des Riffs im Süden findet Ihr die Glimmertiefenschlucht. Wenn Ihr die Leichen vom östlichen Höhlenausgang dorthin schleift und sie im Wasser loslasst, werden die Wildtiere sie beseitigen, noch bevor sie am Meeresgrund angelangt sind. Versucht nur, den Haien so gut wie möglich auszuweichen.", sourceObjective = "Zerrt 3 tote Räuber des Zin'jatar in das offene Meer über der Glimmertiefenschlucht im Süden.", completion = "Es sollte nicht lange dauern, das Wasser zu reinigen. Danke für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[25216] = { id = 25216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Sambino", description = "Falls Ihr Euch auf den Weg hinab in den Graben macht, könntet Ihr mir einen Gefallen tun und nach einem unserer neueren Mitglieder sehen.\n\nSein Name ist Sam, aber er hat die Angewohnheit, seinen Namen ein wenig auszuschmücken. Er hat noch nicht so recht verstanden, was die Mitglieder des Irdenen Rings ausmacht, aber er gibt sich viel Mühe, daher sehen wir es ihm nach.\n\nLasst Euch nicht zu sehr einwickeln, ihm bei seinen verrückten Plänen zu helfen. Schaut einfach nur nach, ob er unversehrt ist und lasst es mich wissen, damit ich beruhigt bin.", sourceObjective = "Sucht nach \"Sam\" am westlichen Ende des Silberflutgrabens.", completion = "Ein weiterer Bewunderer des großen Sambinos! Seid Ihr den ganzen weiten Weg gekommen, damit ich Euch ein Autogramm gebe? Ich bin viel zu beschäftigt, um irgendetwas zu unterschreiben. Hinfort mit Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[25217] = { id = 25217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totemmodifikation", description = "Na gut, weil Ihr mich so verzweifelt anschaut, lasse ich Euch an meiner echten Arbeit teilhaben.\n\nDieser Fels ist noch völlig unerschlossen! Wahrscheinlich schlummern hier größere Reichtümer als in der Schatzkammer eines Handelsprinzen während eines großen Krieges! Ich brauche Proben. Mehr Proben. Proben von überall!\n\nIch habe meine Erdtotems so modifiziert, dass die sich durch den Sand graben und Felsproben aus dem Boden darunter aufnehmen. Geht und sucht einen geeigneten Ort, um eines davon aufzustellen.\n\nDas Zittern und Rumpeln lockt sicher all die süßen, neugierigen Wildtiere an. Da könnt Ihr gleich noch neue Freundschaften schließen!", sourceObjective = "Stellt eines von Sambinos modifizierten Totems im Sand des Silberflutgrabens auf.", completion = "Eine weitere Probe. Ausgezeichnet! Die felsigen Reichtümer des Meeres werden bald mir gehören!", sourceObjectiveStatus = "unverified-source-field" }
quests[25218] = { id = 25218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterwasserinflation", description = "Na gut! Na gut. Ihr habt mich überredet. Ihr dürft mir helfen.\n\nIch verliere mehr Luft als ein mit Stachelebern gefüllter Zeppelin. Mein Luftventil muss sich irgendwo im Graben gelöst haben.\n\nIch habe ein paar Ersatzballons dabei. Macht Euch nützlich und füllt einen auf, ja? Und findet mein Ventil! Das brauche ich natürlich auch.\n\nIch wette, die Krebse haben es gestohlen... Kneifende, gierige kleine Biester...", sourceObjective = "Füllt einen von Sambinos Luftballons und findet das verloren gegangene Luftventil.", progress = "Wenn Luft nur nicht so… luftig wäre! Oder wenn es für diese Wasseratmungszauber wenigstens schicke Helme gäbe! Eines von beidem würde mir schon reichen.", completion = "Wisst Ihr, ich hätte Euch einen Gürtel mit Gewichten geben sollen, damit Ihr nicht einfach mit dem Ballon und allem davontreibt. Zum Glück hattet Ihr ja Eure Rüstung und so an. Ha!", sourceObjectiveStatus = "unverified-source-field" }
quests[25219] = { id = 25219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht verschnecken", description = "Ich untersuche Schnecken.\n\nJa. Schnecken. Wenn Ihr mit Lachen fertig seid, könnt Ihr mir ja vielleicht helfen.\n\nSicher ist Euch die gigantische Schnecke am Riff aufgefallen. Nun, ich bin mir sicher, dass etwas darin steckt. Es gibt dort mehrere Punkte, die eigentlich nur Einmündungen oder Eingänge sein können. Außerdem habe ich gesehen, wie diese Knochenwühler sich dort hinein und hinaus quetschen.\n\nIch dachte, wir können diese Schnecken vielleicht benutzen, um uns selbst Zugang zu verschaffen. Zumindest ist das die Theorie.", sourceObjective = "Sammelt 10 Spiralmuschelknochenwühler.", progress = "Ich weiß, das ist nicht gerade die erstrebenswerteste Aufgabe, aber seid Ihr nicht auch neugierig, was es mit dieser Schnecke auf sich hat? Sie ist so riesig! Da muss doch mehr dahinter stecken.", completion = "Danke. Ehrlich. Wenn noch ein Gestrandeter mich ausgelacht hätte, hätte ich vor lauter Zorn sicher jemanden gemeuchelt.\n\nIch lasse es Euch wissen, sobald mir etwas einfällt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25220] = { id = 25220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glitschige Bedrohung", description = "Wurdet Ihr schon von den Aalen an den Riffen angegriffen? Wenn nicht, dann wird es noch passieren, so viel steht fest. Das sind bösartige, blutdurstige kleine Monster. Und es scheint ihnen auch ganz egal zu sein, wen oder was sie beißen.\n\nWenn Ihr hinaus in das Tal geht, wäre ich Euch sehr dankbar, wenn Ihr ihre Zahl etwas dezimieren würdet. Nicht alle hier sind so gut ausgerüstet wie Ihr. Uns könnten sie vielleicht mehr als nur Kratzer zufügen.", sourceObjective = "Tötet 12 Spitzzahnaale.", completion = "Vielen Dank, {class}. Es gibt immer noch viele größere Raubtiere, auf die wir achten müssen, aber wenigstens sind wir jetzt um die Höhle herum etwas sicherer.", sourceObjectiveStatus = "unverified-source-field" }
quests[25221] = { id = 25221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsjagd", description = "Sie entkommen!\n\nDas sind die gleichen Naga, die die Boote angegriffen und unsere Freunde verschleppt haben. Wir dürfen sie nicht entwischen lassen!\n\nNehmt diese Speere und verfolgt sie auf Eurem Seepferdchen. Verschwendet keine Zeit mit Absteigen. Heftet Euch einfach an ihre Fersen und tötet alle, die Ihr erwischen könnt, mit den Speeren.\n\nIch versuche inzwischen, den Tiefenlord zu stellen. Wenn Ihr fertig seid, sucht mich am Ende des Riffs auf.", sourceObjective = "Benutzt Toshes Jagdspeer, um 20 fliehende Naga des Zin'jatar zu töten.", completion = "Schnelle Arbeit. Sehr beeindruckend.\n\nDieser Tiefenlord ist entkommen. Ich sehe ihn nirgends. Ganz gewiss finden wir über ihn unsere gefangenen Freunde.\n\nIch werde ihn verfolgen. Lange kann er sich nicht verstecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[25222] = { id = 25222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Silberfluthöhle", description = "Ein Großteil des Irdenen Rings, der dem Massaker auf den Booten entkommen ist, hat in einer Höhle nahe dem Riff Zuflucht gefunden. Sie ist gut versteckt in einer riesigen Felsformation westlich von Nespirah, der riesigen Schnecke am Horizont. Bitte geht für mich dorthin und seht nach, ob es ihnen gut geht. Zudem kann es gut sein, dass auch sie unter den Nagaangriffen leiden.\n\nIch werde diesen Tiefenlord jagen. Wenn ich herausgefunden habe, hinter welchem Felsen er sich versteckt, lasse ich es Euch wissen.", sourceObjective = "Sucht nach Felora Feuerkranz in der Silberfluthöhle.", completion = "Ein freundliches Gesicht! Willkommen!\n\nSehr nett von Euch, dass Ihr nach uns seht. Uns geht es gut. Ein Spähtrupp der Naga hat uns gefunden, aber ich bin mir ziemlich sicher, dass keiner entkommen konnte. Wir sollten vorerst in Sicherheit sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25223] = { id = 25223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerprobe", description = "Ich würde ja gerne sagen, dass wir angesichts des wachsenden Widerstands gegen uns auf dem Hyjal für jeden Rekruten dankbar sind, der uns bei unserer Sache unterstützt und so weiter… aber um ganz ehrlich zu sein, sind die meisten von Euch einfach nur eine Last.\n\nWenn ich eine Kupfermünze für jedes Landei bekommen hätte, das vom Kataklysmus so verängstigt wurde, dass es sich uns jetzt unbedingt anschließen möchte... nun, sagen wir einfach, ich wäre eine reiche Frau.\n\nZum Glück haben wir ein paar Prüfungen vorbereitet, mit denen wir die Spreu vom Weizen trennen können. Geht und beweist Euren Wert an den feurigen Instrukteuren da unten. Hoffentlich schlagt Ihr Euch besser als die anderen.", sourceObjective = "Besiegt 8 feurige Instrukteure.", completion = "Ich schätze, Eure Fähigkeiten sind… geeignet. Ich bin beeindruckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25224] = { id = 25224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In voller Blüte", description = "Es ist Brauch, dass neue Rekruten schwierige oder manchmal sogar unmögliche Aufgaben erhalten. Ich wurde losgeschickt, um die Schuppe eines schwarzen Drachen zu beschaffen, der Instrukteur letztes Jahr forderte die Feder eines Phönix'.\n\nIhr habt es dieses Mal vergleichsweise einfach. Besorgt mir eine Handvoll Flammenblüten.\n\nSie wachsen hier in der Gegend relativ zahlreich. Oh, fast hätte ich es vergessen. Damit die Sache interessant bleibt, streift ein gigantischer Kernhund über die Felder. Gebt Euer Bestes, um ihm auszuweichen.", sourceObjective = "Besorgt 5 Flammenblüten.", progress = "Ja, Kiigandamus?", completion = "Also habt Ihr es geschafft, diesen Teil des Tests zu bestehen, ohne von Loderos gefressen oder von den Feuerelementaren in Brand gesetzt zu werden?\n\nIch schätze, dann sollte ich Euch zum Aufstieg in den niedrigsten Rang unserer Hierarchie gratulieren.\n\nAlso: Herzlichen Glückwunsch, Rekrut!", sourceObjectiveStatus = "unverified-source-field" }
quests[25225] = { id = 25225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ölwechsel", description = "Das Schmiermittel in diesen Schreddern ist nutzlos. Was wir brauchen sind ein paar Tropfen gutes altes Kajaroöl 0W!\n\nWisst Ihr, wo Ihr dieses Öl finden könnt? In Öl-Bots der HGK! Und wisst Ihr auch, wo Ihr die finden könnt? Auf der Ölplattform der HGK im Nordwesten!", sourceObjective = "Sammelt 6 Einheiten Kajaroöl 0W.", sourceObjectiveStatus = "unverified-source-field" }
quests[25226] = { id = 25226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet Chip Endale Nachfolgequest" }
quests[25227] = { id = 25227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thonk", description = "<Hey Süßer, mir ist gerade noch was eingefallen!/Entschuldigt mein Verhalten. Ich werde manchmal zickig> wenn neue Frauen in die Stadt kommen, weil ich nicht sehr selbstsicher bin, was mein Äußeres betrifft.; Ich habe einen SEHR guten Freund, Thonk; er arbeitet im Wachturm nordwestlich von Klingenhügel. Er meinte, dass der Fluss über die Ufer getreten sei und dass es viel Arbeit gäbe. Ich hab ihm nicht wirklich zugehört... seine tiefbraunen Augen lenken mich immer ab.\n\n<Wie, eifersüchtig? Ich soll mich nicht mit anderen treffen?/Danke.>", sourceObjective = "Meldet Euch bei Thonk im Wachturm nordwestlich von Klingenhügel.", completion = "Gail hat Euch geschickt? Hat sie... hat sie etwas über mich gesagt?", sourceObjectiveStatus = "unverified-source-field" }
quests[25228] = { id = 25228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untergangsverkündungen", description = "Untergangspropheten sind in den Straßen von Orgrimmar nichts Neues, aber diese neueste Gruppe macht mir Sorgen. Diese Leute sind organisiert, und sie haben in der Gasse, wo sie sich anscheinend versammeln, viel Aufmerksamkeit erregt.\n\nIch habe in Erwägung gezogen, sie zu verhaften oder ihre Aktivitäten auf andere Art zu stören, aber damit würde man sie nur in den Untergrund treiben. Wir müssen mehr über sie herausfinden. Würdet Ihr in die Gasse gehen, Euch anhören, was diese Schwarzseher verbreiten und alle Schriftstücke über ihre Vorstellungen sammeln, die Ihr finden könnt?", sourceObjective = "Hört Euch die Rede eines Weltuntergangsverkünders in der Gasse an, und beschafft Exemplare der Pamphlete \"Elementarfeuer für die Seele\", \"Was bedeutet 'Das Ende der Schöpfung' für mich?\" sowie \"Sicherheit und Geborgenheit in einer dem Untergang geweihten Welt\".", sourceObjectiveStatus = "unverified-source-field" }
quests[25229] = { id = 25229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Frage der Gnomenehre", description = "Unsere Ingenieure haben daran gearbeitet, unsere Kampfmaschinen für den Sturm auf Gnomeregan vorzubereiten, aber uns fehlen Piloten!\n\nUnsere Ingenieure haben ein Gerät namens Motivieratron entwickelt, das Ablenkungen verhindert und dem Gnom den Mut verleiht, sich einzuschreiben.\n\nWenn Ihr ein paar Gnomenbürger motiviert habt, führt sie zu Hauptmann Tret Funkdüse, draußen bei Stahlrosts Depot südlich von Eisenschmiede.\n\nOh, und seid vorsichtig. Das Gerät ist noch ein wenig experimentell.", sourceObjective = "Werbt mit Hilfe des Motivieratron Gnome aus Tüftlerstadt an und führt sie zu Hauptmann Tret Funkdüse bei Stahlrosts Depot.", sourceObjectiveStatus = "unverified-source-field" }
quests[25230] = { id = 25230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr als Krankheit", description = "Wir haben ein paar Drachenwelpen in der Nähe der Straße gefunden, die nach Norden führt. Die Welpen leiden an der gleichen Krankheit wie die Hirsche.\n\nGründrachen sind nicht einfache Bestien der Natur, sondern magische Kreaturen und die Wächter der Wildnis. Ihre Krankheit stellt für uns eine Bedrohung dar.\n\nWir müssen dafür sorgen, dass sich die Krankheit auf keinen Fall weiter ausbreitet. Tötet die erkrankten Welpen, {name}, und kehrt dann zu mir zurück.", sourceObjective = "Tötet 10 giftige Welpen.", completion = "Die neuesten Entwicklungen besorgen mich sehr. Die Geweihe, die ich in Eurer Abwesenheit untersucht habe, haben ein paar Erkenntnisse zu Tage gebracht.\n\nWir müssen einen Weg finden, dieses Problem zu lösen...", sourceObjectiveStatus = "unverified-source-field" }
quests[25231] = { id = 25231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abschaum des Südmeers", description = "In diesem Augenblick greifen Aggra und Kilag die Docks an, um Thrall den Weg für einen Kampf gegen den Handelsprinzen frei zu machen. Der Plan ist, dass Ihr Euch an diesem Angriff beteiligt, aber zunächst müssen wir sicherstellen, dass Gallywix' Südmeerfreibeuter ihm nicht zu Hilfe eilen.\n\nGeht zu den Sklavengruben und sorgt dafür, dass sie das nicht können!", sourceObjective = "Tötet 6 Söldner der Südmeerfreibeuter.", sourceObjectiveStatus = "unverified-source-field" }
quests[25232] = { id = 25232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brennende Klinge", description = "Ich wurde geschickt, um die Anwesenheit der Anhänger der Brennenden Klinge in Durotar zu untersuchen. Nordöstlich von hier ist eine Höhle, in der die Klinge ihre neuen Mitglieder ausbildet. Ich möchte wissen, was genau diese Ausbildung der Neophyten beinhaltet.\n\nIch erzähle Euch das eigentlich nur, weil ich das Gefühl habe, Ihr seid auf der Suche nach Arbeit. Wenn Ihr ein wenig verdienen wollt, so begebt Euch zur Höhle und bringt mir ihre Schriftrollen.\n\nDie Höhle ist etwas versteckt: Verlasst Klingenhügel in Richtung Osten und folgt dann dem östlichen Kamm der Schlucht.", sourceObjective = "Erhaltet 6 Zauberschriftrollen von den Mitgliedern der Brennenden Klinge in der Staubwindhöhle.", progress = "Die Schriftrollen, {name}, die Schriftrollen!", completion = "Das ist wirklich interessant. Diese Rituale sind nicht wirklich anders als die, die den Hexenmeistern der Horde beigebracht werden. Ich muss auf jeden Fall weitere Untersuchungen anstellen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25233] = { id = 25233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende der Versorgungslinie", description = "Cho'galls Zwielichtordner schwören einen Bluteid, dass sie ihre Vorräte bis an die Front schaffen. Sie geloben sogar, für jedes nicht gelieferte Pfund Vorräte mit einem Pfund ihres eigenen Fleisches zu bezahlen. Sie würden lieber sterben als zu scheitern.\n\nSorgt dafür, dass sie beides tun.", sourceObjective = "Tötet 4 Zwielichtordner in der Wolfsschlucht auf dem Hyjal.", completion = "Gut gemacht! Das Chaos, das wir hier anrichten, wird sich durch die gesamte Befehlskette ziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25234] = { id = 25234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arme Deppen schleppen", description = "Gefangene des Schattenhammerklans werden dazu gezwungen, verschiedene für den Krieg benötigte Dinge wie Packtiere herumzuschleppen. Ich will diese Vorräte - und wenn wir dabei ein paar arme Seelen aus den Klauen des Schattenhammers befreien können, umso besser.\n\nTötet die Sklaventreiber entlang der Straße im Süden und die Sklaven in ihrer Nähe sollten in der Lage sein, zu entfliehen.\n\nDurchsucht die Rucksäcke, die sie hinterlassen, nach wertvollen Dingen und zerstört alles, was Ihr nicht tragen könnt.", sourceObjective = "Sammelt 36 Versorgungsgüter des Schattenhammers, die von befreiten Zwielichtsklaven zurückgelassen wurden.", progress = "Habt Ihr da unten ein wenig Zerstörung angerichtet, {name}?", completion = "<Jadi tritt eine der Kisten mit dem Fuß auf und zieht einen geschwungenen Dolch daraus hervor. Sofort fängt sie an zu wimmern.>\n\nAutsch! Verdammt! Dieses Metall ist verflucht. Es beißt!\n\n<Als der Dolch zu Boden fällt, zerspringt er in tausend Stücke, als wäre er aus dünnem Glas.>\n\nWas für eine geisteskranke Schmiedekunst ist das? {name}, ich bin noch nie zuvor auf solch einen Feind getroffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25235] = { id = 25235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vulgäres Vul'Gol", description = "Grüße, {class}. Wollt Ihr die Bewohner von Dunkelhain unterstützen?\n\nDirekt hinter dieser Hügelkuppe da drüben gibt es einen riesigen Ogerhort. Die Oger der Splitterfäuste bleiben normalerweise unter sich, aber sie haben die schlechte Angewohnheit, Reisende zu überfallen. Gerade neulich habe ich gesehen, wie einer das Pferd eines armen Mannes fortgeschleppt hat, um es zu fressen... Zum Glück hat er ihn nicht mitgenommen!\n\nDie Nachtwache möchte das Leben ihrer wenigen Mitglieder, darunter auch meines, jedoch nur für dringlichere Bedrohungen riskieren. Wenn Ihr ein paar dieser Oger für mich töten würdet, würde ich Euch für Eure Tat belohnen.", sourceObjective = "Tötet 15 Oger der Splitterfäuste.", completion = "Ich habe von hier aus gesehen, wie Ihr ein paar von ihnen den Garaus gemacht habt. Gute Arbeit.\n\nHiermit überreiche ich Euch im Namen der Nachtwache Eure Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[25236] = { id = 25236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donner von unten", description = "Unsere Armee braucht Wasser, und das haben wir dank der Elemente nach dem Kataklysmus jetzt reichlich. Das Wasser, das die Schlucht südwestlich von hier gefüllt hat, sollte ausreichen.\n\nLeider sind die Leichname der Donnerechsen noch überall unten in der Schlucht, und die elektrischen Stöße, die sie von sich geben, sind ein bisschen gefährlich. Ich habe Grunzer, die sie aus dem Wasser ziehen können, aber ich brauche jemand, der geschickt genug ist, sie am anderen Ende des Seils zu befestigen. Seid Ihr <der Mann, den/die Frau> die; ich suche?", sourceObjective = "Befestigt die Magiestoffleine an 8 ertrunkenen Donnerechsen im Donnergrat.", progress = "Die Schlucht muss gereinigt werden, {name}. Wasser ist normalerweise sehr selten in Durotar... wir müssen diese Situation nutzen.", completion = "Die Elektrizität der Echsen war nur eine Gefahr. Wenn die Kadaver zu lange im Wasser geblieben wären und weitergerottet hätten, wäre das Wasser bald nicht mehr trinkbar gewesen.\n\nIhr habt gute Arbeit geleistet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25237] = { id = 25237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tränen der Steine", description = "Ihr habt gehört, wie der Drache Ysondre uns erklärt hat, dass die Tränen des Landes das Portal schließen können, aus dem die Verderbnis strömt.\n\nVor einigen Wochen habe ich in dem Tal westlich von hier gesehen, dass es den Bergriesen schlecht ging. Sie waren wild vor Frustration, und als sie weinten, wurden ihre Tränen, die auf die Steine fielen, zu Kristallen.\n\nDie Riesen weinen zwar nicht mehr, aber diese Steintränen sind wohl das, was Ysondre gemeint hat - eine Quelle reiner Natur. Wir brauchen diese Tränen.", sourceObjective = "Sammelt 7 Steintränen.", progress = "Die Tränen sind auf den Steinen, aus denen die Riesen entstanden. In der Nähe der Monolithen am Fuß des Berges sollten lose Tränen zu finden sein.", completion = "Ich danke Euch erneut, {name}. Ich werde die Tränen für unsere letzte Aufgabe vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25238] = { id = 25238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkering Kennzeichnung" }
quests[25239] = { id = 25239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg der Macht", progress = "Ihr wollt also tätsächlich weiter dem Weg der Macht folgen?", completion = "Ihr stellt Euren Wert wieder unter Beweis, {name}. Nehmt dies, nicht als Geschenk, sondern als Werkzeug im Kampf gegen die Geißel." }
quests[25240] = { id = 25240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg der Macht", progress = "Ihr wollt also tätsächlich weiter dem Weg der Macht folgen?", completion = "Ihr stellt Euren Wert wieder unter Beweis, {name}. Nehmt dies, nicht als Geschenk, sondern als Werkzeug im Kampf gegen die Geißel." }
quests[25241] = { id = 25241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das verderbte Land", description = "Die Klippenriesen von Feralas sind Ausläufer der Erde selbst, {name}. Wenn es der Natur gut geht, so sind sie wohlwollende Beschützer und friedliche Wächter.\n\nDoch wenn der Wald leidet, so leiden auch sie.\n\nWenn sie von dieser Krankheit heimgesucht und verderbt wurden, so werden sie sich gewaltvoll gegen die Wildtiere und selbst gegen ihresgleichen richten und so für großflächige Zerstörung sorgen.\n\nZerstört alle verderbten Riesen, die Ihr finden könnt.", sourceObjective = "Tötet 7 verderbte Klippenriesen.", completion = "Die Geister der Beschützer werden wieder zurückkehren, {name}. Ihr habt sie befreit und nun können sie im Kreislauf der Natur ihre Wege gehen.\n\nJetzt liegt es an uns, sicherzustellen, dass der Kreislauf frei von Verderbnis und grundlosem Schmerz ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25242] = { id = 25242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg der Macht", progress = "Ihr wollt also tätsächlich weiter dem Weg der Macht folgen?", completion = "{name}. Niemand kann für sich beanspruchen, den Kampf mit mehr Hingabe zu unterstützen als Ihr.\n\nEs wird gemunkelt, dass die Lakaien der Geißel Euch mehr fürchten als den Lichkönig selber." }
quests[25243] = { id = 25243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie liebt mich, sie liebt mich NICHT!", description = "Oh, <Süßer/Süße>! Ihr werdet nie glauben, wer sich in den Sklavengruben im Norden aufhält.\n\n<Sassy schüttelt traurig den Kopf.>\n\nVani ist da unten und arbeitet für den Handelsprinzen. Diese kaltherzige Schlange hat Euch wie eine heiße Kartoffel fallenlassen und jetzt arbeitet sie auch noch für die anderen. Seit Ihr Euch um Chip \"gekümmert\" habt, schmeißt sie sich an den Handelsprinzen heran!\n\nIch weiß ja nicht, wie es Euch bei der Sache geht, aber wäre sie meine absolut nicht ausgedachte Freundin gewesen, würde ich ihr das wankelmütige Herz aus der Brust reißen.", sourceObjective = "Reißt Vani LeHörnchen das wankelmütige Herz aus der Brust.", progress = "Wie habt Ihr Euch entschieden, Herzchen?", completion = "Ich bin mir sicher, dass sie es verdient hat, {name}. Sie hätte Euch einfach nicht betrügen dürfen.\n\nMir läuft es eiskalt den Rücken hinunter, wenn ich daran denke, dass sie dieses Monster, den Handelsprinzen, vielleicht sogar geküsst hat!", sourceObjectiveStatus = "unverified-source-field" }
quests[25244] = { id = 25244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer heißt denn schon Vani?", description = "Bei dieser Vani LeHörnchen fehlen einem wirklich die Worte! Bis Ihr Euch um Chip \"gekümmert\" habt, wollte sie doch tatsächlich mit ihm eine gemeinsame Marke gründen. Und jetzt schmeißt sie sich an den Handelsprinzen heran!\n\nIch kann es immer noch nicht fassen, dass sie Euch einfach so Euren absolut nicht ausgedachten Freund ausgespannt hat. Vielleicht solltet Ihr zu den Sklavengruben gehen und diesem hinterhältigen Miststück ein für alle Mal die Leviten lesen!", sourceObjective = "Tötet Vani LeHörnchen.", completion = "Das geschieht ihr Recht! Schließlich hat sie Euch den Mann geklaut!", sourceObjectiveStatus = "unverified-source-field" }
quests[25245] = { id = 25245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet Vani LeHörnchen Nachfolgequest" }
quests[25246] = { id = 25246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesinnungswandel" }
quests[25247] = { id = 25247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesinnungswandel" }
quests[25248] = { id = 25248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesinnungswandel" }
quests[25249] = { id = 25249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesinnungswandel" }
quests[25250] = { id = 25250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Traum versiegeln", description = "Wir sind bereit. Nehmt diese Träne, {name}. Sie ist voller natürlicher Essenz und vom Willen Ysondres geheiligt.\n\nÖstlich von hier, auf der anderen Seite des Baches, befindet sich Traumgeäst. Dort steht der Große Baum, der größte Baum Feralas', ein Schössling des Weltenbaums. In seinem Stamm ist ein Portal, das direkt zum Smaragdgrünen Traum führt. Dieses Portal müsst Ihr schließen.\n\nDas Portal wird bewacht sein; Ihr müsst mutig sein. Möge die Erdenmutter über Euch wachen.", sourceObjective = "Benutzt Ysondres Träne, um das Portal im Traumgeäst zu schließen.", completion = "Die Verderbnis wurde eingedämmt! Der Wald kann nun heilen.\n\nMöge der Segen der Erdenmutter auf all Euren Wegen bei Euch sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25251] = { id = 25251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endkampf", description = "{name}, es ist so weit! Thrall ist unten an Gallywix' Docks und kämpft in diesem Augenblick gegen den Handelsprinzen!\n\nSpringt sofort in Euer ultimatives Fußbombentrikot und beteiligt Euch!", sourceObjective = "Legt das ultimative Fußbombentrikot an und kümmert Euch um Handelsprinz Gallywix.", progress = "{name}, Ihr müsst den Handelsprinzen vernichten, bevor es zu spät ist!", completion = "Ihr habt es geschafft! Ihr habt es geschafft!\n\nWir sind gerettet, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25252] = { id = 25252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herrscher von Düsterbruch", description = "Nun, da wir in den Ruinen viel erreicht haben, ist es an der Zeit, dass wir uns der Oger in ihrer Heimat annehmen.\n\nDie Gordok bilden die \"Oberschicht\" des Stamms der Gordunni. Sie wurden ausgewählt, Düsterbruch zu verteidigen. Sie werden merken, dass wir es ernst meinen, wenn wir die Stärksten der Gordok vernichten.\n\nDiesmal nichts Ausgefallenes, {name}. Macht Euch einfach auf den Weg und zerschlagt ein paar Gordokschädel!", sourceObjective = "Tötet 6 Vollstrecker der Gordok und 6 Ogermagier der Gordok.", completion = "Ausgezeichnet! Selbst diese Narren werden bald wissen, dass es den Tod bedeutet, wenn man sich gegen die Horde stellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25253] = { id = 25253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untergangsverkündungen", description = "Untergangspropheten sind in den Straßen von Sturmwind nichts Neues, aber diese neuesten machen mir Sorgen. Sie haben sich in der ganzen Altstadt breitgemacht, und es sieht aus, als seien sie gut organisiert.\n\nIch habe in Erwägung gezogen, sie zu verhaften oder ihre Aktivitäten auf andere Art zu stören, aber damit würde man sie nur in den Untergrund treiben. Wir müssen so viel wie möglich über sie herausfinden. Würdet Ihr in die Altstadt gehen, Euch anhören, was diese Schwarzseher verbreiten, und versuchen, einige ihrer Flugblätter einzusammeln?", sourceObjective = "Hört Euch die Rede eines Weltuntergangsverkünders in der Altstadt an, und beschafft Exemplare der Pamphlete \"Elementarfeuer für die Seele\", \"Was bedeutet 'Das Ende der Schöpfung' für mich?\" sowie \"Sicherheit und Geborgenheit in einer dem Untergang geweihten Welt\".", sourceObjectiveStatus = "unverified-source-field" }
quests[25254] = { id = 25254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen der Zeit", description = "Wir müssen etwas tun, um das Interesse an diesem Weltuntergangskult einzudämmen, aber ich schrecke davor zurück, zur Tat zu schreiten, bevor wir nicht wissen, wer hinter dieser Gruppe steckt.\n\nIch habe meine Leute Markierungen in belebten Teilen Orgrimmars anbringen lassen. Nehmt diese Plakate und bringt sie dort an, wo Ihr die Markierungen seht. Sie werden die entschlossensten unter den Suchenden nicht abhalten, aber es ist ein erster Schritt zur Entlarvung dieses Kultes. Die Horde hat genug zu tun, ohne dass absichtlich Lügen verbreitet werden.", sourceObjective = "Hängt 5 Warnplakate im Tal der Stärke, der Gasse oder dem Tal der Ehre auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[25255] = { id = 25255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stört die Störer", description = "Der Schattenhammer hat sich als mehr als ein einfacher Kult entpuppt. Er ist eine gut geölte Kriegsmaschinerie, die sich wie ein Heuschreckenschwarm auf dem Berg niedergelassen hat und alles verschlingt, was ihr in den Weg kommt.\n\nDie Teile des Waldes, die sie nicht in Brand stecken, werden systematisch nach allem Lebenden durchkämmt, um die sterblichen Kultisten zu nähren.\n\nWir müssen die Jäger aufhalten, die die Wolfsschlucht ins Visier genommen haben. Nicht nur der übrigen Wildtiere zuliebe, sondern auch um den Kult zu zwingen, mit leerem Magen zu marschieren. Sucht südlich von hier und an der Straße im Osten.", sourceObjective = "Tötet 6 Zwielichtjäger in der Wolfsschlucht auf dem Hyjal.", completion = "Danke, {name}. Ich fürchte, dass unsere Anstrengungen vergeblich sein könnten. Aber die Natur erschafft sich immer wieder neu und versetzt uns stets in Erstaunen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25256] = { id = 25256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe benötigt", description = "Ihr da, {race}, nicht so schnell.\n\nMein Boss Spitzzahn hat mich geschickt, um nach Hilfe zu suchen - und nach Vorräten. Ihr scheint kein Händler zu sein, aber wahrscheinlich könnt Ihr ihm trotzdem helfen. Er ist südöstlich von hier, neben dem kaputten Wagen. Oh, und sagt ihm, ich habe Euch geschickt... Ich muss sicherstellen, dass er weiß, dass ich hier nicht nur meine Zeit vertrödel.", sourceObjective = "Meldet Euch bei Spitzzahn an Kilroggs Küste in Durotar.", completion = "Vek'nag schickt Euch? Ohne Euch zu sagen, was ich brauche? Keine Rede von Wagenrädern, Nägeln und Vorräten? So ein Depp.", sourceObjectiveStatus = "unverified-source-field" }
quests[25257] = { id = 25257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghislania", description = "Ich habe ein paar Gladiatoren, die ich bei Wettkämpfen rund um Kalimdor antreten lasse. Die meisten von ihnen sind hier angekettet... wir hatten Glück, diese hier zu bekommen, als ihr Wagen kaputt ging.\n\nGhislania, die Naga dort drüben... hat ihre letzten drei Kämpfe verloren! Sie braucht wohl mehr Ausbildung, oder vielleicht auch nur genug Schläge. Fordert sie heraus - ich wette, selbst IHR seid stärker als sie.", sourceObjective = "Besiegt Ghislania im Kampf.", completion = "Ich habe Euren Kampf beobachtet. Wie lange seid Ihr schon als {class} unterrichtet worden?\n\nNicht schlecht, Kindchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25258] = { id = 25258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Griswold Hanniston", description = "Griswold, der da drüben an der Klippe angekettet ist, ist mein neuster Gladiator. Wir haben ihn direkt südlich von hier gefunden. Hat zusammen mit Soldaten von Nordwacht hier herumgeschnüffelt. Meine Männer haben ihn geschnappt und jetzt arbeitet er für mich.\n\nEr sieht ziemlich stark aus, aber ich habe ihn noch nicht wirklich in der Schlacht getestet. Warum fangt Ihr nicht einen Kampf mit ihm an und schaut, ob es sich lohnt, ihn zu behalten?", sourceObjective = "Besiegt Griswold Hanniston im Kampf.", completion = "Jetzt weiß ich gar nicht mehr, was ich tun soll, {name}… Ihr habt ihn ganz leicht im Kampf besiegt, aber ich habe ihn ja auch umsonst bekommen. Und er ist auch günstig im Unterhalt. Vielleicht behalte ich ihn einfach noch eine Weile.", sourceObjectiveStatus = "unverified-source-field" }
quests[25259] = { id = 25259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaur Eishorn", description = "Normalerweise würde ich Taunka nicht als Gefangene halten, weil sie der Horde doch recht nahe stehen... dieser hier ist allerdings ein Verräter, und noch dazu ein Krimineller. Er wurde von seinem eigenen Stamm ausgestoßen und ist mit dem Kanu nach Azshara gekommen - und dann wurde er dabei erwischt, wie er Vorräte von Valormok geklaut hat. Er hätte sein Ende sofort mit einer Axt gefunden, wenn ich nicht in der Nähe gewesen wäre und für ihn bezahlt hätte.\n\nGaur ist mein bester Gladiator, {class}. Ich wette eine Handvoll Silber, dass Ihr ihn nicht besiegen könnt.", sourceObjective = "Besiegt Gaur Eishorn im Kampf.", completion = "Schon gut, hier habt Ihr das Geld... aber Ihr verschwindet besser bald, bevor ich es mir noch einmal überlege, ob ich nicht doch jemanden von der Horde als Sklaven halten möchte.", sourceObjectiveStatus = "unverified-source-field" }
quests[25260] = { id = 25260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missglückt", description = "Die Flut im Südwesten hat eines der Lager der Brennenden Klinge zerstört, die Durotar so hässlich machten. Dieses Lager wurde von Zischel Dunkelklaue angeführt - glaubt mir, ohne ihn sind wir besser dran.\n\nDunkelklaue hat allerdings eine Kugel besessen, an der die Horde sehr interessiert ist. Man weiß nicht, warum... meiner Meinung nach können sich die Hexenmeister darum kümmern. Ich weiß nur, dass ich die Kugel für sie besorgen muss.", sourceObjective = "Erhaltet Zischels Kugel von Zischel Dunkelklaue im Donnergrat.", progress = "Hattet Ihr irgendwelche Schwierigkeiten?", completion = "Ich bitte Euch, mir eine Kugel zu bringen, und Ihr bringt den halben Goblin mit, der noch dranklebt? Eine sehr schöne Arbeitsweise.\n\nNun, Ihr wart sicherlich eine helfende Hand. Ich möchte Euch nun auch einen Gefallen tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[25261] = { id = 25261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Margoz", description = "Margoz, einer unserer nützlichsten Schamanen, weiß mehr über die Verderbnis der Brennenden Klinge. Er sprach von einer Höhle namens Knochenhöhle in den Bergen - gleich vor den Toren Orgrimmars! - dort soll sich eine große Gruppe von Kultisten der Brennenden Klinge eingenistet haben.\n\nBevor Ihr jedoch zur Knochenhöhle geht, sprecht mit Margoz. Er ist weise und sein Rat wird geschätzt.\n\nEr lagert im Südosten zwischen der Küste und der Staubwindklamm.\n\nFolgt seinem Rat, aber was immer Margoz auch sagt, {name}, ich möchte, dass Ihr diese Kultisten vernichtet!", sourceObjective = "Sprecht mit Margoz.", completion = "Willkommen, {name}. Man hat mir Euer Kommen angekündigt und mir von Euren Unternehmungen in Durotar berichtet.\n\nIhr seid ein {class} mit stetig wachsenden Fertigkeiten und Ansehen.\n\nHaltet Euch auf dem reinen Pfad, dann wird Eure Zukunft wahrlich großartig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25262] = { id = 25262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Knochenhöhle", description = "{name}. Die Brennende Klinge hat die Knochenhöhle östlich von Orgrimmar eingenommen. Sie halten in der Höhle widerliche Rituale ab und verbrennen ihr eigenes Fleisch mit Senghalsbändern.\n\nDurch das Tragen dieser Halsbänder stimmen sich die Kultisten meines Wissens auf dämonische Macht ein. Aber um dies zu bestätigen benötige ich ein paar der Halsbänder, um sie zu untersuchen.\n\nBegebt Euch zur Knochenhöhle und sammelt Senghalsbänder der Kultisten, die sich dort aufhalten. Bringt mir die Halsbänder, und ich werde ihr Geheimnis lüften.", sourceObjective = "Erhaltet 6 Senghalsbänder von den Kultisten in der Knochenhöhle.", progress = "Habt Ihr die Knochenhöhle bereits gefunden, {name}? Habt Ihr die Senghalsbänder?", completion = "Gut. In diesen Halsbändern verbirgt sich das Geheimnis der Brennenden Klinge. Und dieses Geheimnis werde ich nun lüften...", sourceObjectiveStatus = "unverified-source-field" }
quests[25263] = { id = 25263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arnak Feuerklinge", description = "Die Senghalsbänder, die Ihr mir gebracht habt, sind mächtige dämonische Hilfsmittel. Leider sind meine schamanischen Kräfte nicht stark genug, um herauszufinden, woher sie stammen. Bei dieser Aufgabe kann uns nur ein Hexenmeister helfen.\n\nBringt ein Senghalsband zu Arnak Feuerklinge. Er ist zwar ein geschickter Hexenmeister, benutzt nach eigenen Worten seine Künste jedoch nur, um Dämonen zu bekämpfen. Er behauptet, all seine Forschungen stünden im Dienste des Guten. Ob dies nun stimmt oder nicht, wir brauchen seine Hilfe, um etwas gegen den Dämonenkult in Durotar zu unternehmen.\n\nIhr findet Arnak in Orgrimmar in der Kluft der Schatten.", sourceObjective = "Bringt ein Senghalsband-Muster zu Arnak Feuerklinge in Orgrimmar.", progress = "Meine ergebensten Grüße, {class}. Womit kann ich Euch heute behilflich sein?", completion = "Ah, und wo habt Ihr das her? Der gute Margoz hat Euch zu mir geschickt, richtig?\n\nNun, dann lasst mich mal einen Blick darauf werfen...", sourceObjectiveStatus = "unverified-source-field" }
quests[25264] = { id = 25264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ak'zeloth", description = "Seit dem letzten großen Krieg, in dem die Brennende Legion besiegt wurde, suche ich nach den Quellen dämonischer Verderbnis innerhalb der orcischen Gesellschaft. Das Halsband, das Ihr mir brachtet, bestätigt meine Befürchtungen.\n\nEs gehört der Brennenden Klinge.\n\nIhr habt Eure Rolle in dieser Geschichte beinahe zu Ende gespielt, {name}. Geht zur Fernwacht an der Grenze zum Brachland im Westen und sprecht dort mit meinem Assistenten Ak'zeloth. Gebt diese Informationen an ihn weiter.", sourceObjective = "Sprecht mit Ak'zeloth in der Fernwacht im Nördlichen Brachland.", completion = "Das sind keine Neuigkeiten. Ich erkenne Eure Anstrengungen an, aber die Brennende Klinge muss warten. Wir müssen uns Wichtigerem widmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25265] = { id = 25265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieg!", description = "Wir können Euch nicht genug für all das danken, was Ihr getan habt. Endlich kommen wir von dieser Insel herunter, bevor sie uns noch umbringt!\n\nThrall wird zuerst mit Euch sprechen wollen, {name}. Ich schicke Euch mit einer Rakete da rüber.\n\nWir sehen uns auf dem Schiff!", sourceObjective = "Sprecht mit Thrall an Gallywix' Docks auf den Verlorenen Inseln.", completion = "Lok'tar! Sieg, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25266] = { id = 25266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gesandte des Kriegshäuptlings", description = "Die Goblins und die Horde haben gemeinsam zu viel erreicht, um jetzt wieder getrennter Wege zu gehen, {class}. Ich möchte, dass das Bilgewasserkartell sich der Horde anschließt.\n\nIch habe hier etwas für den neuen Kriegshäuptling. Gebt dieses Päckchen einer meiner Vertrauten vom Stamm der Dunkelspeere am Dock der Messerbucht in Durotar. Sie wird Euch helfen, sicher nach Orgrimmar zu gelangen.\n\nSprecht mit Sassy Hartzang auf dem Schiff, wenn Ihr bereit seid, in See zu stechen.\n\nAuf bald! Aka'Magosh! Möget Ihr und die Euren gesegnet sein, {name}!", sourceObjective = "Liefert das versiegelte Päckchen bei der Loyalistin der Dunkelspeere an den Docks der Messerbucht in Durotar ab.", progress = "Was wollt Ihr denn in Orgrimmar?", completion = "Ich weiß, wer Euch schickt. Hat er Euch 'was für mich mitgegeb'n?", sourceObjectiveStatus = "unverified-source-field" }
quests[25267] = { id = 25267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht für Saurfang", description = "<Die Loyalistin der Dunkelspeere öffnet das Paket und liest den darin enthaltenen Brief. Als sie am Ende der Notiz ankommt, entblößt ein Lächeln ihre Fangzähne.>\n\nIhr bringt das besser direkt zu Saurfang in Orgrimmar. Lasst ihn auf jed'n Fall wiss'n, dass das Paket von Thrall stammt.\n\nNehmt meinen Raptor. Schnell, wir hab'n keine Zeit zu verlier'n!", sourceObjective = "Bringt das Emblem des SI:7 zu Hochfürst Saurfang in der Feste Grommash in Orgrimmar.", progress = "Was soll das, {race}? Ihr stammt nicht aus dieser Gegend.", completion = "Das kommt von Thrall?\n\n<Saurfang reibt sich gedankenversunken das Kinn.>\n\nIch verstehe genau, was das bedeutet.\n\nIn Azshara arbeiten noch andere Goblins, die Euch helfen könnten. <Saurfang deutet in Richtung Gobber.> Wir haben den in der Stadt herumlaufen sehen, und er scheint Euch zu erkennen. Vielleicht will der Euch ja begleiten.\n\nVon diesem Tag an seid Ihr und das Bilgewasserkartell Verbündete der Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[25268] = { id = 25268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stimme Goldrinns", description = "Südwestlich von hier liegt der Schrein von Goldrinn, ein Denkmal, das zu Ehren des alten Wolfsgeistes und seinem Beitrag beim Krieg der Ahnen errichtet wurde.\n\nUnsere neuen Verbündeten, die Worgen, waren von dieser Verehrung für den Wolfsgott natürlich vollkommen begeistert und haben begonnen, den Schrein aufzuräumen.\n\nIch habe schon seit Tagen nichts mehr von meiner Kontaktperson Ian Duran gehört. Könntet Ihr vielleicht dorthin fliegen und nach ihm sehen? Ich habe das ungute Gefühl, dass es am Schrein von Goldrinn Schwierigkeiten gibt.", sourceObjective = "Findet Ian Duran in der Nähe des Schreins von Goldrinn auf dem Hyjal.", completion = "Ihr seid hier, um mich zu retten, {class}? Danke!\n\nNein, nein, kümmert Euch nicht um den Käfig. Mein Leben ist unwichtig. Zuerst müssen wir den Schrein retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25269] = { id = 25269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stimme Lo'Goshs", description = "Habt Ihr von Lo'Gosh, dem Wolfsahnen, gehört? Die Mitglieder der Allianz nennen ihn \"Goldrinn\".\n\nIch muss Euch sicher nicht sagen, wie wichtig der Wolfsgott für die Horde ist. Seine Standhaftigkeit im Angesicht des Feindes war für alle Völker eine wahre Inspiration, egal, wie verschieden sie sein mögen.\n\nSüdwestlich von hier, unten im Tal, liegt ein Schrein für Goldrinn. Mein Freund Takrik Wutheuler war dabei, den Schrein wiederaufzubauen, aber ich habe schon seit Tagen nichts mehr von ihm gehört und befürchte das Schlimmste.\n\nBitte findet Takrik und überzeugt Euch davon, dass es ihm gut geht!", sourceObjective = "Findet Takrik Wutheuler in der Nähe des Schreins von Goldrinn auf dem Hyjal.", completion = "Lok'tar, {class}! Macht Euch keine Sorgen wegen des Käfigs, diese Tiere werden schon bald aus Furcht vor mir erzittern.\n\nMeine oberste Priorität besteht darin, diesen Abschaum von meinem geliebten Schrein zu verjagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25270] = { id = 25270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie heulen wie die Schlosshunde", description = "Der Schrein wurde erobert, {name}. Jetzt brauchen wir die Standhaftigkeit von Lo'Gosh mehr denn je.\n\nDiese Schänder, die flohverseuchten Wolfmänner, die den Schrein verwüsten, beschmutzen die Ehre des Wolfsgottes. Sie sind zusammen mit dem Schattenhammerkult eingetroffen und heulen einmütig ihre falschen Götter an. Sie wollen den edlen Lo'Gosh verderben, sodass er in ihr eigenes, verqueres Götterpantheon passt.\n\nTötet sie! Tötet sie und bringt mir die Werkzeuge ihrer Verehrung, eine Art verunreinigter Weihrauch. Ich muss verstehen, was sie mit dem Schrein vorhaben...", sourceObjective = "Beschafft Euch 6 Einheiten verunreinigten Weihrauchs.", progress = "Diese Tiere waren einst Menschen, aber sie haben sich unter dem Einfluss des Schattenhammers in hirnlose Tiere verwandelt. Zögert nicht, sie alle zu töten.", completion = "<Takrik untersucht den Weihrauch.>\n\nAbscheulich. Er ist wie der Weihrauch, den wir verbrennen, um mit den Geistern zu sprechen… aber er ist… besudelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25271] = { id = 25271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldrinns Wildheit", description = "Diese wilden Tiere, die Ihr hier seht, sind nicht länger meine Brüder aus Gilneas. Sie wurden von einer Art Wahnsinn befallen und haben den Schrein eingenommen.\n\nSie kamen, als der Schattenhammer auf dem Hyjal eingetroffen ist, und heulen den Namen eines gotteslästerlichen Abklatsches unseres geliebten Goldrinns. Kümmert Euch nicht um mich. Eure oberste Pflicht besteht darin, diese Vandalen daran zu hindern, den Schrein weiter zu entehren.\n\nVernichtet sie und haltet nach dem Weihrauch Ausschau, den sie bei sich tragen. Bringt mir ein paar Proben davon!", sourceObjective = "Beschafft Euch 6 Einheiten verunreinigten Weihrauchs.", progress = "Worgen wie ich werden von der Geschichte Goldrinns und seiner Stärke und Weisheit magisch angezogen. Aber diese Vandalen verehren eine ganz andere Art von Wolfsgott.", completion = "<Ian untersucht den Weihrauch.>\n\nWie ich es erwartet habe. Diese Reagenzien tragen das Zeichen des Schattenhammerkults. Und hier steht der Name \"Lycanthoth\". Ich glaube, dieser Weihrauch wird in Beschwörungsritualen verwendet…", sourceObjectiveStatus = "unverified-source-field" }
quests[25272] = { id = 25272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lycanthoth der Verderber", description = "Die Handlungen dieser wilden Hunde ergeben so langsam Sinn. Der Schattenhammer fürchtet sich vor der Macht der Ahnen. Sie möchten nicht, dass Lo'Gosh zurückkehrt.\n\nAlso haben sie ihren eigenen Wolfsgott gerufen, oder eher das verzerrte Abbild dessen, was er einst war. \"Lycanthoth\", der Verderber.\n\n{name}, Lycanthoth hat nicht einmal annähernd so viel Macht wie Lo'Gosh, aber die Bestie muss vernichtet werden, damit der wahre Ahn zurückkehren kann. Nehmt dieses Rauchwerk und verbrennt es im Schlund von Lycanthoth östlich von hier. Tötet dieses abscheuliche Wesen und befreit Lo'Goshs Geist!", sourceObjective = "Benutzt Lycanthoths Rauchwerk im Schlund von Lycanthoth auf dem Hyjal, um Lycanthoth zu beschwören und zu töten.", progress = "Euer Mut ist ein leuchtendes Beispiel für andere, {class}. Sagt, wie heißt Ihr?", completion = "Es war sehr tapfer von Euch, Lycanthoth gegenüberzutreten, {name}. So wie ich war er eine ursprüngliche Naturgewalt... doch er stammte von einem dunkleren Ort.\n\nDiejenigen, die dieses Ungeheuer gebaren, drangen tief in die Finsternis ein und kanalisierten Kräfte, die niemals für diese Welt gedacht waren.\n\nKommt, {class}. Klettert auf meinen Rücken und wir werden diesen Ungeheuern das wahre Gesicht der Wildheit zeigen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25273] = { id = 25273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lycanthoth der Verderber", description = "Ich glaube, ich verstehe, was hier vor sich geht. Der Schattenhammer fürchtet, dass die Ahnen sich eines Tages gegen sie wenden könnten. Sie würden alles tun, um Goldrinns Rückkehr zu verhindern.\n\nDieser \"Lycanthoth\" ist eine entstellte Version unseres geliebten Wolfsgottes, den der Schattenhammer beschworen hat, um ihn zu ersetzen.\n\nPah! Lycanthoth hat nicht einmal annähernd so viel Macht wie Goldrinn. {name}, Ihr müsst die Bestie vernichten, damit der wahre Ahn zurückkehren kann. Nehmt dieses Rauchwerk und verbrennt es im Schlund von Lycanthoth östlich von hier. Tötet dieses abscheuliche Wesen und befreit Goldrinn!", sourceObjective = "Benutzt Lycanthoths Rauchwerk im Schlund von Lycanthoth auf dem Hyjal, um Lycanthoth zu beschwören und zu töten.", progress = "Euer Mut ist ein leuchtendes Beispiel für andere, {class}. Sagt, wie heißt Ihr?", completion = "Es war sehr tapfer von Euch, Lycanthoth gegenüberzutreten, {name}. So wie ich war er eine ursprüngliche Naturgewalt... doch er stammte von einem dunkleren Ort.\n\nDiejenigen, die dieses Ungeheuer gebaren, drangen tief in die Finsternis ein und kanalisierten Kräfte, die niemals für diese Welt gedacht waren.\n\nKommt, {class}. Klettert auf meinen Rücken und wir werden diesen Ungeheuern das wahre Gesicht der Wildheit zeigen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25274] = { id = 25274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gezeichnet mit Blut", description = "Endlich seid Ihr hier, {name}. Und genau zur richtigen Zeit.\n\nDie Nachricht über Ragnaros' Auftauchen hat eine große Welle von neuen Rekruten ausgelöst, die sich um eine Mitgliedschaft beim Schattenhammerkult bewerben.\n\nWenn Ihr den Kult unterwandern möchtet, dann ist jetzt der rechte Augenblick. Wir brauchen Rekrutierungsunterlagen, die mit dem Blut eines Mitglieds des Schattenhammers unterzeichnet wurden, das Euch empfiehlt. Lockt einen von den neuen Rekruten von der Gruppe weg und schlagt ihn mit diesem Totschläger.\n\nWenn Ihr Glück habt, könnt Ihr ihm seine Rekrutierungsunterlagen stehlen. Bringt sie zu mir. Ich werde mir alle Mühe geben, sie zu verändern.", sourceObjective = "Lockt einen Zwielichtrekruten von der Gruppe weg und stehlt seine Rekrutierungsunterlagen des Schattenhammers.", progress = "Habt Ihr die Papiere?", completion = "Ausgezeichnet. Ich werde mir alle Mühe geben, diese Dokumente zu verändern.", sourceObjectiveStatus = "unverified-source-field" }
quests[25275] = { id = 25275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch beim Arbeitsaufseher", description = "Eure Leute werden an der landschaftlichen Umwandlung Azsharas arbeiten. Das Land wird gemäß den Vorstellungen der Horde neu gestaltet, damit jeder weiß, dass Kalimdor uns gehört!\n\nGeht nach Norden durch die Stadt. Auf der anderen Seite des Tals der Ehre findet Ihr das Hintere Tor von Orgrimmar. Meldet Euch bei Arbeitsaufseher Grabbit vor dem Tor.\n\nFür die Horde!!!", sourceObjective = "Meldet Euch bei Arbeitsaufseher Grabbit am Hinteren Tor von Orgrimmar in Azshara.", completion = "{name}? Der {name}?!\n\n\n\nEuer Ruf eilt Euch voraus. Ich weiß nicht, ob ich dankbar oder besorgt sein sollte, dass Ihr hier seid. Zumindest gibt es in Azshara keine Vulkane!\n\nIm Ernst, ich kann es kaum glauben, dass Ihr Euch hier blicken lasst... Handelsprinz Gallywix hat eine Werkstatt oben auf dem Berg errichtet!", sourceObjectiveStatus = "unverified-source-field" }
quests[25276] = { id = 25276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eure neue Identität", description = "Da! Nicht meine beste Arbeit, aber auch nicht meine schlechteste. Ihr werdet bei den Kultisten den Namen \"{name}damus\" tragen.\n\nMit diesen Papieren werdet Ihr den anderen Rekruten vorgezogen und könnt direkt mit den Zwielichtinstrukteuren sprechen.\n\nGeht zu den Versuchsgründen und zeigt sie Condenna der Mitleidlosen. Sie trennt die Spreu vom Weizen.\n\nZeigt ihr, aus welchem Holz Ihr geschnitzt seid.", sourceObjective = "Sprecht mit Condenna der Mitleidlosen bei den Versuchsgründen auf dem Hyjal.", progress = "Ihr werdet mich mit dem gebührenden Respekt ansprechen, Rekrut!", completion = "Svitdamus? Hoffen wir mal, dass Eure Eltern Euch mehr auf diese Welt mitgegeben haben als einen dämlichen Namen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25277] = { id = 25277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufräumarbeiten", description = "Wir machen gute Fortschritte darin, den früheren Glanz des Schreins wiederherzustellen, {name}. Aber ein paar Aufräumarbeiten müssen wir noch erledigen. Auf der anderen Seite dieser Wiese errichten gerade ein paar Ogerlandstreicher ihr Lager. Ihr Anführer ist ein dickköpfiger Klotz purer Hässlichkeit namens Gar'gol.\n\nTötet Gar'gols Diener und schaut, ob wir ihn dadurch zum Aufbruch bewegen können.", sourceObjective = "Tötet eine beliebige Kombination aus 8 Schlägern oder Schattenwirkern des Unterschlupfs in Gar'gols Unterschlupf auf dem Hyjal.", completion = "Ha! Also habt Ihr wirklich ein paar Köpfe zum Rollen gebracht!\n\nDie Legenden sagen, dass Lo'Gosh während des Krieges der Ahnen zehn Tage ununterbrochen gegen Dämonen gekämpft haben soll. Hoffentlich habt Ihr nicht so lange kämpfen müssen…", sourceObjectiveStatus = "unverified-source-field" }
quests[25278] = { id = 25278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufräumarbeiten", description = "Dank Eurer Bemühungen sind wir vielleicht schon bald in der Lage, den früheren Glanz des Schreins wiederherzustellen. Aber zunächst müssen wir dieses Tal sichern. Südlich von hier hat eine Gruppe von Ogern unter Leitung von Gar'gol ein Lager in einem stinkenden Unterschlupf errichtet.\n\nIch würde Gar'gol nicht als 'Bedrohung' bezeichnen, sondern vielmehr als enorm massiges Hindernis auf unserem Weg, das uns von der echten Gefahr ablenkt. Dennoch müssen er und seine Gorillas gehen.\n\nTötet Gar'gols Diener in Goldrinns Namen!", sourceObjective = "Tötet eine beliebige Kombination aus 8 Schlägern oder Schattenwirkern des Unterschlupfs in Gar'gols Unterschlupf auf dem Hyjal.", completion = "Ihr habt diesen Ort richtig aufgeräumt, oder? Gut gemacht!\n\nDie Nachtelfen haben mir einst eine Geschichte erzählt, wie Goldrinn sich einem Schreckenslord gestellt und ihn getötet hat, während drei andere an seinen Flanken hingen und sein Fleisch versengten. Ich frage mich, ob Ihr oder ich je eine derartige Stärke beweisen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25279] = { id = 25279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der zurückeroberte Schrein", description = "Ja, {name}. Ich bin Goldrinn, den man in Eurer Sprache \"Lo'Gosh\" nennt. Eure Standhaftigkeit im Angesicht der Angst hat mich aus den Fesseln des Zwielichts befreit.\n\nMein Schrein wurde geläutert, und meine Anhänger sind an ihren rechtmäßigen Platz an meiner rechten Pfote zurückgekehrt.\n\nGeht zu Takrik und setzt Eure Arbeit hier auf dem Hyjal fort. Ich werde Euch schon bald erneut brauchen.", sourceObjective = "Kehrt zu Takrik Wutheuler am zurückeroberten Schrein von Goldrinn auf dem Hyjal zurück.", completion = "{name}, es war unglaublich! Für einen flüchtigen Moment sah ich Lo'Gosh durch die Bäume hindurch, ein Wesen aus Zorn und Licht zugleich. Mein Käfig ist zusammengebrochen und die Vandalen schmolzen unter dem Kuss seiner Klauen dahin wie Wachs. Ihr Schreien und Heulen erfüllte das ganze Tal... War das Euer Werk?", sourceObjectiveStatus = "unverified-source-field" }
quests[25280] = { id = 25280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der zurückeroberte Schrein", description = "Ja, {name}. Ich bin Goldrinn. Eure Standhaftigkeit im Angesicht der Angst hat mich aus den Fesseln des Zwielichts befreit.\n\nMein Schrein wurde geläutert, und meine Anhänger sind an ihren rechtmäßigen Platz an meiner rechten Pfote zurückgekehrt.\n\nGeht zu Ian und setzt Eure Arbeit hier auf dem Hyjal fort. Ich werde Euch schon bald erneut brauchen.", sourceObjective = "Kehrt zu Ian Duran am zurückeroberten Schrein von Goldrinn auf dem Hyjal zurück.", completion = "{name}, es war atemberaubend! Goldrinn selbst, sein weißes Fell so weiß wie der Sommermond. Mein Käfig ist zerfallen und die Vandalen schmolzen unter dem Kuss seiner Klauen dahin wie Wachs. Er war wunderschön, {name}. Wunderschön!", sourceObjectiveStatus = "unverified-source-field" }
quests[25281] = { id = 25281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie ich Euch, so Ihr ihnen", description = "Jetzt seid Ihr in der Lage, Euch in diesem Reich freier und ohne Angst vor Ertrinken zu bewegen.\n\nUnd jetzt beginnt unsere Arbeit.\n\nZunächst gibt es viele Verbündete von Euch in der Nähe, die in diesem Augenblick im Wasser um ihr Leben ringen. Ich habe Euch gerettet und nun müsst Ihr sie retten.\n\nIch habe die Muschel verzaubert, die Ihr mir gebracht habt. Benutzt sie, um Eure Freunde zu retten.\n\nSchnell!", sourceObjective = "Benutzt das verzauberte Tritonshorn, um 6 ertrinkende Soldaten zu retten.", completion = "Während Ihr fort wart, konnte ich einige der gefallenen Soldaten wieder zum Leben erwecken.\n\nWenn wir hier überleben wollen, brauchen wir jede helfende Hand.", sourceObjectiveStatus = "unverified-source-field" }
quests[25282] = { id = 25282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen der Zeit", description = "Wir müssen etwas tun, um das Interesse an diesem Weltuntergangskult einzudämmen, aber ich schrecke davor zurück, zur Tat zu schreiten, bevor wir nicht wissen, wer hinter dieser Gruppe steckt.\n\nIch habe meine Leute Markierungen in den belebten Teilen der Stadt anbringen lassen. Nehmt diese Plakate und bringt sie dort an, wo Ihr die Markierungen seht. Sie werden die entschlossensten unter den Suchenden nicht abhalten, aber es ist ein erster Schritt zur Entlarvung dieses Kultes. Der König hat schon genug Feinde, ohne dass sich seine eigenen Leute gegen ihn wenden.", sourceObjective = "Hängt 5 Warnplakate im Handelsdistrikt, im Kathedralenviertel, in der Altstadt oder im Magierviertel von Sturmwind auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[25283] = { id = 25283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rede vorbereiten", description = "Hochtüftler Mekkadrill hat mich gebeten, eine Rede zu schreiben, die er vor Beginn der Schlacht halten kann. Aber ich kann mich nicht mehr daran erinnern, welche Rede gut ist und welche total daneben.\n\nKönntet Ihr ein paar davon an den örtlichen gnomischen Anwohnern ausprobieren? Dieses Gerät erschafft ein Bild von Mekkadrill, das einige Zeilen aus jeder meiner Reden spricht.\n\nLasst mich wissen, welche funktioniert, ja?", sourceObjective = "Benutzt das Gnomische Abspielgerät vor Ozzie Wechselvolt nördlich von Kharanos, Milli Federpfiff bei Stahlrosts Depot und Tog Rostspross vor der Gaststätte in Kharanos. Kehrt zu Toby Zeigrad zurück, wenn alle Reden gehalten wurden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25284] = { id = 25284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Angst nähren", description = "Unsere Mittel sind begrenzt, {class}, aber das heißt nicht, dass wir da unten nicht für ein wenig Ärger sorgen können. Benutzt die Seile hier, um die Steilwand hinunterzuschleichen und tötet dann die menschlichen Gefängniswärter.\n\nEin paar dürre Wächter zu töten wird das Blatt zwar nicht wenden, aber stellt Euch die Angst und das Chaos vor, die wir dadurch verbreiten werden, wenn die Menschen die verstümmelten Leichen entdecken...\n\n<Holgom grinst und zeigt dabei seine gelben Zähne - seine Augen glitzern.>", sourceObjective = "Tötet 5 Turmwächter. Benutzt die Seile neben Holgom, um schnell nach Ehrenwacht hinein und hinaus zu gelangen.", completion = "Gut, gut! Sie werden viele schlaflose Nächte benötigen, um herauszufinden, wo wir herkamen und wohin wir verschwunden sind, nachdem wir sie umgebracht hatten...", sourceObjectiveStatus = "unverified-source-field" }
quests[25285] = { id = 25285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rein und Raus", description = "Diese neuen Mechanopanzer müssen für den Angriff fertiggemacht werden. Bereit, eine dieser Höllenmaschinen zu testen?! Klar seid Ihr das!\n\nAls erstes müssen wir sicherstellen, dass Ihr wieder rauskommt, wenn Ihr erstmal drin seid. Wenn Ihr in der Schlacht glaubt, dass Euer Panzer gleich explodieren wird, dann raus! Ich hab schon viele Gnome gesehen, die bis zum bitteren Ende dringeblieben sind... der Panzer explodiert, und sie gleich mit.\n\nAlso, ich habe diesen Panzer mit einem Schleudersitz ausgestattet. Probiert ihn für mich aus, ja?", sourceObjective = "Testet den Schleudersitz des Mechanopanzers mit Schleudersitzsystem.", sourceObjectiveStatus = "unverified-source-field" }
quests[25286] = { id = 25286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wortübermittlung", description = "Das ist es. Das ist die Rede, {name}! Sie hat alles, was einen guten Auftakt zur Schlacht ausmacht... sie inspiriert, ist eloquent und spricht den einfachen Gnom direkt an. Noch nie wurde eine bessere Rede geschrieben!\n\nGebt das hier bei Hauptmann Tret Funkdüse ab und besorgt euch einen Transport zu Hochtüftler Mekkadrill!", sourceObjective = "Bringt die Rede zu Hauptmann Tret Funkdüse bei Stahlrosts Depot.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[25287] = { id = 25287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wortübermittlung", description = "In Ordnung, Soldat. Zeit, Euch zu beweisen!\n\nNehmt diese Rede und geht an Bord der Flugmaschine \"Donnerschlag\". Sie ist der schnellste Weg zu Hochtüftler Mekkadrill, und er wartet nur noch auf diese Rede, bevor er Operation: Gnomeregan beginnt.\n\nGeht! Jetzt!", sourceObjective = "Benutzt die Flugmaschine \"Donnerschlag\" bei Stahlrosts Depot, um zu Hochtüftler Mekkadrill zu fliegen, und stellt ihm Tobys Rede zu.", sourceObjectiveStatus = "unverified-source-field" }
quests[25288] = { id = 25288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Kult infiltrieren", description = "Die Straßen von Orgrimmar sind voller Gerüchte über den Ursprung und die Praktiken des Kultes. Es gibt nur einen Weg, die Wahrheit über diese Gruppe herauszufinden, {name}. Ihr werdet ihnen beitreten.\n\nGeht auf einen der Weltuntergangsverkünder in der Gasse zu, und sagt ihm, dass Ihr der Gruppe beitreten wollt. Mit etwas Glück werden sie Euch die Anweisung geben, Euch einem ihrer Anführer vorzustellen, und Euch sagen, wo die Gruppe sich versteckt. Wenn euch der Weltuntergangsverkünder Kleidung gibt, zieht sie an; Ihr werdet sie wieder brauchen, um in das Versteck der Gruppe zu gelangen.", sourceObjective = "Sprecht in der Gasse in Orgrimmar mit einem Weltuntergangsverkünder, oder nehmt eine Robe von der Kiste neben einem Weltuntergangsverkünder, um dem Kult beizutreten. Zieht dann Eure Rekrutenrobe an.", sourceObjectiveStatus = "unverified-source-field" }
quests[25289] = { id = 25289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schritt nach vorn...", description = "Jetzt, da das Schleudersitzsystem funktioniert, sind wir bereit, Bewegungen zu testen. Dieser Panzer hat eine Besonderheit: Automatische Ausweichmanöver!\n\nIch möchte, dass Ihr die Servomotoren am linken Bein und am rechten Bein sowie das Automatische Ausweichmanöversystem ausprobiert.\n\nEs ist ganz einfach, also sollte es nicht lange dauern.", sourceObjective = "Testet die Manövrierbarkeit des krabbelnden Mechanopanzers.", sourceObjectiveStatus = "unverified-source-field" }
quests[25290] = { id = 25290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Kult infiltrieren", description = "Es wird schwierig, die Kultisten von der Öffentlichkeit fernzuhalten, und Gerüchte verbreiten sich in der Stadt. Ich will, dass Ihr dem Kult beitretet und so viel herausfindet, wie Ihr könnt.\n\nGeht auf einen der Weltuntergangsverkünder zu, und sagt ihm, dass Ihr ihrer Gruppe beitreten wollt. Der Weltuntergangsverkünder wird Euch wahrscheinlich Kleidung und die Anweisung, Euch mit anderen Kultisten in einem der Verstecke der Gruppe zu treffen, geben. Folgt diesen Anweisungen, {name}. Es ist der einzige Weg, um ihr Vertrauen zu gewinnen.", sourceObjective = "Sprecht mit einem Weltuntergangsverkünder in Sturmwinds Altstadt, oder nehmt eine Robe aus der Kiste neben einem Weltuntergangsverkünder, um dem Kult beizutreten. Legt dann die Robe des Weltuntergangsrekruten an, die Ihr erhalten habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25291] = { id = 25291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichttraining", description = "Ihr habt bewiesen, dass Ihr wert seid, zumindest an unserem grundlegendsten Training teilzunehmen.\n\nIhr findet eine unserer Siedlungen östlich von hier. Sprecht dort mit Instrukteurin Mylva.", sourceObjective = "Sprecht mit Instrukteurin Mylva auf dem Hyjal.", completion = "Also glaubt Ihr, dass Ihr bereit seid, den nächsten Schritt zu tun, Svitdamus?\n\nMal sehen, was Ihr leisten könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25292] = { id = 25292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die nächsten Verwandten", description = "<Nato zieht Euch beiseite und flüstert.>\n\n{name}, ich habe die Kugel aus Ganns Brust entfernt, aber die Blasen in seinem Blut sagen mir alles, was ich wissen muss. Seine Lunge ist durchstoßen und die Wunde entzündet sich. Er wird nicht mehr lange durchhalten.\n\nNehmt dies. Es ist die Kugel, die ihn getötet hat. Seine Familie wird sicher wissen wollen, was ihrem jüngsten Krieger zugestoßen ist.\n\nSucht Alto Steinkeil auf. Er ist in den Düstermarschen postiert. Geht nach Nordosten und folgt dem Weg nach Brackenwall.", sourceObjective = "Bringt die zwergische Gewehrkugel zu Alto Steinkeil in Brackenwall in den Düstermarschen.", progress = "Hallo, {class}. Ihr seid ja voller Staub statt voller Schlamm. Also kommt Ihr wohl vom Brachland hierher.", completion = "<Alto ballt die Faust um die Kugel, als Ihr ihm erzählt, was passiert ist.>\n\nGann? Tot? Ich… ich hätte es wissen sollen. Sein Temperament… seine Waghalsigkeit. Ich wusste, dass sie ihm eines Tages zum Verhängnis werden würden.\n\nAber es scheint, als hättet Ihr ihm bereits das Geschenk der Rache gemacht. Vielen Dank, {name}!\n\nUnd jetzt richtet Eure Aufmerksamkeit auf die Düstermarschen. Wenn die Allianz den Bau ihrer verfluchten Straße durch das Gebiet abschließt, sind all Eure Siege im Brachland vielleicht nichtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[25293] = { id = 25293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing" }
quests[25294] = { id = 25294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hundefütterung", description = "Hmmmpf… In letzter Zeit lassen die hier wohl einfach jeden rein.\n\nNa gut. Ihr habt in den Versuchsgründen sicher schon Loderos kennengelernt.\n\nNun, ich wurde mit der Aufgabe betraut, mich um einen seiner Welpen zu kümmern. Er ist jetzt schon ein echter Satansbraten. Wenn er später seinem Vater auch nur ein bisschen ähnlich wird, wird er unserer Sache gut dienen.\n\nSammelt Fleisch von den Basilisken in der Gegend und füttert ihn damit.", sourceObjective = "Sammelt 5 Stück verkohltes Basiliskenfleisch und füttert die Brut von Loderos damit.", completion = "Ausgezeichnet. Dieser kleine Welpe wird bestimmt einmal so groß und erbarmungslos wie sein Vater.", sourceObjectiveStatus = "unverified-source-field" }
quests[25295] = { id = 25295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer drücken", description = "Sicherheitssysteme bereit! Motorfunktion funktioniert! Jetzt müssen wir nur noch sicherstellen, dass die Geschütze feuern.\n\nDas sollte nicht schwer sein, {name}. Der Mechanopanzer auf dem Hügel hinter uns ist mit harmlosen Geschossen geladen worden. Feuert einfach ein paar Schüsse auf die Ziele in der Nähe und erstattet mir dann Bericht.", sourceObjective = "Testet die Waffensysteme des schießenden Mechanopanzers an den Zielen in der Nähe.", sourceObjectiveStatus = "unverified-source-field" }
quests[25296] = { id = 25296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sammelt Informationen", description = "Ich bin es, {name}, Ortell!\n\nSchaut nicht direkt auf das Plumpsklo… sonst verratet Ihr noch meinen Standort.\n\nAlso läuft alles nach Plan? Ausgezeichnet!\n\nIhr müsst für mich ein paar Informationen sammeln, während Ihr hier seid. Eine Karte oder ein Brief scheinen zwar nichts Weltbewegendes zu sein, aber den nächsten Schritt unseres Feindes vorauszusehen kann Hunderte von Leben auf unserer Seite retten.", sourceObjective = "Besorgt das Kommuniqué des Schattenhammers und die Hyjalschlachtpläne.", progress = "Habt Ihr die Dokumente, {name}?", completion = "Ausgezeichnete Arbeit, {name}. Oder sollte ich sagen \"Svitdamus\"?\n\nGebt meinen Männern eine Minute, um sich das hier durchzulesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25297] = { id = 25297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Schlund des Wahnsinns", description = "Ich kenne ein Gebräu, das diese stumpfsinnigen ehemaligen Sklaven wieder in die Wirklichkeit zurückholen sollte. Sammelt ein paar Steinblüten von den Felsen rund um Gar'gols Unterschlupf, ein paar Bitterblüten am Ufer des Sees in der Nähe und Schwarzfeuerglut aus einer der Kohlenpfannen am Eingang des Unterschlupfs. Das Gebräu hält nicht lange vor, also gebt alle Zutaten in einen Kessel des Schattenhammers am Eingang des Unterschlupfs.\n\nEin Schluck dieses Gebräus wird diesen hirnlosen Sklaven wieder Verstand einhauchen!", sourceObjective = "Sammelt Steinblüten, Bitterblüten und Schwarzfeuerglut.", progress = "<Im Kessel blubbert eine widerliche Flüssigkeit.>", completion = "<Ihr leert den derzeitigen Inhalt des Kessels aus. Die umstehenden Pflanzen verwelken sofort.>\n\n<Euer Gebräu ähnelt eher einem dicken Eintopf und stinkt nach verfaultem Kohl. Ihr dreht Euren Kopf zur Seite und füllt es in Flaschen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25298] = { id = 25298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiheit ist das Einzige, was zählt", description = "<Rio sagte, dass die Wirkung des Gebräus nicht lange anhalten wird.>\n\n<Ihr solltet schnell zum Unterschlupf eilen und es so vielen Zwielichtdienern wie möglich verabreichen.>", sourceObjective = "Sprecht mit 8 Zwielichtdienern, um ihnen das Gebräu zu verabreichen und sie zu retten.", progress = "Hat das Gebräu gewirkt?", completion = "Sehr gut! Wollen wir nur hoffen, dass der Schaden nicht dauerhaft ist.\n\nDem Zustand dieser armen Opfer hier im Lager nach zu urteilen haben die Schattenhammerkultisten ihren Geist ganz schön verwirrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25299] = { id = 25299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mentales Training: Wahrheit als Weg zur Macht", description = "Ihr glaubt vielleicht, dass Ihr bereit seid, das Wissen zu empfangen, das wir Euch vermitteln werden. Aber das seid Ihr nicht.\n\nStellt Euch Euren Geist als Kiste vor, die sich wiederum in vielen weiteren Kisten befindet.\n\nMit jedem Schritt unseres Trainings öffnet Ihr eine weitere Kiste, bis Ihr bereit seid, Euch direkt mit den Elementen zu verbinden.\n\nNehmt die Kugel des Aufstiegs und beantwortet alle Fragen, die sie Euch stellt. Wahrheitsgemäß! Jede falsche Antwort könnte... fatale Folgen haben.", sourceObjective = "Benutzt die Kugel des Aufstiegs und beantwortet 10 Fragen richtig.", completion = "Ihr hattet Erfolg, Svitdamus. Ihr seid bereit für den nächsten Schritt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25300] = { id = 25300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge des Zwielichts", description = "Der Ogerklan jenseits des Sees wird von Gar'gol geleitet. Nun ja, \"geleitet\" ist relativ. Gar'gol hat die Intelligenz eines rohen Stücks Fleisch.\n\nSoweit ich es beurteilen kann, nimmt Gar'gol Befehle von einem magischen Artefakt entgegen, dem \"Auge des Zwielichts\". Er folgt seinen Anweisungen, ohne Fragen zu stellen.\n\nWenn wir das Auge sabotieren könnten, würden wir unglaublichen Schaden anrichten.\n\nGeht zu Gar'gols Unterschlupf und sucht das Auge des Zwielichts in der Nähe des Eingangs. Untersucht es. Findet einen Weg, es Eurem Willen zu unterwerfen. Ah, welch wundervolles Chaos...", sourceObjective = "Sucht das Auge des Zwielichts in der Nähe des Eingangs zu Gar'gols Unterschlupf auf dem Hyjal.", completion = "<Ihr nähert Euch dem Auge des Zwielichts. Als Eure Fingerspitzen die leuchtende Oberfläche berühren, bemerkt Ihr eine bösartige Präsenz, die Euch anstarrt und Eure Seele durchforstet.\n\n<Instinktiv zieht Ihr Eure Hand zurück.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25301] = { id = 25301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worte der Herrschaft", description = "<Während der kurzen Kommunikation mit dem Auge konntet Ihr spüren, dass die Quelle seiner Macht tief in dem Unterschlupf verborgen liegt. Ihr konntet das Gewicht eines mächtigen Folianten spüren, der die vier Elemente aneinander fesselt.>\n\n<Wenn Ihr das Auge beherrschen wollt, müsst Ihr den Unterschlupf nach diesem Folianten durchsuchen.>", sourceObjective = "Findet die Zwielichtapokryphen in Gar'gols Unterschlupf auf dem Hyjal.", completion = "<Ein schwerer, in Haut gebundener Foliant liegt offen auf dem Tisch.>\n\n<Die bildartige Schrift in rostfarbener Tinte ist nicht entzifferbar und wirkt auf Euch wie Gekritzel. Zwischen einigen der Seiten liegen jedoch Notizen mit der Übersetzung. Das muss das Buch sein, nach dem Ihr sucht.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25302] = { id = 25302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überreste der Schlacht", description = "Hier fand einst eine große Schlacht statt. Zwischen den Nagaskeletten finden sich auch einige humanoide Skelette. Das könnte für XXX interessant sein.", sourceObjective = "Bringt das Bruchstück zu XXX in XXX.", sourceObjectiveStatus = "unverified-source-field" }
quests[25303] = { id = 25303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Eurem Element", description = "<Ihr könnt den Text nicht lesen, aber die Diagramme scheinen darauf hinzudeuten, dass die Geräte um Euch herum in einer bestimmten Reihenfolge aktiviert werden müssen.>\n\n<Ein Absatz der Apokryphen wurde in moderne Sprache übersetzt:>\n\nAm Anfang war der ewige Schatten.\nHass loderte und FEUER ward geboren.\nWunden vernarbten und zeugten die ERDE.\nSchmerzensschreie gebaren den WIND.\nUnd der Himmel weinte ein Meer aus TRÄNEN. \nWir leben im Schatten.\nDie Welt, die wir kennen\nErschaffen aus Wut, Leid, Schmerz und Tränen.", sourceObjective = "Aktiviert die vier in der Nähe befindlichen Elementartiegel in der richtigen Reihenfolge, um das Auge des Zwielichts zu kontrollieren.", progress = "<Ihr beugt Euch über die Apokryphen und versucht, einen Sinn hinter alldem zu erkennen.>", completion = "<Erfüllt von den Energien der gefangenen Elementare steht Ihr vor den Zwielichtapokryphen. Die Seiten blättern sich wie von Geisterhand um.>\n\n<Plötzlich seht Ihr, was das Auge sieht. Es steht unter Eurem Befehl!>", sourceObjectiveStatus = "unverified-source-field" }
quests[25304] = { id = 25304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Sardor", description = "Unsere Siedlung auf der Insel Sardor haben wir an die Nagaschuppen der Hasskämme verloren. Von ihren Zahlen überwältigt mussten wir uns auf das Festland zurückziehen. Während sie sich auf ihrem neuen Sandstrand vergnügten, haben wir an der Küste Neu-Mondfederfeste errichtet und eine weitaus größere Armee zusammengestellt.\n\nJetzt werden wir die Hasskämme zurück ins Meer jagen. Sucht das Urtum des Krieges an der Küste auf. Es wird Euch an die Front bringen. Tambre führt dort die Offensive an.", sourceObjective = "Sprecht mit Tambre auf der Insel Sardor.", completion = "Wir werden diese garstigen Kreaturen zurück ins Meer jagen. Ich hoffe, Ihr seid bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25305] = { id = 25305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Blick zurück", description = "Unsere Siedlung auf der Insel Sardor haben wir an die Naga der Hasskämme verloren. Von ihren Zahlen überwältigt mussten wir uns auf das Festland zurückziehen. Während sie sich auf ihrem neuen Sandstrand vergnügten, haben wir an der Küste Neu-Mondfederfeste errichtet und eine weitaus größere Armee zusammengestellt.\n\nJetzt werden wir die Hasskämme zurück ins Meer jagen. Fordert Schildwache Ranadae auf, sich unseren Truppen auf Sardor anzuschließen. Tötet die Naga und sorgt dafür, dass auch derjenige stirbt, der ihnen die Befehle erteilt.", sourceObjective = "Tötet 10 Naga der Hasskämme und ihren Anführer.", sourceObjectiveStatus = "unverified-source-field" }
quests[25306] = { id = 25306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr seid jetzt in der Gnarmee!", description = "Krieg!", sourceObjective = "Beschreibung", sourceObjectiveStatus = "unverified-source-field" }
quests[25307] = { id = 25307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lauschangriff" }
quests[25308] = { id = 25308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saat der Zwietracht", description = "Nach den Informationen, die Ihr gesammelt habt, gibt es starke Spannungen zwischen den Ogern und Nicht-Ogern des Kults.\n\nHochkultist Azennios und der Ogermagier Karr'gonn treffen sich am Sitz der Auserwählten, um zu versuchen, diese Konflikte zu mildern.\n\nAm Sitz der Auserwählten gibt es ein Plumpsklo wie dieses. Geht dorthin und zieht Euch diese Ogerverkleidung an. Sucht nach einem Weg, Azennios auf seiner Friedensmission zu töten.\n\nWir müssen diese Zwietracht so gut es geht ausnutzen!", sourceObjective = "Lenkt Karr'gonn ab und tötet Hochkultist Azennios am Sitz der Auserwählten auf dem Hyjal.", completion = "Ausgezeichnete Arbeit, {name}! Dieses Mal habt Ihr Euch wirklich selbst übertroffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25309] = { id = 25309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirituelles Training: Mitleid ist etwas für Schwächlinge", description = "Ihr habt es so weit geschafft. Andere nicht.\n\nGeht zur Verdammniswacht direkt nördlich von hier. Wir haben alle… Versager zusammengetrommelt. Ich möchte, dass Ihr Euch um sie kümmert. Das ist gut für Euer spirituelles Wachstum.\n\nWenn Ihr Probleme mit einem so kaltblütigen Verhalten haben solltet, betrachtet es einfach als ihre zweite Chance. Sollte es nämlich jemandem von ihnen gelingen, Euch zu töten... nun, dann nimmt er Euren Platz ein.", sourceObjective = "Tötet 5 gescheiterte Bittsteller in der Verdammniswacht.", completion = "Ihr seid auf der Überholspur zum Erfolg. Wollen wir hoffen, dass Ihr Eure makellose Bilanz nicht mit solchen Albernheiten wie Barmherzigkeit und Menschlichkeit verderbt.\n\nKommt schon. Lasst uns über Eure Zukunft sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25310] = { id = 25310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das größere von zwei Übeln", description = "Wir haben die Flüsternde Schlucht mit Gewalt von den Dämonen der Brennenden Legion zurückerobert. Bis jetzt haben wir unser Gebiet ganz gut verteidigen können, bis auf eine Ausnahme.\n\nKürzlich haben wir die Tore von Sothann an einen Grubenlord und seine Armee verloren. Das können wir nicht auf sich beruhen lassen.\n\nBenutzt diesen Talisman, wenn Ihr in seiner Nähe seid. Ihr erhaltet dann kurzzeitig die Macht eines Flammenaszendenten. Nutzt sie gut!", sourceObjective = "Benutzt den Talisman der Flammenaszendenz und tötet Garnoth, die Faust der Legion, an den Toren von Sothann auf dem Hyjal.", completion = "Ausgezeichnete Arbeit, Svitdamus. Wir müssen allen Möchtegerngegnern zeigen, dass wir nicht so leicht aufgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25311] = { id = 25311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenhammergebiet", description = "Die Dämonen der Brennenden Legion glauben, sie könnten hier einfach so aufkreuzen und sich jedes Gebiet nehmen, das ihnen gefällt. Sicher, das Gebiet gehörte früher ihnen, aber darum geht es ja nicht.\n\nWir werden ihnen beibringen, dass sie sich nicht mit dem Schattenhammer anlegen sollten.\n\nBrecht zu den Toren von Sothann auf und vernichtet den Horrorwachentrupp, der in diesem Gebiet sein Unwesen treibt.", sourceObjective = "Tötet 10 Horrorwachen an den Toren von Sothann auf dem Hyjal.", progress = "Ist es schon erledigt, {race}?", completion = "Pünktlich wie immer. Ihr enttäuscht mich nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25312] = { id = 25312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Abendwisper", description = "<Ihr zwingt Euer eigenes Bild in das Auge und bringt es dazu, den Ogern andere Befehle zu geben. Währenddessen spürt Ihr eine andere Präsenz im Auge, die Euch begutachtet und nach Euren Schwächen sucht. Ein weit entferntes Wesen schäumt vor Wut. Ihr habt Euch heute ein paar Feinde gemacht!>\n\n<Eure Arbeit hier ist getan, und die Oger werden Euch gegenüber freundlich sein. Kehrt zu Royce Abendwisper am Schrein von Goldrinn zurück und berichtet ihm, was Ihr erreicht habt.>", sourceObjective = "Kehrt zu Royce Abendwisper am Schrein von Goldrinn auf dem Hyjal zurück.", completion = "Hallo, ja? Was? Ihr? Oh, Ihr seid einer von denen, die ich auf die Suche nach dem Auge des Zwielichts geschickt habe, oder?\n\nGute Arbeit, sehr gut. Ich schätze, das ist eine wichtige Lektion für Euch:\n\nNehmt niemals Befehle von einem großen violetten Ball an.", sourceObjectiveStatus = "unverified-source-field" }
quests[25313] = { id = 25313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Überläufer", description = "Bleibt wo Ihr seid! Bitte, ich flehe Euch an!\n\nIch bin nur wegen eines Mädchens hier. Ihre Worte waren so süss… aber jetzt erkenne ich den Wahnsinn dahinter.\n\nNehmt diesen Umschlag. Er enthält einige Informationen, die Euch sicher einen Stein im Brett Eurer Vorgesetzten einbringen werden.\n\nDie Wachen sind abgelenkt... Ich kann mich aus dem Staub machen. Bitte. Ich will nicht sterben!", sourceObjective = "Bringt den belastenden Brief zu Elementarist Ortell im Plumpsklo an der Schmiede der Unterwerfung auf dem Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[25314] = { id = 25314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redenschreiben für Anfänger", description = "Hört zu, {name}. Ich habe herausgefunden, was Sie mit Jarod Schattensang vorhaben. Die Oger des Schattenhammers wollen ihn als Teil des diesjährigen Initiationsritus opfern.\n\nIch habe gehört, dass der Initiand, der dieses Jahr die Opferrede hält, ein Oger namens Okrog ist, aber jetzt kommt die Überraschung: Ihr seid nur knapp <Zweiter/Zweite> geworden!\n\nWenn wir Jarod befreien möchten, müsst Ihr diese Rede halten. Keine Sorge, ich schreibe Euch ein paar Stichworte auf. Ihr müsst nur dafür sorgen, dass Okrog auf seinem Weg vom Sitz der Auserwählten einen kleinen \"Unfall\" hat.", sourceObjective = "Tötet Okrog außerhalb des Sitzes der Auserwählten auf dem Hyjal.", completion = "Ausgezeichnete Arbeit, {name}. Unser Plan ist nun fast vollständig.", sourceObjectiveStatus = "unverified-source-field" }
quests[25315] = { id = 25315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abschlussrede", description = "Ihr seid endlich fertig, {name}damus.\n\nIch bin so stolz auf Euch und alles, was Ihr erreicht habt.\n\nHeute werdet Ihr eine Rede vor Euren Gleichrangigen halten und sie anfeuern, unsere Feinde zu vernichten, bis der Hyjal nur noch ein Häuflein Asche ist.\n\nVergesst nicht, {name}damus. Es ist wichtig, dass Ihr die Gefühle Eures Publikums zu deuten wisst und Worte verwendet, die diesen Gefühlen entsprechen.", sourceObjective = "Benutzt das Initiationspodium in der Verdammniswacht, um die Abschlussrede zu halten.", progress = "Seid Ihr gekommen, um mich kaltzumachen?\n\nNein… Ihr scheint mir… klar im Kopf.", completion = "Ihr. Ihr gehört ganz offensichtlich nicht zu denen.\n\nWer seid Ihr dann? Ein Verbündeter?", sourceObjectiveStatus = "unverified-source-field" }
quests[25316] = { id = 25316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hyjal in Flammen", description = "{name}! Wir haben schon so viel von Euch und Euren früheren Heldentaten gehört.\n\nEs ist gut, dass Ihr gerade jetzt hier seid, wo Azeroth Euch am meisten braucht.\n\nTodesschwinges Diener greifen den Hyjal an und haben vor, den zerstörerischen Ragnaros in unsere Welt zurückzubringen.\n\nAronus wird Euch zu Malfurions Streitmächten auf dem Hyjal bringen. Helft ihnen, wo Ihr könnt!", sourceObjective = "Fliegt mit Aronus zum Hyjal und sprecht mit Ysera, sobald Ihr angekommen seid.", completion = "<Ysera scheint in einer Art Trance zu sein.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25317] = { id = 25317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schützt den Weltenbaum", description = "<Yseras Augen sehen abwesend aus, als würde sie Euch nicht ganz erkennen.>\n\nIch fühle es auch, {class}. Ragnaros ist eingetroffen.\n\nWir müssen seine Diener vernichten, bevor er sich ihnen anschließen und ihnen seine Macht leihen kann.\n\nSucht Malfurion Sturmgrimm im Friedvollen Hain westlich von hier auf und helft seinen Streitmächten so gut Ihr könnt.\n\nIch muss im Smaragdgrünen Traum nach Antworten suchen. Ihr müsst den Weltenbaum beschützen, bis ich zurückkehre.", sourceObjective = "Sprecht mit Malfurion Sturmgrimm im Friedvollen Hain auf dem Hyjal.", completion = "Ihr seid gerade rechtzeitig angekommen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25318] = { id = 25318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichtschlachtpläne" }
quests[25319] = { id = 25319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg dem Schattenhammer", description = "Gebt Euch keinen Illusionen hin, {name}. Der Ausgang dieses Krieges entscheidet über das Überleben der Welt, wie wir sie kennen.\n\nDer Schattenhammerkult ist mit Todesschwinges Rückkehr sogar noch mächtiger geworden. Falls es ihnen gelingen sollte, den Weltenbaum an sich zu reißen, könnten sie uns einen Schlag versetzen, von dem wir uns nie erholen werden.\n\nEs ist an der Zeit, den Feind zurückzudrängen. Es ist an der Zeit, den Schattenhammer zu vernichten.", sourceObjective = "Tötet 4 Zwielichtflammenrufer und 10 Zwielichtbezwinger.", completion = "Das habt Ihr gut gemacht, {name}. Aber ich fürchte, dass die Schlacht noch lange nicht vorüber ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25320] = { id = 25320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gefangene Späherin", description = "Ich habe von Euch gehört, {name}, und ich kenne die Nachrichten, die Ihr aus dem Süden bringt. Die Schlacht hat eine Pattsituation erreicht.\n\nDoch ich fürchte, dass sich diese Lage mit dem Wiedererwecken des Feuerlords schlagartig ändern wird.\n\nEs sei denn natürlich, wir könnten das Schicksal zu unseren Gunsten beeinflussen.\n\nEine unserer Späherinnen wurde vom Schattenhammer gefangen genommen. Ich glaube, sie war im Besitz von unschätzbar wertvollen Informationen. Sucht im Zwielichtlager im Westen nach ihr.", sourceObjective = "Findet Späherin Larandia bei der Zwielichtblockade auf dem Hyjal.", completion = "Endlich kommt mir jemand zu Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[25321] = { id = 25321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangene des Zwielichts", description = "Ich habe fast einen ganzen Tag lang hinter den feindlichen Reihen gespäht, bis sie mich gefasst haben.\n\nDieser Angriff an unserer Front ist nicht das, was er zu sein scheint, {name}.\n\nIch berichte Euch alle Einzelheiten, aber holt mich zuerst hier raus!\n\nNur die Vorarbeiter haben die Schlüssel zu diesen Käfigen.\n\nSoweit ich mich erinnern kann, halten sie sich in der Mitte des Kraters auf, mitten im Getümmel.\n\nSchaut, ob Ihr einem von ihnen einen Schlüssel abnehmen könnt.", sourceObjective = "Beschafft Euch einen Schlüssel eines Zwielichtvorarbeiters im Schattenkommandoposten auf dem Hyjal.", progress = "Der Schlüssel, {name}. Habt Ihr ihn?", completion = "Ich bin Euch sehr dankbar, {name}. Ich werde unseren Leuten von meinen Erkenntnissen berichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25322] = { id = 25322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flammende Inschriften", description = "Ein solches Medaillon habt Ihr noch nie gesehen. Seine Runen scheinen in der Nähe der Feuerelementare aufzuleuchten.\n\nVielleicht solltet Ihr Hamuul Runentotem davon berichten.", sourceObjective = "Sprecht mit Hamuul Runentotem auf dem Hyjal.", sourceObjectiveStatus = "unverified-source-field" }
quests[25323] = { id = 25323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flammenbrecher", description = "Die großen Elementare, die uns belagern, sind keine einzelnen Wesen.\n\nEs sind mehrere geringere Geister, durch die Magie der Schattenhammerkultisten zu einem verbunden.\n\nMit dem wiederhergestellten Flammenseherstab sind wir mächtig genug, dieses Band zu lösen.\n\nSobald Ihr die gefährlicheren großen aufgespalten habt, vernichtet die kleineren Elementare.", sourceObjective = "Tötet 30 ungebundene Flammengeister.", progress = "Habt Ihr Eure Aufgabe erledigt, {name}?", completion = "Gut gemacht, {name}. So gewinnen wir die Oberhand über den Feind.", sourceObjectiveStatus = "unverified-source-field" }
quests[25324] = { id = 25324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein interessanter Gefangener", description = "Der Schattenhammer möchte Fandral Hirschhaupt befreien?\n\nMalfurion ist der Meinung, dass seine Verderbtheit weit fortgeschritten ist... und dies ist der beste Beweis dafür.\n\nWir können auf keinen Fall zulassen, dass unser Feind einen so mächtigen Erzdruiden in die Finger bekommt.\n\nIch habe einen Plan, {name}. Wir werden den Gefangenen durch den Smaragdgrünen Traum fortschaffen. Es wird riskant, aber bei den ganzen Kultisten hier ist es vielleicht unsere einzige Hoffnung auf Erfolg.\n\nBringt diesen Schlüssel zu Saynna Sturmläufer in den Grabhügeln im Nordosten.", sourceObjective = "Sprecht mit Hauptmann Saynna Sturmläufer in den Grabhügeln auf dem Hyjal.", completion = "Der Drache hat vielleicht Recht. Der Schattenhammer hat unsere Sicherheitsmaßnahmen umgangen. Und dies ist schließlich unser gefährlichster Gefangener.", sourceObjectiveStatus = "unverified-source-field" }
quests[25325] = { id = 25325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch den Traum", description = "Alysras Plan ist vielleicht notwendig, {name}. Ich weiß nicht, wie lange wir die Kultisten noch zurückhalten können.\n\nFandral Hirschhaupt wird von mächtigen Zaubern gebunden. Er könnte Euch nicht einmal im Smaragdgrünen Traum entkommen.\n\nDoch seid vorsichtig, denn soweit wir wissen, hat der Alptraum sich innerhalb des Traums auf diesen Teil der Welt ausgebreitet.\n\nBringt Fandral an die Oberfläche und übergebt ihn Alysra. Wollen wir hoffen, dass er auf der Mondlichtung sicherer aufgehoben ist als hier.", sourceObjective = "Liefert Erzdruide Fandral Hirschhaupt an Alysra am Eingang zu den Grabhügeln auf dem Hyjal aus.", completion = "Das habt Ihr gut gemacht, {name}. Ich werde Fandral selbst zur Mondlichtung bringen.\n\nSein Gefängnis wird weit genug von der Schlacht hier entfernt liegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25326] = { id = 25326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stoppt ihren Rückzug" }
quests[25327] = { id = 25327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erwachen" }
quests[25328] = { id = 25328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gar'gol muss gehen!", description = "<Kristoff reckt seinen Hals, um Euch in die Augen blicken zu können.>\n\nHört zu, Ihr müsst mich hier rausholen. Entweder fressen sie mich oder sie übergeben mich dem Schattenhammer. Vielleicht sogar beides.\n\nSie haben mich in Ketten gelegt und sie mit einem Schloss fest gesichert. Gar'gol bewahrt den Schlüssel in seiner persönlichen Schatzkiste auf. Tötet Gar'gol, wenn Ihr müsst, solange Ihr mir den Schüssel besorgt!\n\n<Kristoff schüttelt verzweifelt seine Gliedmaßen.>", sourceObjective = "Besorgt den rostigen Schädelschlüssel aus Gar'gols persönlicher Schatzkiste.", progress = "Schlüssel? Jetzt? Bitte?", completion = "<Kristoff streckt sich nach unten, um den Schlüssel zu schnappen.>\n\nDas wurde aber auch Zeit!\n\n<Er windet sich in seinen Fesseln und versucht, das Schloss auf seinem Rücken zu erreichen.>\n\nÄh… könnt Ihr mir hier vielleicht ein bisschen helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[25329] = { id = 25329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht der Steinbrecher", description = "Der Schattenhammer meint also, hier eine Ogerarmee aufstellen zu können? Mitten im Gebiet der Horde?\n\nDas werden wir sehen.\n\nOger respektieren nur eines: Stärke. Ich möchte, dass Ihr bei der Zeremonie von Cho'gall ein Attentat verübt, {name}. Reißt die Tore Düsterbruchs auf, begebt Euch in die Menge der Anwesenden und ermordet sie.", sourceObjective = "Stört die Schattenhammerzeremonie Cho'galls.", completion = "Wir haben es geschafft! Cho'gall wurde von Euch absolut gedemütigt. Seine Diener sind tot, die Gordok sind in alle Richtungen verstreut, und alle werden von der Macht der Horde erfahren! Lok'tar, {name}! Ihr habt Euch Eure Belohnung redlich verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[25330] = { id = 25330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschwendetes Fleisch", description = "Schaut Euch diese Narren an. Die Hälfte von ihnen wird nicht einmal diese Prüfung bestehen.\n\nSie sind es nicht wert, in unsere inneren Kreise aufzusteigen. Aber vielleicht… vielleicht eignen sie sich ja für niedere Lakaiendienste.\n\nNehmt diesen Edelstein und nutzt seine Macht, um einige der weniger fähigen Bittsteller zu retten. Diejenigen, die keine Chance auf Erfolg haben. Bevorzugt jene, die in Flammen stehen.", sourceObjective = "Benutzt den Froststurmkristall, um 4 brennende Bittsteller zu löschen.", completion = "Ausgezeichnete Arbeit, Svitdamus. Ich lasse die Diener, die Ihr für mich ausgesucht habt, in ihre neuen Pflichten einweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25331] = { id = 25331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Omas Katze", description = "Genau! Was die Evakuierung angeht, Liebes.\n\nIch kann nicht ohne meine Katze gehen. Er ist ein zuckersüßer orangefarbener Tigerkater.\n\nFelix spielt am liebsten in der Nähe eines alten Karren in der Nähe einer Laube nordöstlich von hier.\n\nBringt ihn zu mir, dann können wir sofort aufbrechen.", sourceObjective = "Oma Wahl in Wahls Landhaus möchte, dass Ihr Felix die Katze holt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25332] = { id = 25332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holt mich hier raus!", description = "<Ihr greift nach oben, um Kristoffs Fesseln zu lösen.>\n\nGut! Spurtet zum Ausgang. Ich werde Euch folgen.\n\nWenn wir getrennt werden, meldet Euch wieder hier und stellt sicher, dass sie mich nicht erneut geschnappt haben.", sourceObjective = "Begleitet Kristoff aus Gar'gols Unterschlupf hinaus.", completion = "Kristoff, Kristoff… Oh ja, jetzt erinnere ich mich. Ich habe ihn auf etwas geschickt, was man als Selbstmordmission bezeichnen könnte.\n\nEr hat überlebt? Das heißt dann wohl, dass er gescheitert ist.\n\nDennoch verdient Ihr eine kleine Entlohnung für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25333] = { id = 25333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht der Schildwachen", description = "Der Schattenhammer? Hier?\n\nEs ist schwerwiegender, als ich dachte. Wir müssen dem ein Ende setzen. Ich weiß nicht, ob ich bereit bin, eine solche Offensive zu führen, aber ich werde nicht zulassen, dass etwas, was getan werden muss, unterlassen wird, nur weil ich Angst habe!\n\nIch werde die Streitkräfte der Mondfederfeste versammeln. Begebt Euch nach Düsterbruch, um die Aktivitäten von Cho'gall zu stören. Wir werden die Verwirrung, die dadurch entsteht, für unseren Angriff nutzen.", sourceObjective = "Stört die Schattenhammerzeremonie Cho'galls.", completion = "Willkommen zurück von der Schlacht! In den Augen der Gordunni wurde der Schattenhammer erniedrigt und aus Feralas vertrieben.\n\nWir haben die Ehre der Allianz heute in vollem Glanz gezeigt! Seid stolz!", sourceObjectiveStatus = "unverified-source-field" }
quests[25334] = { id = 25334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die drohende Gefahr", description = "Fühlt Ihr, wie wüt'nd die Elemente sind? Schon als wir gerade erst angekomm'n war'n, wollt'n sie uns angreif'n und fress'n. Wir müss'n sie beruhigen, aber dazu müss'n wir erstmal wiss'n, was sie überhaupt aufbringt.\n\nKommt und setzt Euch neb'n mich ans Feuer. Lasst Eure Gedank'n in den Flamm'n streif'n... Lasst Eur'n Geist in die wahre Bedrohung blick'n.", sourceObjective = "Sprecht mit Scharfseher Gadra, um in Eure Geistertrance einzutauchen.", progress = "Verliert Euch ganz in den tanz'nden Flamm'n. Kommt mit mir, tiefer nach Vashj'ir, damit wir das Gesicht unseres Feindes kennenlern'n.", completion = "Wir dacht'n alle, dass es die Naga sind, aber ich wusste nich', dass der Schattenhammerkult sich unter den Well'n versteckt. Sie verderb'n und verdreh'n die Elemente und mach'n sie zu dies'n Schreck'n.\n\nWir müss'n diese beid'n Bedrohung'n bekämpf'n, um eine Chance auf Fried'n in Vashj'ir zu hab'n. Wir hab'n noch nich' genug Leute, um das zu tun.\n\nKommt, {class}. Wir hab'n viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[25335] = { id = 25335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Natürliche Materialien", description = "Ich benötige bestimmte Materialien, um mein Vorhaben zu vervollständigen... Ihr könnt das für mich erledigen, zusammen mit den anderen Aufgaben, die ich Euch stellen werde.\n\nIch brauche einen abgesplitterten Stamm eines Treants aus Feralas. Verkrustete Mineralien könnt Ihr an den Bergriesen und Feendrachen im Westen finden. Sucht mir einige widerstandsfähige Sehnen von den Eulenbestien im Hinterland oder den Hippogryphen von Feralas. Als Letztes benötige ich eine große Menge metallischer Fragmente von einer der Bestien, die ich erwähnt habe.", sourceObjective = "Bringt 2 abgesplitterte Baumstämme, 6 verkrustete Mineralien, 20 Stücke widerstandsfähige Sehne und 40 metallische Fragmente zu Hexendoktor Uzer'i ins Camp Mojache.", sourceObjectiveStatus = "unverified-source-field" }
quests[25336] = { id = 25336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gefäß wird getestet", description = "Meister Uzer'i hat mich in der Herstellung mächtiger Geisterwaffen unterrichtet. Ich werde Euch unterweisen, wie man die Waffen herstellen kann, wenn Ihr mir die Möglichkeit gebt, mein Handwerk zu verfeinern.\n\nDieses Gefäß kann besiegte Kreaturen verkleinern und gefangen halten. Wir brauchen zuerst Eisenfellbärenmuisek und Langzahnläufermuisek. Tötet die Kreaturen und benutzt das Muisekgefäß, um sie zu schrumpfen und einzufangen, bevor ihre Geister fliehen können.", sourceObjective = "Tötet 10 Eisenfellbären oder Langzahnläufer, und benutzt das Gefäß für Bestienmuisek, um die gefallenen Bestien zu schrumpfen und einzufangen.", progress = "Konntet Ihr das Bestienmuisek erhalten?", completion = "Wie mein Meister es mir erklärt hat...\n\nNach einem gewaltsamen Tod kann das Muisek einer Kreatur fliehen und Rache verlangen. Durch das Schrumpfen der Kreaturen wird die Flucht verhindert. Das habt Ihr ja auch gemacht, {name}. Jetzt können wir das Muisek nach Herzenslust verwenden!", sourceObjectiveStatus = "unverified-source-field" }
quests[25337] = { id = 25337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muisek von Hippogryphen", description = "Als Nächstes sind die Hippogryphen dran.\n\nLaut Meister Uzer'i sind die Hippogryphen den Nachtelfen jahrelang treue Begleiter gewesen, und ihre Geister sind loyal und standhaft.\n\nIch glaube nicht, dass es ihnen auffallen wird, wenn ein paar Hippogryphen fehlen, und selbst wenn, dann soll mich das nicht stören. Wir brauchen Muisek von zehn Fransenfederhippogryphen, die in der Wildnis südlich von hier zu finden sind.", sourceObjective = "Schaltet 10 Fransenfederhippogryphen eines beliebigen Typs aus und benutzt dann das Muisekgefäß, um sie zu schrumpfen und einzufangen.", progress = "Konntet Ihr die Hippogryphen einfangen?", completion = "Mein Meister hat immer gesagt, \"wenn man ein Tier tötet und das Muisek flieht, so kann es die Form einer noch wilderen Bestie annehmen\". Es ist wirklich gefährlich. Ich danke Euch, dass Ihr mir bei meinem Studium helft.", sourceObjectiveStatus = "unverified-source-field" }
quests[25338] = { id = 25338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muisek von Treants", description = "Die umherwandernden Waldgänger, die überall im Wald zu finden sind, sind unser nächstes Ziel, {name}. Nachtelfen haben Treants als Verbündete rekrutiert, um gegen die Horde zu kämpfen. Sie mögen zwar langsam sein, aber als Beschützer sind sie nicht zu unterschätzen.\n\nBald werden wir diese Macht für unsere eigenen Zwecke nutzen können.\n\nFindet drei umherwandernde Waldgänger, schaltet sie aus und benutzt das Muisekgefäß, um sie zu schrumpfen und einzufangen.", sourceObjective = "Schaltet 3 umherwandernde Waldgänger aus. Benutzt das Muisekgefäß, um die gefallenen Treants zu schrumpfen und einzufangen.", progress = "Konntet Ihr die wandernden Waldgänger einfangen?", completion = "Danke, {name}. Das ist das erste Mal, dass ich mit Treantmuisek arbeite...", sourceObjectiveStatus = "unverified-source-field" }
quests[25339] = { id = 25339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache an den Nordschwingen", description = "Zu meiner Zeit war ich ein erfahrener Jäger. Es gab keine Kreatur, die ich fürchtete. Bis...\n\nIch war draußen im Wald, um nach einem heftigen Kampf meine Klinge zu schärfen, als ich in einen Hinterhalt geriet. Harpyien umzingelten mich, und ich schaffte es kaum, mich in Sicherheit zu bringen.\n\nSelbst heute noch kann ich das Echo ihrer Schreie vernehmen...\n\nDanach war ich nicht mehr derselbe. Aber der Hass kocht in meinem Inneren - ich will Rache, auch noch nach all diesen Jahren.\n\nDie Harpyien der Nordschwingen leben westlich von hier. {name}, rächt mich.", sourceObjective = "Tötet 6 Harpyien der Nordschwingen und 6 Windruferinnen der Nordschwingen.", completion = "Danke, {name}. Ihr habt dem Geist eines alten Tauren Ruhe gegeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25340] = { id = 25340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkles Herz", description = "Edana Hasskralle ist die Königin der Nordschwingen, die in den Ruinen im Westen zu Hause sind. Sie ist das vollkommen Böse; ich habe gehört, dass sie ein Herz aus Kristall hat. Sie ist bar jeglicher Emotionen außer dem Hass, den sie für alle anderen fühlt. Ihr müsst Euch Edana stellen und mir ihr dunkles Herz zurückbringen.\n\nIch habe von einem Horn gehört, das die Harpyien tragen - wenn es bei den Hasskrallensteinen, im nördlichen Teil der Ruinen, geblasen wird, wird die Königin beschworen.\n\nStellt Euch ihre Überraschung vor, wenn es nicht die ihren sind, die auf sie warten, sondern ihr Tod.", sourceObjective = "Talo Dornhuf im Camp Mojache will das dunkle Herz von Edana Hasskralle.", progress = "Der Hass, den Edana über das Land verbreitet, muss gestoppt werden.", completion = "Jetzt weiß ich, dass Edana wahrhaft tot ist. Dieses Herz; ich werde es in Erinnerung an das behalten, was Ihr hier für mich getan habt, {name}. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[25341] = { id = 25341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gordunnikugel", description = "Während Ihr Schädel eingeschlagen habt...\n\nWir haben Berichte erhalten, laut denen die Oger eine größere Bedrohung darstellen als normalerweise. Ihre Hexenmeister wurden mit Kugeln gesehen, die Gegenstände mit großer Macht sein könnten.\n\nEs wäre einfach, sie als etwas anderes abzutun, aber wir müssen der Sache nachgehen, damit es keine bösen Überraschungen gibt. Bringt mir eine dieser Kugeln.", sourceObjective = "Erlangt eine Gordunnikugel von einem Hexenmeister der Gordunni.", progress = "Habt Ihr die Kugel?", completion = "Gut gemacht. Lasst mich mal sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25342] = { id = 25342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Swar'jan", description = "Hmpf, wir hatten Glück und Pech zur gleichen Zeit. Glück, dass ich Euch gebeten habe, mir diesen Gegenstand zu bringen, und Pech, weil sich meine Befürchtungen bewahrheitet haben. Dieses Ding stinkt förmlich nach Verderbtheit.\n\nUnd es ist auch viel zu neu, um einfach in den Ruinen gefunden worden zu sein. Jemand versorgt die Oger und wir müssen herausfinden, wer, bevor es ein Problem wird.\n\nBringt dieses dreckige Ding zu Swar'jan, dem Hexenmeister oben auf dem Wachturm. Er hat oft gute Ideen - wenn ich Ihr wäre, würde ich mir seine Meinung anhören.", sourceObjective = "Bringt die Gordunnikugel zu Swar'jan in der Festung der Steinbrecher.", progress = "Ja?", completion = "Was habt Ihr für mich? Ihr sagt, Ihr habt sie von den Gordunni?\n\nEkelhaft...", sourceObjectiveStatus = "unverified-source-field" }
quests[25343] = { id = 25343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Plan des Meisters", description = "Ihr passt hier gut her, {name}, aber es gibt mehr zu tun als tägliche Pflichten und das Verkünden der Botschaft. Ich bin sicher, dass Ihr ein wenig darüber gehört habt, als Ihr beigetreten seid.\n\nWie Ihr wisst, geht diese Welt unter, und die Unvorbereiteten werden eines qualvollen Todes sterben.\n\nUns dagegen wurde ein Geschenk zuteil, die Gelegenheit, zu etwas größerem, mächtigeren zu werden. Aufseher Golbaz wird vor dem Altar an der Ostseite des Hofes ein Ritual abhalten. Wartet dort auf ihn, und lernt mehr über Eure neuen Brüder und Schwestern.", sourceObjective = "Erfahrt am Altar im Osten des Scheckeneberhofes mehr über die Pläne der Kultisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25344] = { id = 25344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogerentführung", description = "Es ist unmöglich, dass die Gordunni sie selbst hergestellt haben. Sie werden damit versorgt. Jemand macht ihnen Machtgeschenke und wir müssen herausfinden, wer.\n\nDie Gordok, die mit der Aufgabe geehrt werden, Düsterbruch zu bewachen, werden mehr darüber wissen. Orhan wird dich sicherlich beauftragen, ihre Reihen zu lichten, aber ich brauche einen, der am Leben ist.\n\nBringt die Kugel zurück. Sie ist einem Seelenstein ähnlich, und ich habe einige... Änderungen vorgenommen. Haltet die Kugel vor einem geschwächten Gordok hoch, und bringt ihn hier her, sobald Ihr ihn gefangen habt.", sourceObjective = "Benutzt die modifizierte Seelenkugel, um einen Ogermagier der Gordok gefangenzunehmen.", completion = "Ahh, man kann den Welpen in ihm spüren. Wir sollten ihm ein paar Fragen stellen...", sourceObjectiveStatus = "unverified-source-field" }
quests[25345] = { id = 25345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muisek von Feendrachen", description = "{name}, als Nächstes müsst Ihr für mich eine Kreatur fangen, die vom Aussehen her sehr zerbrechlich scheint, aber ihr mächtiger Geist ist das, was wir eigentlich besitzen wollen. Die Feendrachen, von denen ich spreche, dienen den Nachtelfen als Verbündete. Wir müssen einen von ihnen einfangen, damit auch die Horde von seiner Geisteskraft profitieren kann.\n\nHier ist das Muisekgefäß, {name}. Schaltet 8 Grimmlingflitzer oder Grimmlingdrachen aus und fangt ihr Muisek ein. Ihr könnt sie westlich von hier finden.", sourceObjective = "Schaltet 8 Grimmlingflitzer oder Grimmlingdrachen aus. Benutzt das Muisekgefäß, um die gefallenen Feendrachen zu schrumpfen und einzufangen.", progress = "Konntet Ihr das Muisek der Feendrachen einfangen?", completion = "Danke, {name}. Jetzt steht die geistige Macht der Feendrachen auch uns zur Verfügung.\n\nIch hoffe, Ihr seid willens, eine weitere Aufgabe für mich zu vollbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25346] = { id = 25346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergriesenmuisek", description = "Die Bergriesen haben die Berge verlassen, um den Nachtelfen zu helfen, als die Brennende Legion erschien. Ihr könnt sie leicht an ihrer Größe erkennen, und auch schon von Weitem daran, wie der Boden wackelt, wenn Ihr Euch ihnen nähert.\n\nIch bin sehr interessiert daran, Kraft in diesem Ausmaß nutzen zu können. Tötet sieben Bergriesen und benutzt das Muisekgefäß, um ihre mächtigen Muisek einzufangen.", sourceObjective = "Tötet 7 Bergriesen und benutzt das Gefäß für Bergriesenmuisek, um die gefallenen Bergriesen zu schrumpfen und einzusammeln.", progress = "Konntet Ihr die Bergriesen gefangennehmen?", completion = "Stellt Euch nur die Möglichkeiten vor, die wir nun haben, {name}. Mit den Materialien, die Ihr gesammelt habt, werden wir den Muisek dieser Kreaturen festhalten können, wo immer wir es wünschen", sourceObjectiveStatus = "unverified-source-field" }
quests[25347] = { id = 25347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weltuntergangsplan", description = "Die erste Ladung Elementargeräte ist bereit. Eure Aufgabe ist, sie im Stadtgebiet von Orgrimmar zu verstecken. Die Geräte werden ihre Feuerelementare freilassen, wenn die Zeit reif ist. Keine Sorge, {name}, Ihr werdet außer Reichweite sein, wenn das passiert.\n\nTut nichts, was Aufmerksamkeit auf Euch lenken könnte.\n\n<Die Aufseherin händigt Euch ein Paket mit mehreren Elementargeräten aus. Das ist genau die Sorte Beweis, die Blutwache Torek sich von Euch erhofft hatte. Ihr solltet ihm die Geräte besser überbringen.>", sourceObjective = "Bringt die Elementargeräte zu Blutwache Torek im Tal der Stärke in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[25348] = { id = 25348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thwarting Twilight's Hammer" }
quests[25349] = { id = 25349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verdrehten Schwestern", description = "Ich habe von Eurem Kampf mit den verderbten Drachen gehört, {name}, und ich möchte Euch für Euren Mut danken... leider habe ich schlechte Nachrichten.\n\nDie Dryaden des Waldes haben sich uns gegenüber immer friedlich verhalten, obwohl sie Verbündete der Nachtelfen sind. Sie wurden jedoch grausam und ihr Geist wurde verdreht, so dass sie nun alle angreifen, die die Wildnis östlich von hier betreten.\n\nIch mache mir um die Sicherheit der Flüchtlinge Sorgen, {name}. Bitte, bereitet den verdrehten Dryaden ein Ende.", sourceObjective = "Tötet 7 verderbte Dryaden.", completion = "Ich danke Euch, {name}, aber die Geschichte Eurer Jagd erfüllt mich mit Sorge. So viele hätten es nicht sein sollen.\n\nDie Krankheit breitet sich weiter aus...", sourceObjectiveStatus = "unverified-source-field" }
quests[25350] = { id = 25350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verschollene Lehrling", description = "{class}, wenn Ihr kurz Zeit hättet...\n\nEiner meiner Studenten hat sich alleine nach Süden zu den Dunkelnebelruinen aufgemacht. Ich habe ihn gewarnt, dass es zu gefährlich sei, aber er war zu aufgeregt, um mir zuzuhören... \n\nEstulan erlaubt nicht, dass wir ihm folgen. Falls Ihr in diese Richtung unterwegs seid, könnt Ihr bitte nach ihm schauen?", sourceObjective = "Sucht nach dem verschollenen Lehrling in den Dunkelnebelruinen.", completion = "<Die Leiche des Lehrlings ist kalt. Er ist schon eine Zeit lang tot.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25351] = { id = 25351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warnt unsere Anführer", description = "Ihr habt Orgrimmar erfolgreich gegen die Bedrohung durch die Schattenhammerkultisten verteidigt, {name}, und das ohne Blutvergießen auf unserer Seite. Der Feind wird nicht lange ruhen. Ich kann mir nicht vorstellen, dass Cho'gall eine Niederlage so einfach hinnimmt.\n\nGarrosh Höllschrei ist bei der Horde für seine Heldenhaftigkeit bekannt und wird wissen, was zu tun ist. Geht ins Tal der Weisheit und sprecht in der Feste Grommash mit ihm. Sagt dem jungen Höllschrei, dass unsere Feinde sich gezeigt haben, und dass wir uns auf ihre Rückkehr vorbereiten müssen.", sourceObjective = "Sprecht mit Garrosh Höllschrei in der Feste Grommash im Tal der Weisheit in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[25352] = { id = 25352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wischt den Sims sauber", description = "Ihr habt in dem Unterschlupf ausgezeichnete Arbeit geleistet, {name}. Während Eurer Abwesenheit habe ich am Schrein gebetet. In meinen Visionen hatte Goldrinn ein aufmerksames Auge auf Euch.\n\nAber wir verharren schon zu lange in Verteidigungsstellung. Es ist Zeit, dem Schattenhammer direkt gegenüberzutreten.\n\nFliegt hinauf auf den Gewittersims und durchkreuzt ihre Vorhaben. Tötet die Sturmrufer und Monstrositäten, die sie entfesseln wollen!", sourceObjective = "Tötet 8 Zwielichtsturmrufer und 5 heulende Rissbewohner.", completion = "Ihr hättet die Schlacht von hier aus sehen sollen! Die Leichen stürzten nur so von den Klippen. Spektakulär!", sourceObjectiveStatus = "unverified-source-field" }
quests[25353] = { id = 25353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blitz in der Flasche", description = "Als ich am Schrein betete, gewährte Goldrinn mir eine weitere Vision. Ich sah Euch entschlossen auf dem Gewittersims stehen, mit Blitzen in Euren Händen. Goldrinn schien der Meinung zu sein, dass dies von größter Wichtigkeit sei, aber ich verstehe nicht, was der Ahn geplant hat...\n\n{name}, geht zum Gewittersims. Der Schattenhammer führt Versuche mit etwas durch, das sich \"Blitzkanal\" nennt. Untersucht diese Kanäle und verwendet dann dieses Totem, um den Geist von Goldrinn zu rufen und zu sehen, was er auf dem Herzen hat...", sourceObjective = "Sammelt ein aufgeladenes Kondensatorglas von einem Blitzkanal des Schattenhammers.", progress = "So treffen wir uns wieder, {class}. Wo Ihr wandelt, hinterlasst Ihr eine Spur aus Angst und Verwirrung.", completion = "Also ist es wahr! Ihr tragt wirklich Blitze in Euren Händen.\n\nIhr seid der Auserwählte, {name}. Ihr werdet mein Champion sein und meine Rache in Reiche tragen, die ich nicht betreten kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[25354] = { id = 25354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wischt den Sims sauber", description = "Der Schrein ist sicher, die Oger sind in Aufruhr. Genug. Es ist an der Zeit, in die Offensive zu gehen.\n\nEtwas Böses braut sich über uns auf dem Gewittersims zusammen. Wir müssen den Zorn der Ahnen entfesseln!\n\nFliegt hinauf zum Gewittersims und vernichtet die Anhänger des Schattenhammers dort. Zerschmettert sie, {name}! Erschlagt ihre Kreaturen und werft ihre Körper den Berg hinab!", sourceObjective = "Tötet 8 Zwielichtsturmrufer und 5 heulende Rissbewohner.", completion = "Beeindruckend, {name}. Sehr beeindruckend.\n\nIn Euch vereint sich die Stärke des Wolfsahnen mit der Weisheit, Eure Kräfte geschickt einzusetzen. Ich salutiere vor Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25355] = { id = 25355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blitz in der Flasche", description = "Während Ihr in dem Unterschlupf wart, gewährte Lo'Gosh mir eine Vision, {name}. Ich sah Euch den Gewittersims entlang spazieren, mit Blitzen in Euren Händen. Die Vision war sehr bewegend. Lo'Gosh schien der Meinung zu sein, dass dies von größter Wichtigkeit sei. Wir dürfen den Ahnen nicht enttäuschen.\n\nDer Schattenhammer führt Versuche mit Geräten durch, die sie \"Blitzkanal\" nennen.\n\nUntersucht diese Kanäle und verwendet dann dieses Totem, um den Geist von Lo'Gosh zu rufen und zu sehen, was er vorhat...", sourceObjective = "Sammelt ein aufgeladenes Kondensatorglas von einem Blitzkanal des Schattenhammers.", progress = "So treffen wir uns wieder, {class}. Wo Ihr wandelt, hinterlasst Ihr eine Spur aus Angst und Verwirrung.", completion = "Also ist es wahr! Ihr tragt wirklich Blitze in Euren Händen.\n\nIhr seid der Auserwählte, {name}. Ihr werdet mein Champion sein und meine Rache in Reiche tragen, die ich nicht betreten kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[25356] = { id = 25356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Gipfel", description = "Wir sind dabei, am Westlichen Gipfel für das ganze Gebiet in Tausend Nadeln Hilfsmaßnahmen in die Wege zu leiten. Shyn wird Euch meinen Windreiter zur Verfügung stellen, so dass Ihr sicher ankommt. Sprecht mit Kanati Grauwolke, sobald Ihr gelandet seid.\n\nIhr müsst Euch beeilen, um Leben retten zu können!", sourceObjective = "Leiht Euch von Shyn einen Windreiter und sprecht mit Kanati Grauwolke am Westlichen Gipfel in Tausend Nadeln.", completion = "Jawn schickt Euch? Gut! Wir brauchen Eure Hilfe, jetzt gleich!", sourceObjectiveStatus = "unverified-source-field" }
quests[25357] = { id = 25357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschafft uns Zeit", description = "So viele gute Männer mussten heute ihr Leben lassen. Ohne Euch wäre diese Zahl sogar noch höher.\n\nIhr habt unseren Dank.\n\nWenn das, was der Schamane sagt, stimmt, dann haben wir keine Zeit zu verlieren. Die Naga durchkämmen die Gewässer auf der Suche nach Überlebenden.\n\nWir sind noch nicht bereit, um zu kämpfen. Ihr müsst uns Zeit für die Vorbereitung verschaffen. Findet die Naga, die uns jagen und verlangsamt ihre Fortschritte.", sourceObjective = "Tötet 8 Räuber des Zin'jatar.", completion = "Hoffen wir einfach, dass Eure Anstrengungen ausreichen, um sie abzulenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[25358] = { id = 25358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nerventonikum", description = "Wie es mir geht, fragt Ihr?\n\nNun, nachdem ich von einem riesigen Seemonster vom Deck unseres Schiffes gerissen wurde und im Meer kurz vor dem Ertrinken stand… gewöhnungsbedürftig, würde ich sagen!\n\nEhrlich gesagt bin ich mit den Nerven total am Ende.\n\nWenn Ihr einige der Vorräte zusammensuchen könntet, die in den umliegenden Schiffswracks umhertreiben, könnte ich sicher etwas aus dem Hut zaubern, was die Lage etwas erträglicher macht.", sourceObjective = "Mack möchte, dass Ihr 5 Stück gesunkene Fracht im Tang'tharwald sammelt.", progress = "Konntet Ihr ein paar der Vorräte sammeln, {race}?", completion = "Ich glaube, wir beide wissen, was in diesen Kisten vor sich geht…\n\nGenau… Ferrrmenntation! Hier, bitte. Mein persönliches Geheimrezept.\n\nKein anderer Kerl würde Euch das hier geben!", sourceObjectiveStatus = "unverified-source-field" }
quests[25359] = { id = 25359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toshes Rache", description = "Ihr habt Toshe in der Dunstlichtkammer getroffen, oder? Er ist einigen der fliehenden Naga zu den Ruinen im Osten gefolgt und hat dann Hilfe angefordert.\n\nSucht so schnell wie möglich in den Ruinen nach Toshe. Wenn Ihr herausfindet, was die Naga wollen, lasst es uns bitte wissen!", sourceObjective = "Sprecht mit Toshe Chaosberster in den Ruinen des Thelseraitempels.", completion = "Ich erinnere mich an Euch. Ihr wart da, als sie uns in der Höhle angegriffen haben.\n\nSchön, Euch an meiner Seite zu wissen, {class}. Seid Ihr bereit für ein wenig Rache?", sourceObjectiveStatus = "unverified-source-field" }
quests[25360] = { id = 25360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Krebs straft man nicht mit Ersäufen", description = "Diese Krebse sind nicht nett. Nicht. Nett.\n\nSams endlose Bohrerei versetzt sie in Aufruhr. Ich weiß aus Erfahrung, dass Sam sich nicht aufhalten lässt, also sollten wir uns um die andere Partei in dieser Angelegenheit kümmern. Meint Ihr nicht auch?", sourceObjective = "Tötet 10 grüne Sandkrebse.", completion = "Ist hier eigentlich alles riesengroß? Ohhh! Da kommt mir eine Idee. Vielleicht gibt es hier ja auch irgendwo ein paar stattliche Seegoblins.\n\nVielen Dank übrigens!", sourceObjectiveStatus = "unverified-source-field" }
quests[25361] = { id = 25361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schimmer für einen neuen Umhang", description = "Grüße, {class}. Ich bin mit meinen Gefährten auf einer Mission für unsere Meister aus Orgrimmar hinunter nach Feralas gereist.\n\nMeine Lebensgefährtin Korrin liebt neue Kleider und daher habe ich vor, ihr einen neuen Umhang zu fertigen, der mit den hauchzarten Flügeln von Feendrachen geschmückt ist. Seid Ihr vielleicht in der Lage, mir zu helfen? Grimmlingflitzer mit prachtvollen Flügeln, wie ich sie will, gibt es westlich vom Camp Mojache.", sourceObjective = "Bringt 10 regenbogenfarbene Grimmlingflitzerflügel zu Krueg Schädelspalter nach Camp Mojache.", progress = "Die Grimmlingflitzer können gefährliche Tierwesen sein, wenn man sie provoziert. Seid vorsichtig im Umgang mit ihnen, {class}. Und passt noch viel mehr auf etwaige Nachtelfen in der Gegend auf. Diese lästigen Narren überfallen einen gern in den Wäldern.\n\nWenn Ihr genug Flügel habt, lasst es mich wissen, ich werde Euch sicher gut entlohnen!", completion = "Wunderbar, {class}! Die sind perfekt. Das sind genug, um einen Umhang für Korrin zu fertigen und vielleicht noch anderes! Danke.\n\nIch hoffe, die Reise war nicht zu gefährlich... Das Gebiet von Feralas ist nicht gerade als harmlos bekannt, aber Ihr habt Euch offensichtlich recht gut geschlagen.\n\nNochmals danke, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25362] = { id = 25362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine grausige Entdeckung", description = "Der Stamm der Grimmtotems! Diese feigen Verräter treiben sich hier immer noch herum, was?\n\nIhr müsst wieder dorthin zurück, {class}. Geht zurück und bringt mir ihre Hörner... haufenweise, wenn möglich. Die Grimmtotems sollten nicht einfach als Kleinigkeit abgestempelt oder unterschätzt werden. Geht zurück und tötet sie. Färbt die Flüsse Feralas' rot mit ihrem dunklen Blut.", sourceObjective = "Bringt 20 Grimmtotemhörner zu Krueg Schädelspalter in Camp Mojache.", progress = "Nehmt meine Worte ernst, {class}, der Stamm der Grimmtotems ist böse. Wenn Ihr herausgefunden habt, wo sie sich aufhalten, so müsst Ihr diesen Ort aufsuchen und ihren Stamm zuerst angreifen... bevor sie in unsere Ländereien eindringen und unsere Dörfer plündern oder unser Land einnehmen.", completion = "Verräter an der Horde und an ihrem eigenen Volk...\n\nIch glaube, sie sind nicht ganz unnütz. Zumindest werden wir feine Trinkhörner daraus machen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[25363] = { id = 25363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg gegen die Waldpfoten", description = "Die Gnolle... sie sind mehr als nur ein Ärgernis. Sie sind eine konstante Bedrohung für die Existenz dieses gesamten Lagers! Es ist unwichtig, ob sie Eingeborene des Feralas sind oder nicht. Wenn wir uns nicht gegen sie wappnen, werden wir uns eines Tages aus dem gesamten Gebiet vertrieben sehen.\n\nDie Gnollangriffe auf das Lager wurden in letzter Zeit heftiger. Wir brauchen Eure Hilfe dabei, ihre Anzahl zu reduzieren. Bringt mir zehn ihrer Mähnen und ich werde Euch stattlich für Eure Mühe entlohnen.\n\nLos!", sourceObjective = "Bringt Hadoken Flinkschreiter im Camp Mojache 10 Mähnen eines Waldpfotengnolls.", progress = "Wir schlagen sie zurück und trotzdem greifen sie weiter an! Irgendjemand oder irgendetwas muss sie zur Raserei treiben... Oh, Ihr seid wieder da, was, {name}? Habt Ihr die Mähnen, die ich benötige, um das Kopfgeld auszahlen zu können?", completion = "Dies zeugt von einem guten Anfang, {name}. Euer Geschick als Soldat verdient Lob.\n\nIhr seid nicht der Einzige, dem ich diesen Auftrag gab. Viele haben bereits vor Euch gegen sie gekämpft und in der Vergangenheit haben unsere Bemühungen sie in Schach gehalten. In letzter Zeit haben jedoch ihre Versuche, nordwärts in unser Einflussgebiet einzudringen, dramatisch zugenommen. Ihre Angriffe sind außerdem wilder geworden... fast als wären sie verzweifelt.\n\nIch habe allerdings einen Plan, {name}, der die Sache mit ihnen ein für alle Mal erledigen sollte...", sourceObjectiveStatus = "unverified-source-field" }
quests[25364] = { id = 25364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlag gegen die Alphas", description = "Die Widerstandsfähigkeit der Gnolle kann sich leider mit ihrer Brutalität und Dummheit messen. Ich habe die Gnolle immer und immer wieder aus unserem Lager vertrieben und sie sind nur aufgrund der Gnade unseres Häuptlings noch nicht ausgerottet.\n\nIm Laufe der Jahre wurde es zu einem wahren Tanz aus Stärke und Dominanz. Wenn sie noch mehr werden und damit drohen, das Lager anzugreifen, müssen wir die Alphas, die stärksten Gnolle, ausmerzen.\n\nDas wird sie zurück in die Wälder vertreiben und uns etwas Frieden einbringen, zumindest, bis sie die erteilte Lektion wieder vergessen haben.", sourceObjective = "Töte 5 Alphas der Waldpfoten.", completion = "Ihr habt getan, was ich von Euch verlangt habe, und dafür zolle ich Euch Ehre. Nehmt dies als kleine Belohnung für Eure Anstrengungen, {name}.\n\nNun, da wir ihre Zahlen geschwächt und ihre Anführer getötet haben, werden es sich die Gnolle zweimal überlegen, unser Lager anzugreifen. Das löst aber unser eigentliches Problem nicht...\n\nEs muss einen Grund geben, warum die Gnolle in einen solchen Wahnsinn verfallen sind. Findet heraus, wo der Ursprung dessen liegt, bevor sie sich neu formieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[25365] = { id = 25365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waldpfotennachforschung", description = "Gnolle sind zwar nicht die Hellsten, aber sie werden bestimmt die Strategie ihrer jüngsten Aktivitäten irgendwo dokumentiert haben. Wenn wir diese Pläne finden würden, hätten wir eine bessere Vorstellung davon, was sie so aufbringt.\n\nIch möchte, dass Ihr zu den Waldpfoten zurückgeht und nach allem sucht, was nach ihren Schlachtplänen aussieht. Irgendwas muss es geben, ihre Angriffe waren einfach zu gut koordiniert. Findet diese Schlachtpläne und kommt zu mir zurück, sobald Ihr sie habt.", sourceObjective = "Findet die Schlachtpläne der Gnolle irgendwo in den Gnoll-Lagern südlich vom Camp Mojache.", completion = "Eine Untersuchung der Karte zeigt, dass es sich um die Schlachtpläne handelt, die Hadoken Flinkschreiter haben will. Zahlreiche Pfeile, die vielleicht Truppenbewegungen darstellen, befinden sich auf der Karte, allerdings scheinen die meisten nach Süden zu deuten, nicht nach Norden, wo das Camp Mojache liegt.\n\nEin anderer Teil der Karte enthält ein Bild von etwas, das man für irgendein großes Insekt halten könnte. Darunter befindet sich eine Art Strichliste. So, wie die Gnolle aussehen, stellt diese vielleicht ihre Verluste gegen das unbekannte Ungeziefer dar...", sourceObjectiveStatus = "unverified-source-field" }
quests[25366] = { id = 25366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlachtpläne", description = "Jetzt, nachdem die Schlachtpläne der Gnolle entdeckt wurden, bleibt nur noch, die Pläne zu Hadoken Flinkschreiter in Camp Mojache zurückzubringen. Vielleicht kann er oder irgendjemand dort besser darauf schließen, was die Gnolle vorhaben.", sourceObjective = "Bringt die Schlachtpläne der Waldpfoten zu Hadoken Flinkschreiter in Camp Mojache.", progress = "Willkommen zurück, {name}. Habt Ihr ein paar nützliche Hinweise auf die Pläne der Gnolle gefunden?", completion = "Ah, das ist genau, was wir gebraucht haben. Auch wenn ich nicht sehr geschickt darin bin, das ganze Gekritzel auf dieser Karte zu entziffern, so habe ich doch in meinem Leben genug Schlachtpläne gesehen, um zu verstehen, was mit den Gnollen passiert. Es sieht so aus, als würden sie derzeit einen Zwei-Fronten-Krieg führen. Einen mit uns... Aber wie es scheint, konzentrieren sie außerdem einen Großteil ihrer Energie auf einen Feind im Süden.\n\nHier läuft mehr, als auf den ersten Blick zu erkennen ist. Wir sollten möglichst bald herausfinden, wer dieser andere Feind ist, dem sie gegenüberstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25367] = { id = 25367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zukk'ash-Plage", description = "Schenken wir unseren angesammelten Erkundungen Glauben, so gehört der Gegner südlich der Gnolle einer insektenartigen Rasse an. Offen gesagt spielt es keine Rolle, solange sie lebendig sind. Wenn sie die Gnolle gegen uns aufhetzen, dann sind sie eine mindestens genauso große Bedrohung - wenn nicht sogar eine größere - als die Gnolle selbst.\n\nDringt tief in das Gebiet vor, in dem die Insekten der Zukk'ash hausen; auch bekannt als Gewundene Tiefe. Dezimiert ihre Anzahl, berichtet mir von Euren Entdeckungen und bringt ihre Knochenpanzer als Beweis Eurer Taten zurück.", sourceObjective = "Bringt Hadoken Flinkschreiter im Camp Mojache in Feralas 20 Zukk'ashknochenpanzer.", progress = "Was macht die Jagd, {name}? Seid Ihr hier, um von Eurem Erfolg zu berichten?", completion = "Gut gemacht, {class}. Obwohl man der hohen Ausbreitung der Zukk'ash mit nichts anderem als einer wahren Invasion entgegentreten kann, so habt Ihr uns doch etwas Zeit verschafft, um eine geeignete Strategie entwickeln zu können.\n\nIch werde dafür sorgen, dass man diese Knochenpanzer untersucht; wir müssen alles über sie herausfinden, bevor wir es mit dem zu tun bekommen, was sich unglücklicherweise als eine schwerwiegendere Angelegenheit als angenommen entwickelt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[25368] = { id = 25368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verinias der Verwachsene", description = "Die anderen Geister und ich werden durch einen grausamen Dämon namens Verinias hier festgehalten. Diese verderbte, stumpfsinnige Bestie frisst unsere Seelen im Verlauf von Jahrtausenden.\n\nMit dem Köder aus Seelen und arkaner Magie, den ihr mir gebracht habt, solltet Ihr ihn anlocken können. Bringt diese konzentrierte Essenz zum toten Baum weit im Norden der Ruinen. Benutzt sie, um Verinias anzulocken, und tötet ihn, um mich endlich zu befreien...", sourceObjective = "Besiegt Verinias den Verwachsenen.", completion = "Ich bin frei... endlich! Oh, es tut so gut, frei zu sein...\n\nOh, Ihr habt es gesehen, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[25369] = { id = 25369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zornstachel", description = "Einer unserer Späher berichtete, dass er bei den Untersuchungen der Gewundenen Tiefe ein riesiges Insekt - viel größer als die anderen gesichteten Insekten - gesehen habe, das durch das verschlungene Gelände umherstreift. Es ist nicht nur größer, es scheint auch eine Art Aura abzusondern, was die anderen Insekten nicht tun. Wir haben ihm einen Namen gegeben - Zornstachel.\n\nEine Untersuchung der Innereien dieser Bestie wäre von unschätzbarem Wert, um herauszufinden, wie man mit dieser Bedrohung am besten umgehen kann. Schneidet seine Sekretionsdrüsen heraus und bringt sie sofort zu mir zurück!", sourceObjective = "Besiegt Zornstachel in der Gewundenen Tiefe und bringt seine Drüsen zu Hadoken Flinkschreiter im Camp Mojache in Feralas zurück.", progress = "Konntet Ihr Zornstachel bereits besiegen?", completion = "Beeindruckend, {class}... sehr beeindruckend! Sollte Zornstachel wirklich eine ihrer stärksten Kreaturen sein, so werden sich die Untersuchungen der Bestie mit der Zeit als sehr wertvoll erweisen. Es liegt nun an mir, sicherzustellen, dass wir uns lange genug verteidigen können, um davon zu profitieren.\n\nBitte nehmt diese Prämie als Dankeszeichen des gesamten Camps an, {name}. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25370] = { id = 25370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entzündete Elemente", description = "Das ist kein natürliches Ereignis, {name}. Dahinter muss eine zwielichtige Macht stecken, die wir nicht bedacht haben.\n\nEs kann sein, dass derjenige, der diese elementaren Störungen verursacht, sich mit böser Magie vor unseren Augen verbirgt.\n\nIhr benötigt die Hilfe der Feendrachen, die sich in der Nähe des Weltenbaums aufhalten. Sie können die Illusionen unserer Feinde durchschauen.\n\nFüttert ihnen Wacholderbeeren, die in der Nähe wachsen, um ihr Vertrauen zu erlangen.", sourceObjective = "Füttert die Feendrachen mit Wacholderbeeren und tötet 4 Zwielichtzünder.", completion = "Das habt Ihr gut gemacht, {name}. Wir dürfen nicht zulassen, dass die Spione des Schattenhammerkults sich so nahe am Weltenbaum aufhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25371] = { id = 25371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der abyssische Ritt", description = "Wenn Ihr Euch in diesem Tang'tharwald fortbewegen wollt, braucht Ihr ein zuverlässiges Reittier. Ich glaube, mir ist etwas Besseres als eine Meeresschildkröte eingefallen. Und es ist auch ganz in der Nähe!\n\nBindet einen Köder an das Seil direkt westlich von uns und steigt dann auf das Seepferdchen, das dadurch angelockt wird.\n\nAber seid gewarnt. Es kann ein hartes Stück Arbeit werden, bis der Wille des Tiers gebrochen ist.", sourceObjective = "Lockt ein abyssisches Seepferdchen an und zähmt es.", progress = "Die Eleganz dieser Tiere ist einfach atemberaubend. Sie werden perfekte Reittiere abgeben.", completion = "Beeindruckend! Ihr seht erschöpft aus. Offensichtlich ließ es sich nicht so einfach zähmen.\n\nMit einem treuen Reittier an Eurer Seite sollte das Leben hier unten gleich viel einfacher sein. Herzlichen Glückwunsch, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25372] = { id = 25372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aessinas Wunder", description = "<Die fingerartigen Zweige an einer von Nordus Gliedmaßen brechen auf. Zum Vorschein kommt ein unberührter, glitzernder Samen.>\n\nDies ist das Herz des Waldes, der Samen des Lebens.\n\nBringt ihn zu Eurem Erzdruiden im Hain von Aessina. Hamuul Runentotem wird sicher wissen, wie seine Macht zu erwecken ist. Ich verspreche Euch, dass der Geist der Wildnis nicht länger schweigen wird. Neues Leben wird aus der Asche des alten erblühen.\n\nDanke Euch, {race}. Meine Zeit hier ist um.", sourceObjective = "Bringt das Herz des Waldes zu Hamuul Runentotem im Hain von Aessina auf dem Hyjal.", progress = "Ich bin mit meinem Latein am Ende, {name}! Aessina schweigt.\n\nHabt Ihr etwas gefunden? Was ist das?", completion = "Das ist der Schlüssel, {name}! Mit den Setzlingen, die Ihr für mich gesammelt, den Tieren, die Ihr auf dem gesamten Hyjal gerettet und dem Herz des Waldes, das Ihr jetzt auch noch entdeckt habt, können wir dieses Land direkt unter den Füßen des Schattenhammerkults wieder verjüngen. Stellt Euch nur ihre erstaunten Gesichter vor, wenn das Leben über das Chaos triumphiert...\n\nIch werde sofort mit der Zeremonie beginnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25373] = { id = 25373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bedrohung vom Hügel", description = "Ich bin stolz darauf, dass Mojache als sicherer Ort in der Wildnis von Feralas gilt, aber auch unserem Camp bleiben Bedrohungen nicht fern. Die Oger der Gordunni haben ein Gebiet in der Nähe des nördlichen Vorgebirges eingenommen und zerstören die Wildnis.\n\nDa unsere Brüder und Schwestern nun hier sind, um sich in Sicherheit zu bringen, kann ich nicht länger zulassen, dass die Oger in der Nähe sind. Begebt Euch nach Norden und vertreibt die Oger.", sourceObjective = "Tötet 5 Hügelwächter der Gordunni.", completion = "Ich danke Euch, {name}. Leider gibt es noch mehr Arbeit zu verrichten, um das Camp weiterhin zu sichern. Hört mir zu.", sourceObjectiveStatus = "unverified-source-field" }
quests[25374] = { id = 25374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sasquatch-Sichtung", description = "Ihr mögt es mit Euren eigenen Augen gesehen zu haben, aber meine Fernläufer berichteten mir von etwas, das mich sehr beunruhigt. Die Gordunni in den Hügeln haben einen riesigen wilden Sasquatch eingefangen.\n\nIch weiß nicht, wie lange sie ihn festgehalten haben, aber es ist sicherlich nicht aus Spaß an der Freude. Ich fürchte, sie wollen das misshandelte Biest auf Camp Mojache loslassen.\n\nTief im Außenposten der Gordunni halten sie den Sasquatch gefangen. Geht dorthin und tötet ihn, {name}.", sourceObjective = "Tötet Großfaust.", completion = "Nun kann ich problemlos ruhen, {name}. Ihr habt unser Lager vor einer schrecklichen Bedrohung gerettet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25375] = { id = 25375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmer zähmen", description = "Die Gordunni sind nicht für das Zähmen von Tieren bekannt. Wenn sie diese Fähigkeit erlernen, so ist das ein Grund, alarmiert zu sein. Nicht nur ist der Sasquatch, den sie gezähmt haben, eine enorme Gefahr für unser Lager - auch die Gordunni, die ihn eingefangen haben, müssen ihre rechte Strafe finden. Wenn wir sie am Leben lassen, können sie einfach einen weiteren Sasquatch einfangen.\n\nTötet die Zähmer der Gordunni und stellt sicher, dass die Oger verstehen, dass wir ihre Anstrengungen nicht tolerieren werden!", sourceObjective = "Tötet 6 Zähmer der Gordunni.", completion = "Gut. Hoffen wir, dass die Oger zumindest schlau genug sind, um zu verstehen, dass wir ihnen mit dieser Aktion eine Nachricht vermitteln wollten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25376] = { id = 25376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gordunnikobalt", description = "Ich bin gerade erst hier in Feralas angekommen und habe gehört, dass die Oger der Gordunni, die die Wildnis hier bewohnen, einige interessante Mineralien besitzen. Keiner weiß, was die so vorhaben, aber sie passen höllisch gut auf dieses Zeug auf! Sie lassen es nicht einfach herumliegen. Oh nein, sie vergraben es, damit Leute wie ich es nicht in die Finger bekommen.\n\nWenn Ihr wollt, gebe ich Euch meine Schaufel. Geht zum Außenposten der Gordunni nördlich von hier und grabt mir etwas Gordunnikobalt aus. Haltet nach blauem Glühen Ausschau und fangt dann dort an zu graben!", sourceObjective = "Sammelt 12 Proben Gordunnikobalt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25377] = { id = 25377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hort der Horde", description = "<Es ist nicht ganz klar, welche Wesen diese zufällig wirkenden Markierungen auf dieses Pergament gekritzelt haben. Bei genauerer Betrachtung scheinen die obskuren Formen Orientierungspunkte zu sein.>\n\n<Ihr lasst Euren Blick über den Meeresboden wandern und seid der Meinung, einige der Punkte zu erkennen, unter anderem ein gesunkenes Schiff in der Nähe. Wenn Ihr mit Eurer Vermutung richtig liegt, sollte sich in der Nähe des Wracks eine Art Schatz befinden.>\n\n<Ihr kommt nicht umhin Euch zu fragen, was diese schuppige, schlangenartige Figur auf der Karte darstellen soll...>", sourceObjective = "Besiegt Akasha, um den Schlüssel zur Kiste der Horde zu bekommen. Öffnet dann mit dem Schlüssel die versunkene Kiste der Horde.", progress = "<Das leicht verrostete Schloss sollte noch funktionieren.>", completion = "<Ihr habt einen verlorenen Schatz entdeckt!>\n\n<Eure Gedanken überschlagen sich geradezu bei dem Gedanken, was sonst noch in der Tiefe des Meers verborgen sein könnte.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25378] = { id = 25378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysondres Aufforderung", description = "Die Drachen der Natur... folgt ihrer Aufforderung, {name}. Wartet nicht. Ysondres Aufforderung, ihr zu helfen, ist sowohl eine große Ehre als auch ein Omen schrecklicher Gefahren.\n\nSie sprach von einem Ort namens Smaragdgipfel. Ein Pfad, weitab der Hauptstraße, führt durch die Untere Wildnis zu den hohen Steinplateaus. Dort befindet sich ein Schrein.\n\nDas Schicksal Feralas' liegt in Euren Händen. Möge die Erdenmutter über Euch wachen.", sourceObjective = "Sprecht mit Ysondre am Smaragdgipfel in der Unteren Wildnis.", completion = "Ihr seid angekommen.\n\nIch schäme mich, Euch diese Aufgabe aufzubürden, {class}, aber ich bin schon zu lange vor ihm auf der Flucht. Taerar muss aufgehalten werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25379] = { id = 25379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taerars Sturz", description = "Smariss und Lethlas sind nicht mehr hier. Nur wir sind noch übrig. Ich kann mich nicht länger verstecken. Alles, was ich als Teil der Brut getan habe... all das Leid, das ich verursacht habe... ich muss es wieder gutmachen.\n\nIch bin noch immer schwach, {name}. Meine wahre Gestalt kann ich noch nicht annehmen, egal, wie sehr ich es versuche. Ich werde jedoch im Kampf an Eurer Seite stehen.\n\nWenn Ihr so weit seid, werde ich Taerar rufen. Er wird der Versuchung nicht widerstehen können, mir die Verderbtheit wieder aufzulegen.", sourceObjective = "Besiegt Taerar.", completion = "Es ist vollbracht.\n\nDas Land, das so sehr gelitten hat, kann nun ruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25380] = { id = 25380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spreading The Word" }
quests[25381] = { id = 25381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer mit… irgendwas bekämpfen", description = "Das Inferno, das vor uns tobt, bildet die Frontlinie zwischen uns und den Streitmächten des Feuerlords. Diese entfesselten Feuerelementare sind anders als alles, was ich je gesehen habe.\n\nKönnt Ihr uns helfen, diese Flut der Zerstörung aufzuhalten? Tötet die tobenden Feuerstürme... bevor sie den Hain von Aessina verschlingen und alle Hoffnung, diesen Berg dereinst zurückzugewinnen, zunichtemachen!", sourceObjective = "Tötet 10 tobende Feuerstürme innerhalb des Infernos.", completion = "Vielen Dank, {name}. Ihr habt uns die Chance gegeben, wieder die Oberhand zu erringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25382] = { id = 25382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rituale unterbrechen", description = "Die Feuerstürme vor uns sind ungebundene Elementare in ihrer reinsten Form. Ich hätte nie gedacht, dass sie außerhalb ihrer Ebene überleben könnten. Nur äußerst geschickte Beschwörer könnten solche Wesen entfesseln.\n\n{name}, begebt Euch in das Inferno und sucht die Zwielichtinfernofürsten. Sie beschwören bestimmt just in diesem Moment Verstärkung. Bringt sie zum Schweigen... für immer!", sourceObjective = "Tötet 6 Zwielichtinfernofürsten im Inferno.", completion = "Tot? Gut!\n\nAber es scheint, als hätten wir noch so viel zu tun… so viele Feuer zu ersticken… so viel Boden zu heilen…\n\nIch hoffe, Ihr bleibt in der Nähe und helft uns dabei, den Hyjal zurückzugewinnen!", sourceObjectiveStatus = "unverified-source-field" }
